	}

	-- ── sound ────────────────────────────────────────────────────────────────────
	--
	-- Every one of these ships INSIDE the Roblox client. No upload, no moderation,
	-- and they cannot be taken down. The old handoff assumed audio was blocked
	-- until someone uploads samples; it is not, and this is the cheapest quality
	-- win on the list.
	Config.Sound = {
		Library = {
			collect  = "rbxasset://sounds/electronicpingshort.wav",
			purchase = "rbxasset://sounds/switch3.wav",
			ui       = "rbxasset://sounds/button.wav",
			impact   = "rbxasset://sounds/impact_water.mp3",
			swing    = "rbxasset://sounds/swoosh.wav",
			rebirth  = "rbxasset://sounds/victory.wav",
			siren    = "rbxasset://sounds/action.wav",
		},
		-- Pool and round-robin; never Instance.new per drop. ~400 live Sound
		-- instances is where audio/video desync starts.
		PoolSize = 8,
		MinRepeatSeconds = 0.04,
		RollOffMaxDistance = 60,   -- so a neighbour's factory doesn't blare at you
		PitchPerCombo = 0.06,
		MaxPitch = 2,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Derived lookups (built once at require time)
	-- ─────────────────────────────────────────────────────────────────────────────

	-- Resolved once, at require time, so every module sees the same numbers.
	-- The widest a plot can get: the centre plus every expansion on both sides.
	-- Derived here, after the land tables exist. Ring packing reserves this — a
	-- plot can max out, so the world has to hold the maxed chord.
	do
		local width = Config.World.PlotSize.X
		for _, side in ipairs({ "left", "right" }) do
			for _, def in ipairs(Config.landRows(side)) do
				width += def.width
			end
		end
		Config.World.PlotMaxWidth = width
	end

	-- Every strip's sub-belt joins Config.BeltPaths here, after the land tables
	-- and the path derivation both exist. Registered data, built parts: the belt
	-- assertions and the drop budget see all eleven paths, and ensureLand builds
	-- each strip's surfaces only when the strip is standing.
	for _, side in ipairs({ "left", "right" }) do
		for _, def in ipairs(Config.landRows(side)) do
			table.insert(Config.BeltPaths, Config.landBeltPath(def))
		end
	end

	Config.World.PlotCount = Config.plotCountFor()
	Config.World.PlotPlacements = Config.plotPlacements(Config.World.PlotCount)
	Config.World.PlotRadius = Config.World.PlotPlacements[1].radius   -- inner ring

	-- invariant: THE MERGE. The five track tables become one Config.Buttons, in
	-- track order, so every consumer downstream iterates a single array.
	--
	-- FACTORY FIRST IS LOAD-BEARING. It leaves every factory button with the same
	-- `order` it had when there was only one table, which is what lets
	-- Tycoon:assign keep replaying installs by sorting on `order` — weapons and
	-- armour land after the whole factory, and because no requirement crosses a
	-- track that ordering is trivially valid. It also keeps the verifier's
	-- "requires must point at an earlier index" check true without modification.
	--
	--   order       position in the merged array. The install-order key. Global.
	--   trackOrder  position within the button's own track. The gating and
	--               display key: it is what the buy-button billboard counts, what
	--               the three-state reveal measures its frontier against, and
	--               what the HUD calls a step.
	-- POWER WENT LAST FOR THIS REASON: appending leaves every existing button's
	-- `order` exactly where it was, so no save's install replay changes sequence.
	--
	-- STRUCTURE DOES NOT GO LAST, AND THAT BREAKS THE CONVENTION DELIBERATELY.
	-- Two things make it the right call anyway. The first is that the convention
	-- is already spent: pulling four rows out of FactoryButtons renumbers the
	-- merged array from index 5 onwards no matter where the new track is spliced
	-- in, so there is no placement that preserves the old `order` values. The
	-- second is that `order` is not a saved field. A profile stores
	-- `owned = { [id] = true }` and Tycoon:assign sorts those ids against the
	-- CURRENT Config every time it replays them, so renumbering costs nothing as
	-- long as ids never change — which is a rule this file already enforces for
	-- other reasons (see the WeaponButtons banner).
	--
	-- design:D-03, design:D-05 — POSITION IN THIS LIST IS THE BEACON.
	-- Config.TrackRank is the TrackOrder index, and both Tycoon:pointAt and the HUD
	-- card rank candidates by (rank, price). Nothing in the verifier can catch a
	-- beacon that points somewhere useless; it is a property of this list and it
	-- has to be decided here.
	Config.TrackOrder = { "factory", "structure", "weapons", "armor", "power", "landL", "landR" }
	Config.Tracks = {
		factory   = Config.FactoryButtons,
		structure = Config.StructureButtons,
		weapons   = Config.WeaponButtons,
		armor     = Config.ArmorButtons,
		power     = Config.PowerButtons,
		landL     = Config.LandLButtons,
		landR     = Config.LandRButtons,
	}

	-- invariant: EVERYTHING THAT IS TRUE OF A TRACK RATHER THAN OF A BUTTON, in
	-- one table.
	--
	-- Adding a fourth track is mostly an exercise in finding the per-track facts,
	-- because they were scattered across five tables in three files and one of them
	-- existed TWICE.
	--
	-- invariant: A MISSING ROW IN EACH FAILS DIFFERENTLY AND NONE FAIL LOUDLY:
	--
	--   where its buttons stand    Layout.Tracks[track] is nil -> indexing nil ->
	--                              buildButtons throws -> the plot fails to build
	--   survives a rebirth         asserted from two places with opposite polarity;
	--                              a missing row FAILS OPEN and the generator
	--                              survives the reset it is supposed to be part of
	--   beacon rank                one copy in Tycoon and one in HUD: the panel
	--                              names one purchase, the beacon glows on another
	--   preview depth              falls back to 3, so a 4-rung ladder previews
	--                              itself entirely from the moment you claim
	--   spine or detour            the verifier prices it as a side track, which is
	--                              wrong for anything that multiplies income
	--
	-- `rank` is not here because it is exactly the TrackOrder index; it is derived
	-- below, which deletes both copies rather than adding a third.
	Config.TrackInfo = {
		-- design:D-05, via #125 — THE PURCHASE SURFACE IS THREE CATEGORIES:
		-- conveyor (everything that makes the line earn more), generator, and
		-- plot (the ground and the shell on it). `category` is the label a pad
		-- and the HUD card wear; the TRACKS underneath stay chains, because the
		-- chains carry the orderings geometry forces (no L2 without L1) and the
		-- categories are what the player is asked to hold. The cabinet tracks
		-- keep their own labels until #108 moves them off the plot.
		--
		-- The conveyor outranks everything by TrackOrder POSITION, which is what
		-- "the conveyor's label sits highest" already means to the card and the
		-- beacon: both rank by (TrackRank, price).
		factory = { label = "CONVEYOR", category = "conveyor", preview = 3, keepOnRebirth = false, paced = "spine", furniture = "misc" },
		-- invariant: THE SHELL. Three of its five facts are FORCED rather than
		-- chosen; preview is design:D-03.
		--
		-- paced = "spine" because the detour model prices a track against a curve it
		-- does not change AND assumes you can decline it. The second half stopped
		-- being true when a cross-ladder gate once put `roof` between the player and the
		-- mezzanine. Measured as a detour the build reads 46 minutes against a
		-- MIN_TOTAL_MINUTES of 45 — the four purchases did not stop happening, the
		-- verifier just stopped counting them.
		--
		-- keepOnRebirth = false because rebirth() clears self.machines
		-- unconditionally and the wall ring lives there, not in self.props. Set it
		-- true and the ring is destroyed while `owned.walls` survives, so
		-- refreshButtons hides a pad for a building that is not standing and the
		-- plot has no shell for the rest of that owner's life. The cabinets get to
		-- be true because their props are the exempt folder; this track is not.
		--
		-- furniture = "misc" because these four already have hand-placed positions
		-- in Layout.MiscButtons and they are exactly the case that table is for:
		-- unrelated purchases in a line down an open floor.
		--
		-- preview = 2 is the one real choice. At 3 the whole four-rung track is
		-- visible from the moment you claim, which puts a 690000 price tag on the
		-- plot at minute three; at 2 the roof stays hidden until `gates` is owned.
		structure = { label = "PLOT", category = "plot", preview = 2, keepOnRebirth = false, paced = "spine", furniture = "misc" },
		weapons = { label = "WEAPONS", category = "weapons", preview = 2, keepOnRebirth = true,  paced = "side",  furniture = "cabinet" },
		armor   = { label = "ARMORY",  category = "armor",  preview = 2, keepOnRebirth = true,  paced = "side",  furniture = "cabinet" },
		-- The generator multiplies exactly what a rebirth resets. Keeping it would
		-- stack x2 on top of MultiplierPerRebirth 2.25 for an effective 4.5x first
		-- prestige, which makes the asserted CostGrowth/MultiplierPerRebirth ratio
		-- a lie about the real pacing. It is plot machinery, same class as a
		-- dropper — not a monotone character grant like a bat or a suit of armour.
		-- preview = 0, and it is load-bearing rather than a taste call. All four
		-- rungs resolve to ONE pad position, so a preview pad would be built inside
		-- the lit one. At 2 it put three pads in the yard on a plot that had bought
		-- none of them, which is most of what "the generator is visually intrusive
		-- on plot creation" was about. The verifier asserts this is 0.
		power   = { label = "GENERATOR", category = "generator", preview = 0, keepOnRebirth = false, paced = "spine", furniture = "yard" },
		-- design:D-03 — LAND SURVIVES A REBIRTH (#88, via #78: rebirth raises the
		-- ceiling on what can exist; the ground is the ceiling). keepOnRebirth
		-- works here because ensureLand rebuilds the slabs from `owned` on the
		-- refreshButtons beat, so land needs no exempt props folder — the
		-- cabinet-only argument the verifier states is widened to name land.
		--
		-- preview = 0 for the power track's reason, which is load-bearing: every
		-- rung of a side resolves to ONE pedestal, so a preview pad would be built
		-- inside the lit one.
		--
		-- paced = "spine": land is the plot's own growth and the simulation walks
		-- it; priced as a detour it would stop counting toward the build.
		landL   = { label = "PLOT", category = "plot", preview = 0, keepOnRebirth = true, paced = "spine", furniture = "land" },
		landR   = { label = "PLOT", category = "plot", preview = 0, keepOnRebirth = true, paced = "spine", furniture = "land" },
	}

	Config.TrackLabel = {}
	Config.TrackRank = {}
	for rank, track in ipairs(Config.TrackOrder) do
		Config.TrackRank[track] = rank
		Config.TrackLabel[track] = Config.TrackInfo[track] and Config.TrackInfo[track].label or track:upper()
	end

	-- design:D-03 — WHAT A WHOLE LADDER WAITS ON, why the cabinets arrive on a gate
	-- rather than on claim, and why `structure` opens on the very first rung.
	--
	-- invariant: DELIBERATELY NOT A `requires` ON EACH TRACK'S FIRST RUNG. The
	-- loader derives requirements within a track and the verifier asserts none ever
	-- crosses one; that guarantee is worth more than the convenience, and a
	-- precondition on an entire ladder is a different kind of thing from a link
	-- inside one.
	--
	-- A GATE MUST NAME A FACTORY BUTTON — asserted, because a side track gating a
	-- side track can deadlock. The gate is STICKY, so a rebirth that wipes
	-- `dropper3` does not take both cabinets with it.
	--
	-- `structure` opening on the first rung is also what keeps the "no side track's
	-- first rung is affordable at spawn" check meaningful for it — you cannot buy
	-- walls at minute zero at any price.
	Config.TrackUnlock = {
		weapons = "dropper3", armor = "dropper3", structure = "dropper1",
		-- Land opens once the centre pad is earning properly: mid-build, when the
		-- line is established and the next thing to want is room.
		landL = "dropper5", landR = "dropper5",
	}

	-- design:D-03, via #125 — Config.ButtonUnlock and its helper are GONE. The
	-- one entry ever shipped gated the mezzanine on the roof, and the mechanism
	-- retired with the storey system: three categories and per-track chains need
	-- nothing that gates ONE purchase across a ladder, and a mechanism nothing
	-- uses is a mechanism that silently rots. TrackUnlock is the surviving gate
	-- shape — a precondition on a whole ladder — and the reachability fixpoint
	-- still counts it.

	--- Whether `track` is open on a plot that owns `owned`.
	---
	--- STICKY, and derived rather than stored. Owning any rung of a track counts as
	--- having it open, which matters because rebirth wipes the factory (and so the
	--- gate button) while deliberately keeping weapons and armour. Without that
	--- clause a rebirth would make the cabinets vanish while the shelf displays and
	--- the granted bat survived — a cabinet-shaped hole with a bat floating in it.
	--- Derived this way it costs no new persisted field and no migration.
	function Config.trackUnlocked(track: string, owned): boolean
		local gate = Config.TrackUnlock[track]
		if not gate or owned[gate] then
			return true
		end
		for _, def in ipairs(Config.Tracks[track] or {}) do
			if owned[def.id] then
				return true
			end
		end
		return false
	end

	--- Whether one row survives a rebirth. Per-track via TrackInfo, with one
	--- carve-out: on a land track the GROUND survives (design:D-03 — rebirth
	--- raises the ceiling, and the ground is the ceiling) while the machines
	--- standing on it reset — an upgrader that outlived the wipe would multiply
	--- the next build from minute zero, which is the generator's argument one
	--- track over.
	function Config.keptOnRebirth(def): boolean
		local info = Config.TrackInfo[def.track]
		if not info or not info.keepOnRebirth then
			return false
		end
		if info.furniture == "land" then
			return def.kind == "Land"
		end
		return true
	end

	Config.Buttons = {}
	Config.ButtonById = {}
	for _, track in ipairs(Config.TrackOrder) do
		local defs = Config.Tracks[track]
		for trackOrder, def in ipairs(defs) do
			def.track = track
			def.trackOrder = trackOrder
			-- A track IS a chain, so derive the link rather than restating it.
			-- This is what makes "no requirement crosses a track" a property of
			-- the loader instead of a promise the verifier has to police, and it
			-- deletes the single most error-prone field in this file for every
			-- row that doesn't genuinely need something unusual.
			if def.requires == nil and trackOrder > 1 then
				def.requires = defs[trackOrder - 1].id
			end
			table.insert(Config.Buttons, def)
			def.order = #Config.Buttons
			Config.ButtonById[def.id] = def
		end
	end

	-- design:D-05, via #125 — the category ordinals the pads and the card count
	-- by. A pad says "PLOT 20/34" rather than naming one of three internal
	-- chains: the categories are what the player is asked to hold, and the
	-- count's width is the category's whole size.
	Config.CategoryCount = {}
	for _, def in ipairs(Config.Buttons) do
		local info = Config.TrackInfo[def.track]
		def.category = info and info.category or def.track
		Config.CategoryCount[def.category] = (Config.CategoryCount[def.category] or 0) + 1
		def.categoryOrder = Config.CategoryCount[def.category]
	end

	--- Every price on the SPINE, highest first.
	---
	--- The spine is what the progression simulation walks and what the build time
	--- is measured against. Weapons and armour are deliberately excluded: they are
	--- side tracks, priced against the factory rather than pacing it, and a bat
	--- costing more than a dropper is the entire point of that split.
	---
	--- READS `paced` RATHER THAN NAMING THE TRACKS. It listed factory and power by
	--- hand while its own comment argued from "what the simulation walks", which is
	--- two statements of one fact with a list as the tiebreak — the same shape as
	--- the two hand-kept copies of the beacon ranking that TrackRank replaced. A
	--- third spine track had to be added in two places or it would have been
	--- half-counted, and the half that got missed would have been this one, silently,
	--- because nothing downstream of here fails loudly on a slightly short list.
	function Config.spinePricesDescending(): { number }
		local prices = {}
		for _, track in ipairs(Config.TrackOrder) do
			if Config.TrackInfo[track].paced == "spine" then
				for _, def in ipairs(Config.Tracks[track]) do
					table.insert(prices, def.price)
				end
			end
		end
		table.sort(prices, function(a, b)
			return a > b
		end)
		return prices
	end

	--- What the rebirth pad costs: the price of the PriceRung-th most expensive
	--- thing on the spine, rounded to two significant figures.
	---
	--- The rounding is not cosmetic. Unrounded, this would change in its ninth
	--- digit every time anyone touched an unrelated dropper, and every one of those
	--- changes would rewrite build/ and land in a diff as noise.
	function Config.rebirthBaseCost(): number
		local prices = Config.spinePricesDescending()
		local raw = prices[Config.Rebirth.PriceRung] or prices[#prices] or 0
		if raw <= 0 then
			return 0
		end
		local magnitude = 10 ^ (math.floor(math.log(raw, 10)) - 1)
		return math.floor(raw / magnitude + 0.5) * magnitude
	end

	Config.Rebirth.BaseCost = Config.rebirthBaseCost()

	Config.BatById = {}
	for tier, def in ipairs(Config.Bats) do
		def.tier = tier
		Config.BatById[def.id] = def
	end

	Config.ArmorById = {}
	for tier, def in ipairs(Config.Armor.Tiers) do
		def.tier = tier
		Config.ArmorById[def.id] = def
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- invariant: ANALYTICS
	--
	-- The schema lives in Config for the same reason the fonts do: the verifier can
	-- only check what it can see, and EVERY limit below is a silent counting
	-- failure. Roblox does not error, warn, or drop a line in the output window when
	-- you exceed one — the event is accepted, the field is discarded, and the chart
	-- you look at three weeks later is simply wrong in a way that looks like data.
	--
	-- The four that bite, verbatim from the reference:
	--
	--   * THREE custom fields per event, and only under the keys
	--     Enum.AnalyticsCustomFieldKeys.CustomField01/02/03. A fourth key of any
	--     name is ignored.
	--   * Field values must be STRINGS. A number is dropped.
	--   * 8,000 unique combinations of field values PER EXPERIENCE — one shared
	--     budget across every event, not a per-event allowance. This is the limit
	--     that a well-meaning "let's also break it down by button" blows through,
	--     and it is why nothing continuous is ever allowed into a field.
	--   * 100 custom event names per experience.
	--
	-- The consequence of the third is the single rule this schema is built on:
	-- EVERYTHING CONTINUOUS GOES IN `value`, NEVER IN A FIELD. `value` is a real
	-- number Roblox aggregates for you and costs nothing from the combination
	-- budget. A field is a facet, and a facet with a thousand values is a facet you
	-- cannot afford.
	-- ─────────────────────────────────────────────────────────────────────────────

	Config.Analytics = {
		-- The kill switch. Analytics.lua ANDs this with "is a server" and "is not
		-- Studio", because the API silently no-ops on the client and in Studio.
		Enabled = true,

		-- Platform limits. Named rather than written as literals in the verifier so
		-- the failure message can quote the number that was exceeded.
		MaxFields = 3,
		-- Raised from 40 when the land rows joined the milestone set (48, then 72
		-- when #109 put each strip's machines on the chain): the set is every
		-- button plus "none", and the binding budget is MaxCombinations, which is
		-- asserted separately.
		MaxFieldValues = 72,      -- widest single value set we will allow ourselves
		MaxCombinations = 8000,
		MaxEventNames = 100,
		MaxEconomySkus = 100,
		MaxTransactionTypes = 20,
		MaxCurrencyTypes = 5,

		-- THE RATE LIMIT IS NOT IN THE REFERENCE DOCS. A Roblox staff forum post
		-- gives roughly 120 + 20 x CCU service calls per minute; nothing in the
		-- published documentation confirms it. Treat these two numbers as a design
		-- budget we chose, not as a contract Roblox has stated — if the real ceiling
		-- is lower we will find out by losing events silently, which is exactly why
		-- Analytics.lua counts its drops instead of assuming there are none.
		RateBurst = 120,
		RatePerPlayerPerMinute = 20,

		-- How long the join waits for the client's platform before giving up and
		-- logging "unknown". There is no edit path on a logged event, so a session
		-- that fires early with a wrong platform is wrong forever.
		HelloTimeoutSeconds = 10,
		-- Last N events kept in memory for `Analytics.tail`, which is the only way
		-- to answer "what did the server actually send" without a dashboard.
		TailSize = 64,

		-- The currency name Roblox aggregates economy events under. One currency, so
		-- the 5-type limit is not in play, but it is named so the verifier can see it.
		Currency = "Tung",
		-- Every transaction type we ever pass to LogEconomyEvent. Limit is 20 per
		-- experience and they are strings, so a typo is a new type, not an error.
		TransactionTypes = { "Shop", "Gameplay", "TimedReward" },
	}

	--- A FIELD is a named, CLOSED set of strings. Two shapes:
	---
	---   * a plain `values` list — a label per state, e.g. clipped / within_cap
	---   * `bounds` + `values`, which is a bucket ladder: #values == #bounds + 1,
	---     and Analytics.bucket() picks values[i] for the first bound the number
	---     does not exceed. Bounds are what turn a continuous quantity into a facet
	---     the combination budget can afford; the quantity itself still goes in
	---     `value`, so no resolution is lost.
	---
	--- Two of these are DERIVED from the ladder below rather than hand-listed, so a
	--- new button cannot drift out of the schema: a hand-typed button list would go
	--- stale the first time someone adds a dropper, and the symptom would be a
	--- purchase logged under the wrong facet rather than an error.
	Config.Analytics.Fields = {
		platform = { values = { "desktop", "mobile", "tablet", "console", "vr", "unknown" } },
		-- `unknown` is the sixth entry because GetJoinData is a network call in a
		-- pcall: it can fail, and a failed read is not a direct join.
		entry = { values = { "direct", "follow_friend", "referral", "teleport", "private_server", "unknown" } },

		sessionIndex = {
			bounds = { 1, 2, 5, 20 },
			values = { "1", "2", "3-5", "6-20", "21+" },
		},
		-- Time to the first purchase of the account. The first two buckets are
		-- narrow on purpose: onboarding either lands in the first minute or it is a
		-- different conversation.
		secondsBucket = {
			bounds = { 30, 60, 180, 600 },
			values = { "0-30s", "30-60s", "1-3m", "3-10m", "10m+" },
		},
		rebirthBand = {
			bounds = { 0, 1, 3, 9 },
			values = { "0", "1", "2-3", "4-9", "10+" },
		},
		-- Time away, both for `returned` and for what the offline vault was paying
		-- against. The 6-24h bucket straddles Offline.CapHours 8 deliberately: the
		-- `clipped` field on offline_claim is what answers the cap question, and
		-- splitting this set to answer it twice would cost combinations for nothing.
		awayBucket = {
			bounds = { 600, 3600, 21600, 86400, 604800 },
			values = { "<10m", "10m-1h", "1-6h", "6-24h", "1-7d", "7d+" },
		},
		-- Minutes into the session when a rebirth landed.
		minutesBucket = {
			bounds = { 10, 30, 60, 180, 480 },
			values = { "<10m", "10-30m", "30-60m", "1-3h", "3-8h", "8h+" },
		},
		clipped = { values = { "within_cap", "clipped" } },
		friendCount = {
			bounds = { 1, 2, 3 },
			values = { "1", "2", "3", "4+" },
		},
		serverKind = { values = { "public", "private" } },

		-- DERIVED below from Config.Tracks.factory and Config.Buttons.
		buttonId = { values = {} },
		milestone = { values = {} },
	}

	-- The factory track and nothing else: a first purchase is an ONBOARDING signal,
	-- and no other track can supply one. Adding a factory rung widens this set by
	-- one and the verifier re-prices the combination budget on the next run.
	--
	-- THE REASON HAS BEEN RESTATED TWICE AND WAS WRONG BOTH TIMES IN BETWEEN. It
	-- read "the side tracks are gated behind floor2 forty minutes in" for a round
	-- after round 8 moved that gate to `dropper3` at minute three. The durable form
	-- is the one that does not name a button: EVERY other track is gated on a
	-- factory rung (Config.TrackUnlock), and `power`, which is not, opens at 14000
	-- against a StartingCash of 100. So the first purchase is always a factory
	-- purchase, and it is `dropper1` in particular.
	--
	-- This set SHRANK by four when the shell moved to its own track, which is the
	-- derivation working: walls/gates/windows/roof were never reachable as a first
	-- buy and were costing combinations for a state that could not happen.
	for _, def in ipairs(Config.Tracks.factory) do
		table.insert(Config.Analytics.Fields.buttonId.values, def.id)
	end

	-- Every button on every track, plus "none" for a session that bought nothing.
	-- "How far did they get before they stopped" is the whole question `session_end`
	-- exists to answer, and it has to be able to answer "nowhere".
	for _, def in ipairs(Config.Buttons) do
		table.insert(Config.Analytics.Fields.milestone.values, def.id)
	end
	table.insert(Config.Analytics.Fields.milestone.values, "none")

	--- THE SEVEN EVENTS. `value` is prose: it names the number, because the number
	--- is the part a dashboard cannot label for you.
	---
	--- `friends_in_server` is deliberately NOT called `friend_bonus_active`. There
	--- is no friend bonus in this game, and an event named after a feature that does
	--- not exist reads as a bug six months from now. Named for what it measures, it
	--- also gives the co-play baseline BEFORE any bonus ships, which is the only
	--- thing that will make the bonus's effect readable.
	Config.Analytics.Events = {
		{
			name = "session_start", value = "session number",
			fields = { "platform", "entry", "sessionIndex" },
		},
		{
			name = "first_button_purchased", value = "seconds since join",
			fields = { "platform", "buttonId", "secondsBucket" },
		},
		{
			name = "session_end", value = "session seconds",
			fields = { "platform", "milestone", "rebirthBand" },
		},
		{
			name = "returned", value = "hours since last seen",
			fields = { "platform", "awayBucket", "sessionIndex" },
		},
		{
			name = "rebirth", value = "rebirth number",
			fields = { "platform", "minutesBucket", "rebirthBand" },
		},
		{
			name = "offline_claim", value = "Tung claimed",
			fields = { "platform", "clipped", "awayBucket" },
		},
		{
			name = "friends_in_server", value = "friends in server",
			fields = { "platform", "friendCount", "serverKind" },
		},
	}

	--- What this schema costs of the 8,000 combinations the whole EXPERIENCE gets.
	---
	--- Summed across events rather than maxed, because the budget is shared: two
	--- events with disjoint facets each spend their own product. One function, called
	--- by the verifier, by the specs and by anyone about to add a field, so nobody
	--- has to re-derive the arithmetic and get it wrong in the optimistic direction.
	function Config.analyticsCombinations(): number
		local total = 0
		for _, event in ipairs(Config.Analytics.Events) do
			local product = 1
			for _, field in ipairs(event.fields) do
				local set = Config.Analytics.Fields[field]
				product *= set and #set.values or 0
			end
			total += product
		end
		return total
	end

	--- Where a side track's buy button `slot` stands, in plot-local coordinates.
	---
	--- Component arithmetic on purpose: tools/verify_config.lua stubs Vector3 as a
	--- plain table with no operators, so anything that adds or scales a Vector3 at
	--- require time takes the whole verifier down.

	function Config.trackButtonPosition(track: string, slot: number): Vector3
		local t = Config.Layout.Tracks[track]
		return Vector3.new(t.buttonX, 0, t.firstZ + (slot - 1) * t.spacing)
	end

	--- The cabinet body behind that column: centre, then size. Its long axis is Z,
	--- running the length of its own button column with four studs of overhang at
	--- each end so the case reads as containing the buttons rather than starting
	--- level with them.
	function Config.trackCabinet(track: string): (Vector3, Vector3)
		local t = Config.Layout.Tracks[track]
		local length = (t.slots - 1) * t.spacing + 8
		return Vector3.new(t.cabinetX, 0,
				t.firstZ + (t.slots - 1) * t.spacing / 2),
			Vector3.new(t.depth, t.height, length)
	end

	--- Shelf slot `slot` on the cabinet — where the display for a bought tier
	--- stands, so the case visibly fills up as you climb the track.
	function Config.trackShelfPosition(track: string, slot: number): Vector3
		local t = Config.Layout.Tracks[track]
		return Vector3.new(t.cabinetX, 5,
			t.firstZ + (slot - 1) * t.spacing)
	end

	function Config.requirementsOf(def)
		local req = def.requires
		if req == nil then
			return {}
		elseif type(req) == "string" then
			return { req }
		end
		return req
	end

	return Config
end


__MODULES["Fx"] = function()
	--[[
		Fx.lua — every particle / light / sound effect in the game, built from code.

		No asset uploads required: all textures use Roblox's built-in default
		particle sprites (rbxasset://textures/particles/*) which ship with the
		engine and are always available, so nothing here can be moderated away.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Sound = Req("Sound")

	local TweenService = game:GetService("TweenService")
	local Debris = game:GetService("Debris")

	local Fx = {}

	-- Built-in engine textures. These are shipped in the Roblox client itself.
	local SPARKLE = "rbxasset://textures/particles/sparkles_main.dds"
	local SMOKE   = "rbxasset://textures/particles/smoke_main.dds"
	local FIRE    = "rbxasset://textures/particles/fire_main.dds"

	local function emitter(part: BasePart, props: { [string]: any }): ParticleEmitter
		local p = Instance.new("ParticleEmitter")
		p.Name = "TungFx"
		p.Texture = SPARKLE
		p.Lifetime = NumberRange.new(0.4, 0.9)
		p.Rate = 12
		p.Speed = NumberRange.new(1, 3)
		p.SpreadAngle = Vector2.new(180, 180)
		p.LightEmission = 0.6
		p.LockedToPart = false
		for key, value in pairs(props) do
			(p :: any)[key] = value
		end
		p.Parent = part
		return p
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Per-variant recipes
	-- ─────────────────────────────────────────────────────────────────────────────

	local RECIPES: { [string]: (BasePart, any) -> () } = {}

	RECIPES.none = function() end

	RECIPES.sparkle = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(variant.accent, variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.5),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 14,
			Lifetime = NumberRange.new(0.4, 0.8),
		})
	end

	RECIPES.dust = function(part, variant)
		emitter(part, {
			Texture = SMOKE,
			Color = ColorSequence.new(variant.wood),
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.5),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Size = NumberSequence.new(1.2),
			Rate = 8,
			Speed = NumberRange.new(0.5, 1.5),
			LightEmission = 0,
		})
	end

	RECIPES.embers = function(part, variant)
		emitter(part, {
			Texture = FIRE,
			Color = ColorSequence.new(Color3.fromRGB(255, 160, 60), variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.8),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 22,
			Speed = NumberRange.new(2, 5),
			Acceleration = Vector3.new(0, 6, 0),
			Lifetime = NumberRange.new(0.5, 1.1),
			LightEmission = 1,
		})
	end

	RECIPES.pulse = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.4, 1.1),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 26,
			Speed = NumberRange.new(0.5, 2),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.void = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(Color3.fromRGB(160, 80, 255), Color3.fromRGB(30, 0, 60)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1.4),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 24,
			Speed = NumberRange.new(-3, -1),  -- negative = sucked inward
			Lifetime = NumberRange.new(0.6, 1.2),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.eclipse = function(part, variant)
		RECIPES.embers(part, variant)
		emitter(part, {
			Color = ColorSequence.new(Color3.fromRGB(255, 150, 40)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.5, 2.4),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.4),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Rate = 6,
			Speed = NumberRange.new(0, 0.5),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.galaxy = function(part, _variant)
		emitter(part, {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.fromRGB(120, 160, 255)),
				ColorSequenceKeypoint.new(0.5, Color3.fromRGB(200, 120, 255)),
				ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
			}),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.7),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 40,
			Speed = NumberRange.new(1, 4),
			Rotation = NumberRange.new(0, 360),
			RotSpeed = NumberRange.new(-180, 180),
			Lifetime = NumberRange.new(0.7, 1.4),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.infinity = function(part, variant)
		RECIPES.galaxy(part, variant)
		emitter(part, {
			Texture = FIRE,
			Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 210, 90)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 2.2),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 30,
			Speed = NumberRange.new(3, 8),
			SpreadAngle = Vector2.new(180, 180),
			Lifetime = NumberRange.new(0.4, 0.9),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	--- Applies a variant's signature effect + light to a part.
	--- `opts.light = false` skips the PointLight — important for conveyor drops,
	--- since Roblox only renders a limited number of lights and hundreds of
	--- glowing drops would starve the lights that actually matter.
	--- `opts.rateScale` thins out the particles for the same reason.
	function Fx.applyVariant(part: BasePart, variant, opts)
		opts = opts or {}
		local recipe = RECIPES[variant.fx or "none"] or RECIPES.none
		recipe(part, variant)

		if opts.rateScale then
			for _, child in ipairs(part:GetChildren()) do
				if child:IsA("ParticleEmitter") then
					child.Rate = math.max(1, child.Rate * opts.rateScale)
				end
			end
		end

		if variant.light and opts.light ~= false then
			local light = Instance.new("PointLight")
			light.Color = variant.light.color
			light.Range = variant.light.range
			light.Brightness = variant.light.brightness
			light.Shadows = false
			light.Parent = part
		end
	end

	--- The ceiling fixture that lights an enclosed storey.
	---
	--- A SurfaceLight on the BOTTOM face, and both halves of that are load-bearing.
	--- Shadows are off — at eight fixtures per storey across ten plots they have to
	--- be — and a Roblox light with shadows off ignores occluders entirely, so a
	--- PointLight hung under the mezzanine deck would shine straight through a
	--- 1.6-stud slab and light the floor above it. A SurfaceLight emits from one
	--- face into a cone and cannot leak upward at all.
	---
	--- Every number comes from Config.Structure.Lights, because tools/verify_config
	--- reads Config and nothing else: a brightness typed here is a brightness no
	--- check can ever see.
	function Fx.ceilingLight(part: BasePart)
		local spec = Config.Structure.Lights
		local light = Instance.new("SurfaceLight")
		light.Face = Enum.NormalId.Bottom
		light.Range = spec.range
		light.Brightness = spec.brightness
		light.Angle = spec.angle
		light.Shadows = false
		light.Parent = part
		return light
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- One-shot effects
	-- ─────────────────────────────────────────────────────────────────────────────

	--- A quick expanding ring. Used for purchases, upgrades and heavy hits.
	function Fx.burst(position: Vector3, color: Color3, size: number?, parent: Instance?)
		local ring = Instance.new("Part")
		ring.Name = "TungBurst"
		ring.Shape = Enum.PartType.Ball
		ring.Anchored = true
		ring.CanCollide = false
		ring.CanQuery = false
		ring.CanTouch = false
		ring.CastShadow = false
		ring.Material = Enum.Material.Neon
		ring.Color = color
		ring.Transparency = 0.25
		ring.Size = Vector3.one * 0.5
		ring.CFrame = CFrame.new(position)
		ring.Parent = parent or workspace

		local goalSize = Vector3.one * (size or 10)
		TweenService:Create(ring, TweenInfo.new(0.45, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			Size = goalSize,
			Transparency = 1,
		}):Play()
		Debris:AddItem(ring, 0.6)
	end

	--- Floating "+1.2K" text.
	function Fx.floatingText(position: Vector3, text: string, color: Color3, parent: Instance?)
		local anchor = Instance.new("Part")
		anchor.Name = "TungFloatText"
		anchor.Anchored = true
		anchor.CanCollide = false
		anchor.CanQuery = false
		anchor.CanTouch = false
		anchor.Transparency = 1
		anchor.Size = Vector3.one * 0.2
		anchor.CFrame = CFrame.new(position)
		anchor.Parent = parent or workspace

		-- ONE OF THE TWO THINGS IN THIS GAME THAT DRAWS THROUGH WALLS. A damage
		-- number you can't see is a hit you didn't feel land, and the thing most
		-- likely to be standing between you and it is the enemy you just hit. (The
		-- other is enemy nameplates, and those are Roblox's own — it draws them on
		-- top whatever we ask for.)
		local billboard = Style.billboard(anchor, {
			name = "FloatText", width = 6, height = 2,
			distance = "prop", alwaysOnTop = true,
		})

		local label = Style.text(billboard, { text = text, color = color })

		TweenService:Create(anchor, TweenInfo.new(1.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			CFrame = CFrame.new(position + Vector3.new(0, 6, 0)),
		}):Play()
		TweenService:Create(label, TweenInfo.new(1.1), { TextTransparency = 1, TextStrokeTransparency = 1 }):Play()
		Debris:AddItem(anchor, 1.3)
	end

	--- Procedural "tung" percussion. Generated from engine default sound ids that
	--- ship with Studio, pitched by index so each variant sounds different.
	---
	--- With Config.Prototypes.Sound on, both of these hand off to Sound.lua, which
	--- plays them out of a fixed pool instead of allocating one Sound per drop.
	--- With it off they keep the shipped behaviour exactly, down to the volumes
	--- and roll-off distances — the prototype has to be switchable, not merged.
	local TUNG_SOUND = "rbxasset://sounds/electronicpingshort.wav"
	local IMPACT_SOUND = "rbxasset://sounds/impact_water.mp3"

	function Fx.tung(part: BasePart, pitch: number?, volume: number?)
		if Config.Prototypes.Sound then
			Sound.playAt("collect", part, { pitch = pitch, volume = volume or 0.35 })
			return
		end
		local sound = Instance.new("Sound")
		sound.SoundId = TUNG_SOUND
		sound.PlaybackSpeed = pitch or 1
		sound.Volume = volume or 0.35
		sound.RollOffMaxDistance = 90
		sound.Parent = part
		sound:Play()
		Debris:AddItem(sound, 3)
	end

	function Fx.impact(part: BasePart, pitch: number?)
		if Config.Prototypes.Sound then
			-- combo is passed by callers that track one (bat swings); without it
			-- this is just the pitch they asked for
			Sound.playAt("impact", part, { pitch = pitch, volume = 0.6, rollOff = 120 })
			return
		end
		local sound = Instance.new("Sound")
		sound.SoundId = IMPACT_SOUND
		sound.PlaybackSpeed = pitch or 1
		sound.Volume = 0.6
		sound.RollOffMaxDistance = 120
		sound.Parent = part
		sound:Play()
		Debris:AddItem(sound, 3)
	end

	--- Named passthroughs for the rest of the library, so callers outside Fx do
	--- not have to know the asset keys. All no-ops with the flag off.
	function Fx.sfx(name: string, position: Vector3?, opts)
		if not Config.Prototypes.Sound then
			return
		end
		if position then
			Sound.playAt(name, position, opts)
		else
			Sound.play(name, opts)
		end
	end

	--- Trail between two attachments, used on bats mid-swing.
	function Fx.trail(a0: Attachment, a1: Attachment, color: Color3): Trail
		local trail = Instance.new("Trail")
		trail.Attachment0 = a0
		trail.Attachment1 = a1
		trail.Color = ColorSequence.new(color)
		trail.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.1),
			NumberSequenceKeypoint.new(1, 1),
		})
		trail.Lifetime = 0.22
		trail.LightEmission = 0.8
		trail.MinLength = 0.1
		trail.Enabled = false
		trail.Parent = a0.Parent
		return trail
	end

	return Fx
end


__MODULES["Net"] = function()
	--[[
		Net.lua — lazily creates and hands out the project's RemoteEvents.

		Server calls Net.event("Name") and it is created on demand.
		Client calls Net.event("Name") and it waits for it.
	]]

	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RunService = game:GetService("RunService")

	local Net = {}

	local FOLDER_NAME = "TungNet"

	local folder: Folder
	if RunService:IsServer() then
		folder = ReplicatedStorage:FindFirstChild(FOLDER_NAME) :: Folder
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = FOLDER_NAME
			folder.Parent = ReplicatedStorage
		end
	else
		folder = ReplicatedStorage:WaitForChild(FOLDER_NAME, 30) :: Folder
	end

	-- Every remote the game uses. Declared up front so the client never races.
	Net.NAMES = {
		"Notify",        -- S->C  { kind, title, body, color }
		"Stats",         -- S->C  { cash, rebirths, kills, batTier, armorTier, multiplier, owned, rebirthCost }
		"PlotAssigned",  -- S->C  plotIndex
		"Purchased",     -- S->C  { id, name, price }
		-- phase: idle | resting | warning | spawning | active | clear.
		-- `seconds` is sent ONCE per phase and counted down client-side.
		"WaveState",     -- S->C  { phase, wave, remaining, total, seconds, boss, forced,
		                 --         bossHp, bossMaxHp, bossScale }
		"SwingFx",       -- S->C  { character, combo, duration } — play a swing on that rig
		"HitFeedback",   -- S->C  { damage, crit, killed, position }
		"Knockback",     -- S->C  impulse Vector3, applied by the owning client
		"RequestRebirth",-- C->S
		"RequestReset",  -- C->S  (leave plot)
		"Sfx",           -- S->C  { name, position }
		-- The friend bonus. Deliberately NOT folded into the Stats payload above:
		-- Economy would then have to require SocialService, which is exactly the
		-- dependency Economy.setMultiplierHook exists to prevent. A separate remote
		-- keeps Economy ignorant, and lets this one carry friend NAMES for the toast.
		"SocialState",   -- S->C  { friends, cap, bonus, multiplier, names }
		"RequestInvite", -- C->S  (no payload; it exists for the server-side cooldown)

		-- PROTOTYPES (see Config.Prototypes). Declared here rather than created on
		-- demand so a client that connects with a flag off still resolves them and
		-- never sits in WaitForChild for 30 seconds.
		"UpgradeState",   -- S->C  { levels = {id = level}, costs = {id = price} }
		"RequestUpgrade", -- C->S  upgrade id
		"UseUtility",     -- C->S  (fire the equipped utility)
		"SessionState",   -- S->C  { daily, playtime, boost, offline }
		"RequestClaim",   -- C->S  { kind = "daily" | "playtime" | "offline", index }
		"RequestBoost",   -- C->S

		-- Roblox exposes no server-side device API, so the ONE thing the client has
		-- to tell us about itself is which kind of machine it is. Declared here
		-- rather than created on demand for the reason above: a client that resolves
		-- it lazily sits in WaitForChild, and this one fires in the first seconds of
		-- a session. Validated server-side against Config.Analytics.Fields.platform
		-- and used as a chart label only — it gates nothing.
		"ClientHello",    -- C->S  { platform = string }
	}

	if RunService:IsServer() then
		for _, name in ipairs(Net.NAMES) do
			if not folder:FindFirstChild(name) then
				local remote = Instance.new("RemoteEvent")
				remote.Name = name
				remote.Parent = folder
			end
		end
	end

	local cache: { [string]: RemoteEvent } = {}

	function Net.event(name: string): RemoteEvent
		local hit = cache[name]
		if hit then
			return hit
		end
		local remote
		if RunService:IsServer() then
			remote = folder:FindFirstChild(name)
			if not remote then
				remote = Instance.new("RemoteEvent")
				remote.Name = name
				remote.Parent = folder
			end
		else
			remote = folder:WaitForChild(name, 30)
			if not remote then
				error(("[Tung] remote %q never replicated"):format(name))
			end
		end
		cache[name] = remote
		return remote
	end

	return Net
end


__MODULES["ShopMath"] = function()
	--[[
		ShopMath.lua — shared maths and lookups for the two player-progression
		prototypes: the upgrade shop (Config.PlayerUpgrades) and the utility slot
		(Config.Utilities).

		IT WAS CALLED Utilities.lua, next to Util.lua, and the two are unrelated:
		Util is number formatting and welding, this is price curves. Two modules a
		letter apart, neither named after what it does, is a wrong guess every time
		somebody new opens the tree — and this one is reached from exactly two files
		while Util is reached from fifteen. Renamed for the reader, not for tidiness.

		Why one module for both: the server prices a purchase and the client draws
		the price, and if those two ever disagree the shop shows a number you can't
		actually buy at. Every formula the UI needs lives here so there is exactly
		one copy of it, and the server treats its own result as the authority.

		Pure data + maths only — no Instances, no remotes, so it is safe on both
		sides of the wire.
	]]

	local Req = __Req
	local Config = Req("Config")

	local ShopMath = {}

	export type UpgradeDef = {
		id: string, name: string, stat: string, levels: number,
		base: number, perLevel: number, cost: number, costGrowth: number,
		blurb: string,
	}

	export type UtilityDef = {
		id: string, name: string, verb: string,
		duration: number, cooldown: number, price: number, requires: string,
	}

	-- Config ships the two tables as arrays; index them once here rather than
	-- looping over four entries on every remote call.
	ShopMath.UpgradeById = {} :: { [string]: UpgradeDef }
	for _, def in ipairs(Config.PlayerUpgrades) do
		ShopMath.UpgradeById[def.id] = def
	end

	ShopMath.UtilityById = {} :: { [string]: UtilityDef }
	for _, def in ipairs(Config.Utilities) do
		ShopMath.UtilityById[def.id] = def
	end

	--- The value of an upgrade's stat at `level` (level 0 = unpurchased).
	function ShopMath.valueAt(def, level: number): number
		return def.base + def.perLevel * math.clamp(level, 0, def.levels)
	end

	--- What the NEXT level costs, or nil at max. Geometric, per IDEAS.md §7:
	--- x4–6 per tier for a ~7-level premium stat.
	function ShopMath.costAt(def, level: number): number?
		if level >= def.levels then
			return nil
		end
		return math.floor(def.cost * (def.costGrowth ^ level))
	end

	--- Trims trailing zeros so "23.10 studs/sec" reads as "23.1 studs/sec" without
	--- turning the payout multiplier into a bare "x1".
	function ShopMath.formatValue(value: number): string
		if value == math.floor(value) then
			return tostring(math.floor(value))
		end
		local s = ("%.2f"):format(value)
		s = s:gsub("0$", "")
		return s
	end

	--- The blurb with the current stat value substituted in. Some blurbs (the
	--- autocollect toggle) have no placeholder, hence the find().
	function ShopMath.describe(def, level: number): string
		if not def.blurb:find("%%s") then
			return def.blurb
		end
		return def.blurb:format(ShopMath.formatValue(ShopMath.valueAt(def, level)))
	end

	--- What each verb actually does, for the shop row. Config.Utilities carries a
	--- verb and a duration but no player-facing description, and the wording has
	--- to match what UpgradeService's implementation really does — so it lives
	--- next to the maths rather than in the UI, where it would be one more thing
	--- that can quietly stop being true.
	local VERB_BLURB = {
		freeze = "Roots nearby raiders for %ds. They can still swing.",
		shove = "Heavy knockback on everything nearby. No damage.",
		decoy = "Drops a decoy for %ds. PROTOTYPE: raiders ignore it.",
	}

	function ShopMath.verbBlurb(def): string
		local blurb = VERB_BLURB[def.verb] or ("%s nearby."):format(def.verb)
		if blurb:find("%%d") then
			return blurb:format(def.duration)
		end
		return blurb
	end

	--- Utilities are one-shot purchases, so their "level" is 0 or 1 and their cost
	--- is flat. Expressed through the same two functions as the upgrades so the
	--- shop UI can draw both kinds of row with one code path.
	function ShopMath.utilityCostAt(def, level: number): number?
		if level >= 1 then
			return nil
		end
		return def.price
	end

	return ShopMath
end


__MODULES["Sound"] = function()
	--[[
		Sound.lua — the whole audio layer, built on sounds that ship INSIDE the
		Roblox client (`rbxasset://sounds/*`). No upload, no moderation queue, and
		nothing here can 404 or be taken down, which is the same contract every
		other asset in this project honours.

		Three rules drive the shape of this file, and all three are failure modes
		rather than preferences:

		  * **Never `Instance.new` a Sound per event.** Around 400 live Sound
		    instances is where audio/video desync starts, and ten plots dropping a
		    Tung every 0.4s reach that inside a minute. Every sound name owns a
		    fixed pool of `Config.Sound.PoolSize` instances handed out round-robin;
		    the 9th overlapping play steals the oldest slot instead of allocating.
		  * **Server-side sound spam can take a 20-player server down.** Anything
		    the client can play for itself, it plays for itself — the server never
		    broadcasts audio it does not have to.
		  * **Everything goes through one SoundGroup.** "There is no way to turn
		    the sound off" is a recurring playtest complaint, and with a group the
		    fix is one property write.

		Gated on `Config.Prototypes.Sound`: with the flag off every entry point
		returns nil before touching a single instance, so a shipping build is
		byte-for-byte the audio it has today.
	]]

	local Req = __Req
	local Config = Req("Config")

	local RunService = game:GetService("RunService")
	local SoundService = game:GetService("SoundService")

	local Sound = {}

	local CFG = Config.Sound
	local GROUP_NAME = "TungSfx"
	local ANCHOR_FOLDER = "TungSfxAnchors"

	local IS_SERVER = RunService:IsServer()

	export type PlayOptions = {
		pitch: number?,       -- multiplies the resolved playback speed
		volume: number?,
		combo: number?,       -- pitch-stacks: 1 + combo * PitchPerCombo, clamped
		rollOff: number?,     -- override RollOffMaxDistance for one play
		looped: boolean?,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lazily-built plumbing
	-- ─────────────────────────────────────────────────────────────────────────────

	local group: SoundGroup? = nil
	local groupVolume = 1

	--- One group for every sound in the game. Found-or-created rather than always
	--- created: the server's group replicates, so a client that arrives late must
	--- adopt the existing one instead of stacking a second.
	local function soundGroup(): SoundGroup
		if group and group.Parent then
			return group :: SoundGroup
		end
		local existing = SoundService:FindFirstChild(GROUP_NAME)
		if existing and existing:IsA("SoundGroup") then
			group = existing :: SoundGroup
		else
			local made = Instance.new("SoundGroup")
			made.Name = GROUP_NAME
			made.Volume = groupVolume
			made.Parent = SoundService
			group = made
		end
		return group :: SoundGroup
	end

	local anchorFolder: Folder? = nil

	local function anchors(): Folder
		if anchorFolder and anchorFolder.Parent then
			return anchorFolder :: Folder
		end
		local existing = workspace:FindFirstChild(ANCHOR_FOLDER)
		if existing then
			anchorFolder = existing :: Folder
		else
			local made = Instance.new("Folder")
			made.Name = ANCHOR_FOLDER
			made.Parent = workspace
			anchorFolder = made
		end
		return anchorFolder :: Folder
	end

	--- A pooled positional sound needs somewhere permanent to live. Parenting it
	--- to the thing that made the noise looks obvious and is wrong: a drop being
	--- collected destroys its children, so the pool would quietly decay back into
	--- allocate-per-drop. Each slot owns a 0.2-stud invisible anchor we teleport
	--- to the emitter instead.
	local function newAnchor(): BasePart
		local part = Instance.new("Part")
		part.Name = "SfxAnchor"
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Locked = true
		part.Transparency = 1
		part.Size = Vector3.one * 0.2
		part.Parent = anchors()
		return part
	end

	type Slot = { sound: Sound, anchor: BasePart? }
	type Pool = { slots: { Slot }, cursor: number, lastPlay: number }

	local pools: { [string]: Pool } = {}
	local warned: { [string]: boolean } = {}

	local function buildPool(name: string, assetId: string, positional: boolean): Pool
		local pool: Pool = { slots = {}, cursor = 0, lastPlay = -math.huge }
		for i = 1, math.max(1, CFG.PoolSize) do
			local sound = Instance.new("Sound")
			sound.Name = ("%s_%d"):format(name, i)
			sound.SoundId = assetId
			sound.SoundGroup = soundGroup()
			sound.Volume = 0.5
			if positional then
				local anchor = newAnchor()
				-- RollOffMaxDistance is the whole reason a neighbour's factory
				-- does not blare across the ring: a plot is ~120 studs wide and
				-- the gap between plots is 44, so 60 studs dies out at the fence.
				sound.RollOffMode = Enum.RollOffMode.InverseTapered
				sound.RollOffMinDistance = 8
				sound.RollOffMaxDistance = CFG.RollOffMaxDistance
				sound.Parent = anchor
				table.insert(pool.slots, { sound = sound, anchor = anchor })
			else
				-- parented to a non-BasePart, a Sound is 2D and plays at full
				-- volume wherever the listener is — which is what UI wants
				sound.Parent = SoundService
				table.insert(pool.slots, { sound = sound })
			end
		end
		return pool
	end

	--- Round-robin, with the repeat-rate guard applied per sound NAME. Two drops
	--- landing in the same frame is one audible "tung", not two stacked into a
	--- clipped mush — and the guard is what stops a ten-plot server machine-gunning
	--- the same 40ms sample.
	---
	--- os.clock() here, not os.time(): this is a sub-second monotonic timer, and
	--- os.time() has 1-second resolution which would silence everything.
	local function acquire(name: string, positional: boolean): Slot?
		local assetId = CFG.Library[name]
		if not assetId then
			if not warned[name] then
				warned[name] = true
				warn(("[Tung] no sound named %q in Config.Sound.Library"):format(name))
			end
			return nil
		end

		local key = name .. (positional and "@3d" or "@2d")
		local pool = pools[key]
		if not pool then
			pool = buildPool(name, assetId, positional)
			pools[key] = pool
		end

		local now = os.clock()
		if now - pool.lastPlay < CFG.MinRepeatSeconds then
			return nil
		end
		pool.lastPlay = now

		pool.cursor = (pool.cursor % #pool.slots) + 1
		return pool.slots[pool.cursor]
	end

	--- `PlaybackSpeed = min(1 + combo * PitchPerCombo, MaxPitch)` — the combo
	--- pitch-stack. Rising pitch on a repeated hit is the single cheapest way to
	--- make one stock sample read as a streak instead of a stutter.
	function Sound.comboPitch(combo: number?): number
		return math.min(1 + (combo or 0) * CFG.PitchPerCombo, CFG.MaxPitch)
	end

	local function resolvePitch(opts: PlayOptions?): number
		local speed = (opts and opts.pitch) or 1
		if opts and opts.combo then
			speed *= Sound.comboPitch(opts.combo)
		end
		return math.clamp(speed, 0.2, CFG.MaxPitch)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public
	-- ─────────────────────────────────────────────────────────────────────────────

	--- 2D one-shot: UI clicks, stings, anything that is not happening at a place.
	--- On the client this goes through `PlayLocalSound`, which never replicates and
	--- never asks the server for anything.
	function Sound.play(name: string, opts: PlayOptions?): Sound?
		if not Config.Prototypes.Sound then
			return nil
		end
		local slot = acquire(name, false)
		if not slot then
			return nil
		end

		local sound = slot.sound
		sound.PlaybackSpeed = resolvePitch(opts)
		sound.Volume = (opts and opts.volume) or 0.5
		sound.Looped = (opts and opts.looped) or false

		if IS_SERVER then
			sound:Play()
		else
			SoundService:PlayLocalSound(sound)
		end
		return sound
	end

	--- Positional one-shot at a part or a raw position.
	---
	--- Called from the server this replicates a *bounded* number of instances
	--- (PoolSize per name for the whole server), which is the point: the shipped
	--- code allocates one Sound per drop and lets Debris clean up after it.
	function Sound.playAt(name: string, where: any, opts: PlayOptions?): Sound?
		if not Config.Prototypes.Sound then
			return nil
		end

		local position: Vector3?
		if typeof(where) == "Vector3" then
			position = where
		elseif typeof(where) == "Instance" and where:IsA("BasePart") then
			position = where.Position
		elseif typeof(where) == "CFrame" then
			position = where.Position
		end
		if not position then
			return nil
		end

		local slot = acquire(name, true)
		if not slot or not slot.anchor then
			return nil
		end

		local anchor = slot.anchor :: BasePart
		anchor.CFrame = CFrame.new(position)

		local sound = slot.sound
		sound.PlaybackSpeed = resolvePitch(opts)
		sound.Volume = (opts and opts.volume) or 0.5
		sound.Looped = (opts and opts.looped) or false
		sound.RollOffMaxDistance = (opts and opts.rollOff) or CFG.RollOffMaxDistance
		sound:Play()
		return sound
	end

	--- The mute toggle a HUD checkbox would drive. Volume rather than
	--- SoundGroup.Parent = nil so a muted group still tracks playback position.
	function Sound.setVolume(volume: number)
		groupVolume = math.clamp(volume, 0, 1)
		if Config.Prototypes.Sound then
			soundGroup().Volume = groupVolume
		end
	end

	function Sound.setMuted(muted: boolean)
		Sound.setVolume(muted and 0 or 1)
	end

	function Sound.group(): SoundGroup?
		if not Config.Prototypes.Sound then
			return nil
		end
		return soundGroup()
	end

	--- Warms every pool up front so the first drop of the session is not the one
	--- that pays for eight instantiations. Safe to call more than once.
	function Sound.preload(positional: boolean?)
		if not Config.Prototypes.Sound then
			return
		end
		for name, assetId in pairs(CFG.Library) do
			local wants3d = positional ~= false
			local key = name .. (wants3d and "@3d" or "@2d")
			if not pools[key] then
				pools[key] = buildPool(name, assetId, wants3d)
			end
		end
	end

	return Sound
end


__MODULES["Style"] = function()
	--[[
		Style.lua — the one place that turns Config.Style into instances.

		Every label this game draws, in the world and on the screen, comes through
		here. Before it existed each site picked its own font, its own outline and
		its own view distance as it was written, which is how the plot ended up
		using three fonts, six outline settings and eleven view distances from 90
		studs to 1200 — none of them chosen against each other.

		WHY A MODULE AND NOT JUST CONSTANTS. Constants would have fixed the values
		and left the *shape* free: one site setting LightInfluence and the next
		forgetting, one billboard with StudsOffsetWorldSpace and the next without.
		The point of a builder is that the site cannot leave a field out. What a
		caller still gets to choose is what a label IS — its size, its colour, and
		how far away it stops mattering — and nothing else.

		tools/verify.py fails the build if `Enum.Font`, `TextStrokeTransparency` or
		`MaxDistance` appears anywhere in src/ outside this file. That lint is the
		only reason this stays true; the state it replaced is what happens without
		one.
	]]

	local Req = __Req
	local Config = Req("Config")

	local S = Config.Style

	local Style = {}

	--- The two faces. `title` is the display face — names, headlines, anything you
	--- read at a glance from across the plot. `body` is everything else: prices,
	--- step counters, blurbs, the small print on a panel.
	Style.Font = {
		title = (Enum.Font :: any)[S.TitleFont],
		body  = (Enum.Font :: any)[S.BodyFont],
	}

	--- Named view distances, resolved. Anything that wants a number reads
	--- `Style.distance("prop")` rather than writing 220.
	function Style.distance(tier: string): number
		local value = S.Distance[tier]
		if not value then
			-- Loud rather than silent: a typo'd tier that fell back to a default
			-- would be a label that quietly renders at the wrong range forever,
			-- which is exactly the class of bug this module exists to end.
			error(("[Tung] unknown view-distance tier %q; expected one of machine/prop/plot/world"):format(tostring(tier)), 2)
		end
		return value
	end

	--- A world-space label anchor.
	---
	---   width, height   studs (BillboardGui scale maps 1:1 to studs)
	---   distance        a Config.Style.Distance key
	---   offset          studs straight up from the adornee, world-space
	---   alwaysOnTop     draws through geometry. Two things in this game are
	---                   allowed it — damage numbers and enemy nameplates — and
	---                   the nameplates are Roblox's own. Everything else obeys
	---                   walls, which is the whole point of hiding behind one.
	function Style.billboard(parent: Instance, opts): BillboardGui
		local gui = Instance.new("BillboardGui")
		gui.Name = opts.name or "Label"
		gui.Size = UDim2.fromScale(opts.width, opts.height)
		gui.MaxDistance = Style.distance(opts.distance)
		gui.AlwaysOnTop = opts.alwaysOnTop == true
		gui.LightInfluence = S.LightInfluence
		if opts.offset then
			gui.StudsOffsetWorldSpace = Vector3.new(0, opts.offset, 0)
		end
		gui.Parent = parent
		return gui
	end

	--- A line of world text. Defaults to filling its billboard, because most of
	--- them hold exactly one line; the buy button is the only label with enough to
	--- say that it needs its own layout.
	function Style.text(parent: Instance, opts): TextLabel
		local label = Instance.new("TextLabel")
		label.Name = opts.name or "Text"
		label.BackgroundTransparency = 1
		label.Size = opts.size or UDim2.fromScale(1, 1)
		if opts.position then
			label.Position = opts.position
		end
		label.Font = (opts.weight == "body") and Style.Font.body or Style.Font.title
		label.Text = opts.text or ""
		label.TextColor3 = opts.color or Color3.new(1, 1, 1)
		label.TextStrokeTransparency = S.StrokeTransparency
		label.TextStrokeColor3 = S.StrokeColor
		label.TextScaled = opts.scaled ~= false
		label.Parent = parent
		return label
	end

	--- Retunes a live billboard's view distance. Some labels have more than one
	--- voice — a locked buy button drops out of sight sooner than a buyable one —
	--- and the tier still has to come from here rather than from a number written
	--- at the call site.
	function Style.setDistance(gui: BillboardGui, tier: string)
		gui.MaxDistance = Style.distance(tier)
	end

	--- Fades a label, outline included.
	---
	--- The outline has to fade WITH the text or a dimmed label keeps its hard dark
	--- edge and ends up reading as MORE contrasty than the bright one it was
	--- supposed to recede behind — which is the exact opposite of the point.
	function Style.fade(label: TextLabel, alpha: number)
		label.TextTransparency = alpha
		label.TextStrokeTransparency = alpha + (1 - alpha) * S.StrokeTransparency
	end

	return Style
end


__MODULES["SwingAnim"] = function()
	--[[
		SwingAnim.lua — procedural melee swings that move the CHARACTER, not just
		the bat.

		The old swing tweened Tool.Grip, which is the offset of the engine's
		RightGrip weld. That rotates the bat inside a motionless hand: the arm, the
		shoulders and the torso never moved, so a "swing" read as the bat pivoting
		in mid-air. This drives the rig itself.

		WHY NOT AN AnimationTrack? Roblox animations are uploaded assets. This game
		has zero uploads by design (see README), and an animation asset would also
		have to be authored twice, once per rig type. Writing the joints directly
		costs one PreSimulation connection and works on R6 and R15 from the same
		pose data.

		THE FOUR THINGS THAT MAKE THIS WORK
		  1. We write Motor6D.Transform, not C0. Transform is the channel the
		     Animator itself writes into every frame, so it composes with the
		     playing animation and leaves the rig's rest pose (C0/C1) untouched.
		     Stop writing and Roblox's own Animate script takes the limb straight
		     back over, with no restore step. (C0 is also becoming read-only on
		     character joints under the Avatar Joint Upgrade, so it is a dead end.)
		  2. We write on RunService.PreSimulation, and ONLY there. This is the part
		     that was wrong for the whole first version of this file, which used
		     BindToRenderStep at Enum.RenderPriority.Character + 1 and was
		     consequently a no-op: nothing moved, ever.

		     BindToRenderStep binds to PreRender, and the frame goes

		         PreRender -> render -> PreAnimation -> [Animator writes joint
		         transforms] -> PreSimulation -> [transforms applied to parts]

		     so a PreRender write is overwritten by the Animator later in the same
		     frame and is discarded before it ever reaches a part. PreSimulation is
		     the last Luau event before the batch apply. Enum.RenderPriority is a
		     bare ordering constant with no engine meaning; `Character = 300` does
		     not mark where characters are animated, and reading it that way is
		     what produced the bug. The reasoning was imported from the camera
		     shake in CombatClient, where binding at `RenderPriority.Camera + 1`
		     genuinely does work — because the default camera module really IS a
		     BindToRenderStep binding, so priority ordering applies to it. The
		     Animator is not, so no priority value could ever have won.
		  3. We MULTIPLY into Transform rather than assigning it. Assigning throws
		     away the Animator's pose for that joint, so the arm snaps out of the
		     tool-hold with no blending.
		  4. Poses are expressed in TORSO space, not joint space, and converted per
		     joint by conjugating with that joint's own C0 rotation:

		         Transform = C0.Rotation:Inverse() * Q * C0.Rotation

		     R6 and R15 bake completely different rotations into their shoulder C0s,
		     so a raw joint-space angle that raises an R15 arm forwards swings an R6
		     arm out sideways. Conjugating makes "rotate the arm 90 degrees about
		     the torso's X axis" mean the same thing on both rigs, and means this
		     file never has to know a single rig convention.

		This module runs on the CLIENT ONLY. Motor6D.Transform is not replicated, so
		every client plays every swing locally: the attacker predicts their own on
		Tool.Activated and everyone else plays it from the SwingFx broadcast.
	]]

	local Req = __Req
	local Config = Req("Config")

	local RunService = game:GetService("RunService")

	local SwingAnim = {}

	local ZERO = Vector3.new(0, 0, 0)

	--- invariant: poses are ABSOLUTE torso-space Euler angles in DEGREES —
	--- (pitch, yaw, roll),
	--- measured from the rig's bind pose — arms hanging straight down. They are not
	--- offsets from whatever the character is currently doing; see applyJoint.
	---
	--- THE FRAME. A Roblox character faces -Z, up is +Y, and +X is its own right.
	--- Both arms hang along -Y from their shoulder. So for an ARM joint:
	---
	---   pitch    0 = straight down      90 = straight forward (horizontal)
	---          180 = straight up       270 = straight back
	---   roll   +90 = out to the character's RIGHT      -90 = out to its LEFT
	---   yaw        = twist about the limb's own length; unused here
	---
	--- Note "right" and "left" are the CHARACTER's, in torso space, for BOTH arms.
	--- The rotation is applied to each arm identically, so a symmetric two-handed
	--- pose needs the off-arm's roll to reach ACROSS: positive roll swings the left
	--- arm toward the body's centre, negative swings it away. Mirroring the sign,
	--- which is the intuitive thing to write, splays the arms apart instead.
	---
	--- ORDER MATTERS. CFrame.Angles(x, y, z) composes as Rx * Ry * Rz, so roll is
	--- applied first, in the hanging frame, and pitch then swings the result up and
	--- over. Reading a pair as "point the arm here, then rotate to there" is why
	--- these are easier to reason about as a cone than as a direction vector.
	---
	--- For a TORSO joint (R15 Waist, R6 RootJoint) the same frame applies to the
	--- upper body: pitch +  leans BACK, pitch - leans forward, yaw + turns left.
	---
	--- Choreography lives here rather than in Config because these are drawings,
	--- not balance. The timings that damage depends on ARE in Config. design:D-05.
	local function P(arm: Vector3, offArm: Vector3?, torso: Vector3?)
		return { arm = arm, offArm = offArm or ZERO, torso = torso or ZERO }
	end

	--- One entry per step of the combo. `Config.Combat.SwingSteps` (which is
	--- ComboMaxStacks + 1, because stack 0 is the first swing of a chain) selects
	--- among these. Alternating the direction is what makes a chain read as a combo
	--- instead of as the same swing played four times.
	SwingAnim.SWINGS = {
		{   -- 1. overhead diagonal: cocked over the right shoulder, chopped down
		    -- across to the left hip. Wind-up pitch is past 180 so the arm goes up
		    -- and BEHIND; at 158 it was raised up and in FRONT, which reads as
		    -- presenting the bat rather than loading a swing.
			name = "diagonal",
			windUp = P(Vector3.new(200, 0, 35), Vector3.new(30, 0, -20), Vector3.new(-6, -30, 0)),
			strike = P(Vector3.new(60, 0, -45), Vector3.new(20, 0, 25), Vector3.new(-10, 28, 0)),
		},
		{   -- 2. backhand: low across the body on the left, swept up to the right
			name = "backhand",
			windUp = P(Vector3.new(55, 0, -70), Vector3.new(25, 0, 20), Vector3.new(-4, 32, 0)),
			strike = P(Vector3.new(120, 0, 60), Vector3.new(30, 0, -18), Vector3.new(-8, -30, 0)),
		},
		{   -- 3. flat horizontal sweep, right to left. Pitch stays near 90 through
		    -- both poses so the arm stays level and only the roll travels — that
		    -- level arc is what distinguishes it from the two diagonals.
			name = "sweep",
			windUp = P(Vector3.new(95, 0, 75), Vector3.new(28, 0, -22), Vector3.new(0, -38, 0)),
			strike = P(Vector3.new(95, 0, -68), Vector3.new(35, 0, 28), Vector3.new(0, 36, 0)),
		},
		{   -- 4. two-handed overhead slam; the combo finisher. Both rolls are
		    -- POSITIVE so the off-arm reaches across to meet the bat instead of
		    -- splaying away from it, and the torso leans back to load and forward
		    -- to land — which is the way round it was NOT written the first time.
			name = "slam",
			windUp = P(Vector3.new(196, 0, 6), Vector3.new(190, 0, 20), Vector3.new(16, 0, 0)),
			strike = P(Vector3.new(58, 0, -4), Vector3.new(62, 0, 12), Vector3.new(-24, 0, 0)),
		},
	}

	-- The server times its hitbox off the same two numbers, so they live in Config
	-- rather than here. If they drift apart, damage stops landing when the bat
	-- looks like it connects.
	assert(#SwingAnim.SWINGS == Config.Combat.SwingSteps,
		"SwingAnim.SWINGS and Config.Combat.SwingSteps disagree; the combo would repeat a swing")

	local active: { [Model]: any } = {}
	local bound = false

	local function angles(v: Vector3): CFrame
		return CFrame.Angles(math.rad(v.X), math.rad(v.Y), math.rad(v.Z))
	end

	--- A rig joint by name, accepting either class.
	---
	--- R15 characters are migrating from Motor6D to AnimationConstraint under the
	--- Avatar Joint Upgrade, and an upgraded character has no Motor6Ds at all.
	--- Both classes carry C0 and Transform with the same meaning, so everything
	--- here works on either — but only if we never filter on Motor6D. The name
	--- check alone is not enough: a rig part can hold other children.
	local function jointNamed(parent: Instance?, name: string): Instance?
		local joint = parent and parent:FindFirstChild(name)
		if joint and (joint:IsA("Motor6D") or joint:IsA("AnimationConstraint")) then
			return joint
		end
		return nil
	end

	--- The rig's joints, found once per swing. Named by ROLE, not by rig: `arm` is
	--- whichever joint swings the weapon, `torso` is whichever one twists the upper
	--- body relative to the root.
	local function jointsFor(character: Model)
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return nil
		end

		if humanoid.RigType == Enum.HumanoidRigType.R6 then
			local torso = character:FindFirstChild("Torso")
			local rootPart = character:FindFirstChild("HumanoidRootPart")
			if not torso or not rootPart then
				return nil
			end
			return {
				arm = jointNamed(torso, "Right Shoulder"),
				offArm = jointNamed(torso, "Left Shoulder"),
				-- R6 has no waist. RootJoint is the closest thing, but it is NOT
				-- equivalent to R15's Waist: every R6 limb joint hangs off the
				-- Torso, so a rotation here carries the arms, legs and head with
				-- it and the character bodily leans rather than twisting at the
				-- middle. Yaw only, and damped — that reads as a shoulder turn,
				-- where the raw pose would swing the feet.
				torso = jointNamed(rootPart, "RootJoint"),
				torsoGain = Vector3.new(0, 0.45, 0),
			}
		end

		local rightUpperArm = character:FindFirstChild("RightUpperArm")
		local leftUpperArm = character:FindFirstChild("LeftUpperArm")
		local upperTorso = character:FindFirstChild("UpperTorso")
		return {
			arm = jointNamed(rightUpperArm, "RightShoulder"),
			offArm = jointNamed(leftUpperArm, "LeftShoulder"),
			-- R15's Waist joins LowerTorso to UpperTorso, so the legs stay put
			torso = jointNamed(upperTorso, "Waist"),
			torsoGain = Vector3.new(1, 1, 1),
		}
	end

	--- Blend a joint from whatever the Animator put there this frame toward an
	--- absolute torso-space pose. See the header: conjugating by the joint's own
	--- C0 rotation is what makes one set of angles work on both rigs.
	---
	--- `state` carries, per joint, the Transform we wrote last frame and the pose
	--- we blended from. That pair is what stops the pose drifting. Normally the
	--- Animator resets Transform before every PreSimulation, so `current` is a
	--- fresh pose and there is nothing to undo — but it does NOT reset when the
	--- Animator is throttled (it reuses the previous frame's pose for distant
	--- characters, see Animator.EvaluationThrottled) or when no track is playing at
	--- all. In those frames Transform is still exactly what we wrote, so without
	--- this check a partial-weight blend would creep toward the target a little
	--- more every frame and the pose would slowly overshoot into a pose we never
	--- authored.
	local function applyJoint(state, joint: Instance?, rotation: Vector3, weight: number)
		if not joint or not joint.Parent then
			return
		end

		local current = (joint :: any).Transform
		if state.written[joint] == current then
			current = state.baseline[joint]
		end
		state.baseline[joint] = current

		-- BLEND toward the pose, do not stack onto it. Multiplying our rotation
		-- into the Animator's looks right until you remember the tool-hold has
		-- already raised the right arm about 90 degrees forward: a 200-degree
		-- wind-up then becomes 290 and the bat starts somewhere behind the
		-- character's back. Poses are absolute, so the Animator's contribution is
		-- what we blend FROM, not something we add to.
		--
		-- Lerping also makes the weight envelope do the whole job of easing in and
		-- out: at weight 0 this is exactly the Animator's pose, so a swing can
		-- start and end without a pop and without ever needing to restore anything.
		local basis = (joint :: any).C0.Rotation
		local target = basis:Inverse() * angles(rotation) * basis
		local result = current:Lerp(target, weight)
		;(joint :: any).Transform = result
		state.written[joint] = result
	end

	local function lerpPose(a, b, alpha: number)
		return {
			arm = a.arm:Lerp(b.arm, alpha),
			offArm = a.offArm:Lerp(b.offArm, alpha),
			torso = a.torso:Lerp(b.torso, alpha),
		}
	end

	local REST = P(ZERO, ZERO, ZERO)

	--- Where the rig should be, `t` seconds into a swing of length `duration`.
	--- Returns the pose plus a blend weight that fades the whole thing in over the
	--- first few frames and out over the tail, so nothing pops when Roblox's own
	--- animation takes the limbs back.
	local function evaluate(swing, t: number, duration: number)
		local f = math.clamp(t / duration, 0, 1)
		local windUpEnd = Config.Combat.SwingWindUp
		local strikeEnd = Config.Combat.SwingStrikeAt

		local pose
		if f < windUpEnd then
			-- decelerating into the top of the wind-up
			local a = f / windUpEnd
			pose = lerpPose(REST, swing.windUp, 1 - (1 - a) * (1 - a))
		elseif f < strikeEnd then
			-- accelerating through the strike: this is the fast part
			local a = (f - windUpEnd) / (strikeEnd - windUpEnd)
			pose = lerpPose(swing.windUp, swing.strike, a * a)
		else
			-- HOLD the strike and let the weight envelope carry the arm back into
			-- whatever the Animator is doing. This used to lerp the pose toward
			-- REST, which is the bind pose — arms hanging at the sides — so at full
			-- weight the arm was driven down to the hip and then snapped back up to
			-- the tool-hold as the weight finally released. That was the odd ending.
			pose = swing.strike
		end

		-- The weight envelope does all the easing in and out of the Animator's
		-- pose, so it has to reach 1 before the strike and be back at 0 by the end.
		local weight
		local riseEnd = windUpEnd * 0.6
		if f < riseEnd then
			local a = f / riseEnd
			weight = a * a
		elseif f < strikeEnd then
			weight = 1
		else
			local a = (f - strikeEnd) / (1 - strikeEnd)
			weight = (1 - a) * (1 - a)
		end
		return pose, weight
	end

	--- Start (or restart) a swing on `character`.
	function SwingAnim.play(character: Model?, comboIndex: number, duration: number)
		if not character or not character.Parent then
			return
		end
		local swing = SwingAnim.SWINGS[((comboIndex - 1) % #SwingAnim.SWINGS) + 1]
		if not swing then
			return
		end
		active[character] = {
			swing = swing,
			joints = jointsFor(character),
			elapsed = 0,
			duration = math.max(0.15, duration),
			freeze = 0,
			-- per-joint memory of what we wrote and what we layered onto; see
			-- applyJoint for why both are needed
			written = {},
			baseline = {},
		}
	end

	--- Freeze the pose for a moment. Called on a landed hit: stopping the arc dead
	--- for two or three frames is most of what makes a hit feel like it connected
	--- with something solid rather than passing through it.
	function SwingAnim.hitStop(character: Model?, seconds: number?)
		local entry = character and active[character]
		if entry then
			entry.freeze = math.max(entry.freeze, seconds or 0.07)
		end
	end

	function SwingAnim.stop(character: Model?)
		if character then
			active[character] = nil
		end
	end

	local function step(dt: number)
		for character, entry in pairs(active) do
			if not character.Parent then
				active[character] = nil
			else
				if entry.freeze > 0 then
					entry.freeze -= dt
				else
					entry.elapsed += dt
				end

				if entry.elapsed >= entry.duration then
					active[character] = nil
				else
					local joints = entry.joints
					if not joints or not joints.arm or not joints.arm.Parent then
						-- the character can respawn mid-swing
						joints = jointsFor(character)
						entry.joints = joints
					end
					if joints then
						local pose, weight = evaluate(entry.swing, entry.elapsed, entry.duration)
						applyJoint(entry, joints.arm, pose.arm, weight)
						applyJoint(entry, joints.offArm, pose.offArm, weight)
						applyJoint(entry, joints.torso, pose.torso * (joints.torsoGain or ZERO), weight * 0.8)
					end
				end
			end
		end
	end

	function SwingAnim.start()
		if bound then
			return
		end
		bound = true
		-- PreSimulation, and nothing else. See the header: this is the last Luau
		-- event before Motor6D transforms are applied to part CFrames, and the
		-- first one after the Animator has written its own. A render-step binding
		-- here does nothing at all — that was the original bug.
		--
		-- Do NOT "modernise" this to its deprecated alias Stepped. PreSimulation
		-- passes (deltaTime); Stepped passes (timeSinceStart, deltaTime). With
		-- Stepped, `step` would take the elapsed run time as its dt and every swing
		-- would blow past its duration on the first frame — invisible again, for a
		-- completely different reason.
		RunService.PreSimulation:Connect(step)
	end

	return SwingAnim
end


__MODULES["TungModels"] = function()
	--[[
		TungModels.lua — procedural Tung Tung Tung Sahur models.

		Everything here is built from primitives at runtime. That means:
		  * zero dependency on toolbox / free models that can vanish or be moderated
		  * every variant is a parameter change, not a new upload
		  * the whole game is one Rojo sync away from running

		The silhouette: a wooden baseball bat standing on two skinny legs, with
		stick arms, an angry face, and (usually) a smaller bat in one hand.

		Facing convention: the face points along -Z, which matches Roblox's
		CFrame.LookVector and Enum.NormalId.Front.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Fx = Req("Fx")

	local TungModels = {}

	local HALF_PI = math.pi / 2

	local function variantOf(name: string)
		return Config.Variants[name] or Config.Variants.classic
	end

	local function part(parent: Instance, name: string, size: Vector3, cf: CFrame, color: Color3, material: Enum.Material): Part
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Color = color
		p.Material = material
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.CastShadow = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	--- Vertical cylinder helper (Roblox cylinders run along X, so we spin them).
	local function cylinder(parent, name, height, diameter, cf, color, material): Part
		local p = part(parent, name, Vector3.new(height, diameter, diameter), cf * CFrame.Angles(0, 0, HALF_PI), color, material)
		p.Shape = Enum.PartType.Cylinder
		return p
	end

	local function ball(parent, name, diameter, cf, color, material): Part
		local p = part(parent, name, Vector3.one * diameter, cf, color, material)
		p.Shape = Enum.PartType.Ball
		return p
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- The face — drawn with a SurfaceGui so it costs no extra physics parts.
	-- ─────────────────────────────────────────────────────────────────────────────

	local function circle(parent: Instance, size: UDim2, pos: UDim2, color: Color3, z: number): Frame
		local f = Instance.new("Frame")
		f.Size = size
		f.Position = pos
		f.AnchorPoint = Vector2.new(0.5, 0.5)
		f.BackgroundColor3 = color
		f.BorderSizePixel = 0
		f.ZIndex = z
		f.Parent = parent
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(1, 0)
		corner.Parent = f
		return f
	end

	--- Angry sahur face: wide eyes, hard brows, gritted mouth.
	function TungModels.paintFace(facePlate: BasePart, variant, mood: string?, maxDistance: number?)
		mood = mood or "angry"

		local gui = Instance.new("SurfaceGui")
		gui.Name = "Face"
		gui.Face = Enum.NormalId.Front
		gui.CanvasSize = Vector2.new(200, 200)
		gui.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
		gui.LightInfluence = Config.Style.LightInfluence
		gui.AlwaysOnTop = false
		-- A face is the most expensive label on screen — sixteen frames apiece, one
		-- per Tung on the belt — and the default used to be 0, which in
		-- SurfaceGui.MaxDistance means "never stop drawing". The arena statue and
		-- every raider inherited that. Callers that know better still pass their
		-- own (drops use `machine`); everything else gets the range at which a face
		-- has stopped being a face.
		gui.MaxDistance = maxDistance or Style.distance("plot")
		gui.Parent = facePlate

		local root = Instance.new("Frame")
		root.Size = UDim2.fromScale(1, 1)
		root.BackgroundTransparency = 1
		root.Parent = gui

		local dark = Color3.fromRGB(12, 10, 14)

		-- eye whites
		circle(root, UDim2.fromScale(0.30, 0.30), UDim2.fromScale(0.31, 0.40), variant.eye, 2)
		circle(root, UDim2.fromScale(0.30, 0.30), UDim2.fromScale(0.69, 0.40), variant.eye, 2)
		-- pupils
		circle(root, UDim2.fromScale(0.13, 0.15), UDim2.fromScale(0.33, 0.42), dark, 3)
		circle(root, UDim2.fromScale(0.13, 0.15), UDim2.fromScale(0.67, 0.42), dark, 3)
		-- glint
		circle(root, UDim2.fromScale(0.05, 0.05), UDim2.fromScale(0.30, 0.38), Color3.new(1, 1, 1), 4)
		circle(root, UDim2.fromScale(0.05, 0.05), UDim2.fromScale(0.64, 0.38), Color3.new(1, 1, 1), 4)

		if mood == "angry" then
			for i, x in ipairs({ 0.31, 0.69 }) do
				local brow = Instance.new("Frame")
				brow.Size = UDim2.fromScale(0.30, 0.075)
				brow.Position = UDim2.fromScale(x, 0.245)
				brow.AnchorPoint = Vector2.new(0.5, 0.5)
				brow.BackgroundColor3 = variant.accent
				brow.BorderSizePixel = 0
				brow.Rotation = (i == 1) and 16 or -16
				brow.ZIndex = 5
				brow.Parent = root
				Util.roundedFrame(brow, 6)
			end
		end

		-- mouth
		local mouth = Instance.new("Frame")
		mouth.Size = UDim2.fromScale(0.42, 0.16)
		mouth.Position = UDim2.fromScale(0.5, 0.70)
		mouth.AnchorPoint = Vector2.new(0.5, 0.5)
		mouth.BackgroundColor3 = dark
		mouth.BorderSizePixel = 0
		mouth.ZIndex = 2
		mouth.Parent = root
		Util.roundedFrame(mouth, 10)

		-- teeth
		for i = 0, 3 do
			local tooth = Instance.new("Frame")
			tooth.Size = UDim2.fromScale(0.075, 0.075)
			tooth.Position = UDim2.fromScale(0.325 + i * 0.117, 0.665)
			tooth.AnchorPoint = Vector2.new(0.5, 0.5)
			tooth.BackgroundColor3 = Color3.fromRGB(245, 245, 240)
			tooth.BorderSizePixel = 0
			tooth.ZIndex = 3
			tooth.Parent = root
		end

		return gui
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Bat body (no face) — reused by the character, the weapon, and props.
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Builds a bat aligned along +Y, centred at `origin`. Returns the barrel part.
	---
	--- The shape is deliberately five explicit parts rather than a sampled profile.
	--- A continuously tapered version was built and reverted: it satisfied every
	--- assertion written for it and still did not look right, which is the whole
	--- reason the shape lives in code you can see rather than in data you can only
	--- check.
	function TungModels.buildBatBody(parent: Instance, variantName: string, s: number, origin: CFrame): (Part, Part)
		local v = variantOf(variantName)
		s = s * (v.scale or 1)

		cylinder(parent, "Knob", 0.22 * s, 0.62 * s, origin * CFrame.new(0, -1.55 * s, 0), v.accent, v.material)
		local handle = cylinder(parent, "Handle", 1.50 * s, 0.44 * s, origin * CFrame.new(0, -0.75 * s, 0), v.accent, v.material)
		cylinder(parent, "Taper", 0.55 * s, 0.80 * s, origin * CFrame.new(0, 0.20 * s, 0), v.wood, v.material)
		local barrel = cylinder(parent, "Barrel", 2.05 * s, 1.34 * s, origin * CFrame.new(0, 1.45 * s, 0), v.wood, v.material)
		ball(parent, "Cap", 1.34 * s, origin * CFrame.new(0, 2.45 * s, 0), v.wood, v.material)

		-- wood grain rings
		for i = 1, 3 do
			local ring = cylinder(parent, "Grain" .. i, 0.06 * s, 1.37 * s,
				origin * CFrame.new(0, (0.85 + i * 0.42) * s, 0), v.accent, v.material)
			ring.Transparency = 0.35
		end

		return barrel, handle
	end

	--- A bat's extents at scale 1, measured off the parts buildBatBody actually
	--- emits: the knob's underside at -1.55 - 0.22/2, the cap's crown at
	--- 2.45 + 1.34/2. Anything that has to span or sit against a bat derives from
	--- these rather than restating a number that will not be updated with them.
	TungModels.BAT_BASE = -1.66
	TungModels.BAT_TOP = 3.12
	TungModels.BAT_LENGTH = TungModels.BAT_TOP - TungModels.BAT_BASE

	--- The barrel's radius at the local +Y offset `y`, in studs at the same scale.
	--- The barrel is a constant 1.34 across the whole face-plate region, so `y` is
	--- unused today — it is in the signature because the caller's question is "how
	--- wide is the body HERE", and the day the barrel stops being constant that is
	--- the question that still needs answering.
	function TungModels.batRadiusAt(y: number, s: number): number
		return 1.34 * s / 2
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Full character
	-- ─────────────────────────────────────────────────────────────────────────────

	export type BuildOptions = {
		scale: number?,
		anchored: boolean?,
		withEffects: boolean?,
		holdBat: boolean?,
		mood: string?,
		collide: boolean?,
	}

	--- The full Tung Tung Tung Sahur guy. PrimaryPart is `Core` at the model centre.
	function TungModels.build(variantName: string, opts: BuildOptions?): Model
		local o = opts or {}
		local v = variantOf(variantName)
		local s = (o.scale or 1) * (v.scale or 1)

		local model = Instance.new("Model")
		model.Name = "Tung_" .. variantName

		-- invisible physics core, sized to the whole silhouette
		local core = Instance.new("Part")
		core.Name = "Core"
		core.Size = Vector3.new(1.6 * s, 3.4 * s, 1.6 * s)
		core.CFrame = CFrame.new(0, 0, 0)
		core.Transparency = 1
		core.Anchored = true
		core.CanCollide = o.collide ~= false
		core.CanQuery = true
		core.CanTouch = true
		core.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.35, 0.2, 1, 1)
		core.Parent = model
		model.PrimaryPart = core

		local origin = CFrame.new(0, 0, 0)

		-- legs
		for i, sign in ipairs({ -1, 1 }) do
			local hip = origin * CFrame.new(sign * 0.34 * s, -2.15 * s, 0)
			local leg = cylinder(model, "Leg" .. i, 1.25 * s, 0.26 * s, hip, v.accent, Enum.Material.SmoothPlastic)
			leg.Color = Color3.fromRGB(232, 214, 186)
			local foot = part(model, "Foot" .. i, Vector3.new(0.52 * s, 0.24 * s, 0.92 * s),
				origin * CFrame.new(sign * 0.34 * s, -2.85 * s, -0.18 * s), Color3.fromRGB(60, 48, 40), Enum.Material.SmoothPlastic)
			local c = Instance.new("SpecialMesh")
			c.MeshType = Enum.MeshType.Sphere
			c.Scale = Vector3.new(1, 0.9, 1)
			c.Parent = foot
		end

		-- body
		local barrel = TungModels.buildBatBody(model, variantName, o.scale or 1, origin)

		-- Face plate, set 0.01 studs into the barrel so its 0.08 of depth leaves the
		-- front surface standing proud. Derived from the barrel's radius rather
		-- than written as the literal -0.66 it evaluates to: the two agree today
		-- only because the barrel is 1.34, and the literal would not notice if it
		-- stopped being.
		local faceY = 1.62 * s
		local faceRadius = TungModels.batRadiusAt(faceY, s)
		local face = part(model, "FacePlate", Vector3.new(1.16 * s, 1.16 * s, 0.08 * s),
			origin * CFrame.new(0, faceY, -(faceRadius - 0.01 * s)), v.wood, v.material)
		face.Transparency = 1
		TungModels.paintFace(face, v, o.mood)

		-- Arms. The RIGHT one — the one holding the bat — is built into its own
		-- sub-model so it can hang off a Motor6D instead of being welded rigidly to
		-- the body. Without that joint there is no way to raise a raider's bat:
		-- the R6 rig underneath is entirely invisible, so animating its shoulder
		-- rotates a stick nobody can see.
		local rightArm = Instance.new("Model")
		rightArm.Name = "RightArm"
		rightArm.Parent = model

		local shoulderCF, armRoot
		for _, sign in ipairs({ -1, 1 }) do
			local parent = (sign > 0) and rightArm or model
			local shoulder = origin * CFrame.new(sign * 0.72 * s, 1.15 * s, 0) * CFrame.Angles(0, 0, math.rad(sign * -34))
			local arm = cylinder(parent, "Arm", 1.30 * s, 0.22 * s, shoulder * CFrame.new(0, -0.55 * s, 0),
				Color3.fromRGB(232, 214, 186), Enum.Material.SmoothPlastic)
			arm.Name = (sign < 0) and "ArmLeft" or "ArmRight"
			local hand = ball(parent, "Hand", 0.34 * s,
				shoulder * CFrame.new(0, -1.25 * s, 0), Color3.fromRGB(240, 226, 200), Enum.Material.SmoothPlastic)
			hand.Name = (sign < 0) and "HandLeft" or "HandRight"

			if sign > 0 then
				shoulderCF = shoulder
				armRoot = arm
				-- the held bat rides with the arm, so it goes in the same sub-model
				if o.holdBat ~= false then
					local grip = CFrame.new(hand.Position) * CFrame.Angles(math.rad(-58), 0, math.rad(-18))
					TungModels.buildBatBody(rightArm, variantName, 0.34 * (o.scale or 1), grip * CFrame.new(0, 0.55 * s, 0))
				end
			end
		end

		-- signature effects
		if o.withEffects ~= false then
			Fx.applyVariant(barrel, v)
		end

		-- Assemble. Everything is welded rigidly to the core except the right arm,
		-- whose parts weld to each other and then join the body on one Motor6D —
		-- the only articulated joint on the visible model.
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") and p ~= core and p ~= armRoot then
				p.Anchored = true
				Util.weld(p:IsDescendantOf(rightArm) and armRoot or core, p)
			end
		end

		if armRoot then
			armRoot.Anchored = true
			local joint = Instance.new("Motor6D")
			joint.Name = "TungArm"
			joint.Part0 = core
			joint.Part1 = armRoot
			-- Pivot at the shoulder. Both C-frames are expressed relative to the
			-- same world point, so an identity Transform reproduces the pose the
			-- parts were built in.
			joint.C0 = core.CFrame:Inverse() * shoulderCF
			joint.C1 = armRoot.CFrame:Inverse() * shoulderCF
			joint.Parent = core
		end

		if not o.anchored then
			for _, p in ipairs(model:GetDescendants()) do
				if p:IsA("BasePart") then
					p.Anchored = false
				end
			end
		end

		model:SetAttribute("Variant", variantName)
		return model
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Conveyor drop — deliberately cheap (2 physics parts) because there can be
	-- hundreds of these alive at once.
	-- ─────────────────────────────────────────────────────────────────────────────

	function TungModels.buildDrop(variantName: string, scale: number?): Model
		local v = variantOf(variantName)
		local s = (scale or 0.5) * (v.scale or 1)

		local model = Instance.new("Model")
		model.Name = "Drop"

		local body = Instance.new("Part")
		body.Name = "Body"
		body.Shape = Enum.PartType.Cylinder
		body.Size = Vector3.new(2.4 * s, 1.15 * s, 1.15 * s)
		body.Color = v.wood
		body.Material = v.material
		body.Anchored = false
		body.CanCollide = true
		body.CastShadow = false
		body.TopSurface = Enum.SurfaceType.Smooth
		body.BottomSurface = Enum.SurfaceType.Smooth
		body.CustomPhysicalProperties = PhysicalProperties.new(0.6, 0.4, 0.1, 1, 1)
		body.CFrame = CFrame.Angles(0, 0, HALF_PI)
		body.Parent = model
		model.PrimaryPart = body

		local face = Instance.new("Part")
		face.Name = "FacePlate"
		face.Size = Vector3.new(0.95 * s, 0.95 * s, 0.06)
		face.Transparency = 1
		face.CanCollide = false
		face.CanQuery = false
		face.CanTouch = false
		face.CastShadow = false
		face.Massless = true
		face.CFrame = body.CFrame * CFrame.Angles(0, 0, -HALF_PI) * CFrame.new(0, 0.55 * s, -0.58 * s)
		face.Parent = model
		TungModels.paintFace(face, v, "angry", Style.distance("machine"))
		Util.weld(body, face)

		if v.fx and v.fx ~= "none" then
			-- no PointLight and fewer particles: there can be hundreds of these
			Fx.applyVariant(body, v, { light = false, rateScale = 0.35 })
		end

		model:SetAttribute("Variant", variantName)
		return model
	end

	--- The world CFrame a drop should be locked to so it rides the belt upright
	--- and looking back at whoever is walking alongside it.
	function TungModels.dropOrientation(beltDirection: Vector3): CFrame
		local look = CFrame.lookAt(Vector3.zero, -beltDirection.Unit)
		return look * CFrame.Angles(0, 0, HALF_PI)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- NPC rig — a real R6 Humanoid so pathfinding, MoveTo and damage all work,
	-- with the Tung visual welded on top of invisible limbs.
	-- ─────────────────────────────────────────────────────────────────────────────

	local function rigPart(model: Model, name: string, size: Vector3, cf: CFrame): Part
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Transparency = 1
		p.Anchored = false
		p.CanCollide = false
		p.CastShadow = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = model
		return p
	end

	local function motor(parent: BasePart, part0: BasePart, part1: BasePart, name: string, c0: CFrame, c1: CFrame): Motor6D
		local m = Instance.new("Motor6D")
		m.Name = name
		m.Part0 = part0
		m.Part1 = part1
		m.C0 = c0
		m.C1 = c1
		m.Parent = parent
		return m
	end

	export type NPCOptions = {
		scale: number?,
		health: number?,
		walkSpeed: number?,
		displayName: string?,
		boss: boolean?,
	}

	function TungModels.buildNPC(variantName: string, opts: NPCOptions?): Model
		local o = opts or {}
		local scale = o.scale or 1

		local model = Instance.new("Model")
		model.Name = o.displayName or ("Sahur Raider (" .. variantName .. ")")

		local base = CFrame.new(0, 0, 0)

		local hrp = rigPart(model, "HumanoidRootPart", Vector3.new(2, 2, 1) * scale, base)
		hrp.CanCollide = false

		local torso = rigPart(model, "Torso", Vector3.new(2, 2, 1) * scale, base)
		local head = rigPart(model, "Head", Vector3.new(1.2, 1.2, 1.2) * scale, base * CFrame.new(0, 1.5 * scale, 0))
		local la = rigPart(model, "Left Arm", Vector3.new(1, 2, 1) * scale, base * CFrame.new(-1.5 * scale, 0, 0))
		local ra = rigPart(model, "Right Arm", Vector3.new(1, 2, 1) * scale, base * CFrame.new(1.5 * scale, 0, 0))
		local ll = rigPart(model, "Left Leg", Vector3.new(1, 2, 1) * scale, base * CFrame.new(-0.5 * scale, -2 * scale, 0))
		local rl = rigPart(model, "Right Leg", Vector3.new(1, 2, 1) * scale, base * CFrame.new(0.5 * scale, -2 * scale, 0))

		-- an R6 Humanoid stands on its Torso + Legs; without collision here the
		-- raider sinks through the floor on spawn.
		torso.CanCollide = true
		ll.CanCollide = true
		rl.CanCollide = true

		motor(hrp, hrp, torso, "RootJoint", CFrame.new(0, 0, 0) * CFrame.Angles(-HALF_PI, 0, math.pi), CFrame.new(0, 0, 0) * CFrame.Angles(-HALF_PI, 0, math.pi))
		motor(torso, torso, head, "Neck", CFrame.new(0, 1 * scale, 0) * CFrame.Angles(-HALF_PI, 0, math.pi), CFrame.new(0, -0.5 * scale, 0) * CFrame.Angles(-HALF_PI, 0, math.pi))
		motor(torso, torso, la, "Left Shoulder", CFrame.new(-1 * scale, 0.5 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0), CFrame.new(0.5 * scale, 0.5 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0))
		motor(torso, torso, ra, "Right Shoulder", CFrame.new(1 * scale, 0.5 * scale, 0) * CFrame.Angles(0, HALF_PI, 0), CFrame.new(-0.5 * scale, 0.5 * scale, 0) * CFrame.Angles(0, HALF_PI, 0))
		motor(torso, torso, ll, "Left Hip", CFrame.new(-1 * scale, -1 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0), CFrame.new(-0.5 * scale, 1 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0))
		motor(torso, torso, rl, "Right Hip", CFrame.new(1 * scale, -1 * scale, 0) * CFrame.Angles(0, HALF_PI, 0), CFrame.new(0.5 * scale, 1 * scale, 0) * CFrame.Angles(0, HALF_PI, 0))

		-- the visible guy
		local visual = TungModels.build(variantName, {
			scale = scale * 0.95,
			anchored = false,
			withEffects = true,
			holdBat = true,
			collide = false,
		})
		visual.Name = "Visual"
		local core = visual.PrimaryPart :: BasePart
		core.CanCollide = false
		core.CanQuery = false
		core.CanTouch = false
		for _, p in ipairs(visual:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Massless = true
				p.CanCollide = false
			end
		end
		visual:PivotTo(torso.CFrame * CFrame.new(0, 0.7 * scale, 0))
		visual.Parent = model

		-- Motor6D (not a weld) so we can waddle it from code
		local sway = motor(torso, torso, core, "TungSway",
			CFrame.new(0, 0.7 * scale, 0), CFrame.new(0, 0, 0))
		sway.Name = "TungSway"

		local humanoid = Instance.new("Humanoid")
		humanoid.RigType = Enum.HumanoidRigType.R6
		humanoid.MaxHealth = o.health or 100
		humanoid.Health = o.health or 100
		humanoid.WalkSpeed = o.walkSpeed or 13
		humanoid.HipHeight = 0
		humanoid.AutoRotate = true
		humanoid.BreakJointsOnDeath = false
		humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
		humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOn
		humanoid.NameDisplayDistance = 120
		humanoid.HealthDisplayDistance = 120
		humanoid.Parent = model

		model.PrimaryPart = hrp
		model:SetAttribute("Variant", variantName)
		model:SetAttribute("IsSahurNPC", true)
		if o.boss then
			model:SetAttribute("IsBoss", true)
		end

		return model
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Weapon
	-- ─────────────────────────────────────────────────────────────────────────────

	--- How the Tool's visible bat sits relative to its Handle box. Named because
	--- the trail attachments have to span exactly this.
	local DECO_SCALE = 0.72
	local DECO_ORIGIN_Y = 1.9

	--- Builds the Handle part + decoration for a bat Tool.
	function TungModels.buildBatTool(batDef): Tool
		local v = variantOf(batDef.variant)

		local tool = Instance.new("Tool")
		tool.Name = batDef.name
		tool.RequiresHandle = true
		tool.CanBeDropped = false
		tool.ToolTip = ("%d dmg  •  click to swing"):format(batDef.damage)
		-- Held like a sword rather than straight up out of the fist: the grip drops
		-- the bat into the palm and cants it forward so the barrel reads as a blade
		-- you're about to swing. Grip is the offset of the engine's RightGrip weld,
		-- so this is a pose, not an animation, and it costs nothing.
		tool.Grip = CFrame.new(0, -0.15, 0.1) * CFrame.Angles(math.rad(-18), 0, math.rad(-8))

		local handle = Instance.new("Part")
		handle.Name = "Handle"
		handle.Size = Vector3.new(0.5, 1.6, 0.5)
		handle.Color = v.accent
		handle.Material = v.material
		handle.CanCollide = false
		handle.Massless = true
		handle.TopSurface = Enum.SurfaceType.Smooth
		handle.BottomSurface = Enum.SurfaceType.Smooth
		handle.Parent = tool

		local deco = Instance.new("Model")
		deco.Name = "Deco"
		deco.Parent = tool

		-- barrel above the grip
		local origin = CFrame.new(0, DECO_ORIGIN_Y, 0)
		TungModels.buildBatBody(deco, batDef.variant, DECO_SCALE, origin)

		for _, p in ipairs(deco:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Massless = true
				p.CanCollide = false
				p.Anchored = false
				Util.weld(handle, p)
			end
		end

		-- Swing trail, spanning the deco the Tool actually built.
		--
		-- These were hardcoded at 0.8 and 3.4, which was wrong twice: the span did
		-- not scale with the variant, and a bat is not centred on its origin
		-- anyway — it runs from -1.66 to +3.12, so the fixed pair clipped the last
		-- three quarters of a stud off a `classic` and covered barely half of a
		-- `void`, which carries its own 1.3x on top.
		local decoScale = DECO_SCALE * (v.scale or 1)
		local a0 = Instance.new("Attachment")
		a0.Name = "TrailTop"
		a0.Position = Vector3.new(0, DECO_ORIGIN_Y + TungModels.BAT_BASE * decoScale, 0)
		a0.Parent = handle
		local a1 = Instance.new("Attachment")
		a1.Name = "TrailBottom"
		a1.Position = Vector3.new(0, DECO_ORIGIN_Y + TungModels.BAT_TOP * decoScale, 0)
		a1.Parent = handle
		local trail = Fx.trail(a0, a1, v.light and v.light.color or v.wood)
		trail.Name = "SwingTrail"

		tool:SetAttribute("BatId", batDef.id)
		tool:SetAttribute("Damage", batDef.damage)
		tool:SetAttribute("Cooldown", batDef.cooldown)
		tool:SetAttribute("Knockback", batDef.knockback)
		tool:SetAttribute("Reach", batDef.reach)
		tool:SetAttribute("Crit", batDef.crit)

		return tool
	end

	--- Big anchored decorative statue for the lobby / plot signage.
	function TungModels.buildStatue(variantName: string, scale: number): Model
		local model = TungModels.build(variantName, {
			scale = scale,
			anchored = true,
			withEffects = true,
			holdBat = true,
			collide = true,
		})
		model.Name = "TungStatue"
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Anchored = true
			end
		end
		return model
	end

	return TungModels
end


__MODULES["Util"] = function()
	--[[
		Util.lua — the leaf. Thirteen small helpers, required by fifteen files
		across both sides of the game.

		IT REQUIRES NOTHING, and that is a contract rather than an accident. There is
		no `Req` line and no service lookup anywhere below, so any module can require
		Util without thinking about the require graph, and the spec harness can load it
		with no mock standing behind it. Adding `Req("Config")` here would hand all
		fifteen of those files a new edge, and Req refuses a circular require at
		RUNTIME — a cycle introduced here does not fail the build, it fails the boot.

		IT IS COMPILED INTO BOTH PASTE BUILDS. tools/pack.py builds the server script
		from [src/shared, src/server] and the client one from [src/shared, src/client],
		so everything in src/shared ships to both. Nothing that only one side is
		allowed to do belongs here — src/client/UiKit.lua lives on the client for
		precisely this reason, and its header explains the failure.

		WHAT IS LOAD-BEARING, out of the thirteen:

		  abbreviate    the game's money formatter — fifty-odd call sites, and
		                Economy.format is an alias for it. Its trailing-zero trim is
		                gated on the text containing a decimal point: an
		                unconditional trim turned "320" into "32", so 320K rendered
		                as 32K. That guard is the whole function's history.
		  platformFrom  every string it can return must also appear in
		                Config.Analytics.Fields.platform.values. It cannot read
		                Config to check (see above), so analytics_spec.lua checks it
		                instead, through the Analytics.platformFrom re-export — which
		                is why that alias exists and must not be deleted as
		                redundant. The ORDER of the tests inside it is the function.
		  getRig        the sanctioned way to read a character's Humanoid and root.
		                Twelve call sites, every one of which relies on the nil, nil
		                return rather than on a pcall.

		shallowCopy IS SHALLOW, and its one caller makes that matter: Tycoon:rebirth
		copies the kept-buttons set with it. A Config.ButtonById def is one table
		shared by every plot on the server, so copying a def rather than a set of ids
		would hand you nested tables that are still shared with every other plot.

		comma, count, hash, newPart, setCollision and weldModel have no caller in src/
		today. They are available; they are not proven.
	]]

	local Util = {}

	local SUFFIXES = {
		"", "K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No",
		"Dc", "UDc", "DDc", "TDc", "QaDc", "QiDc", "SxDc", "SpDc", "OcDc", "NoDc", "Vg",
	}

	--- 1234567 -> "1.23M"
	function Util.abbreviate(n: number): string
		if n ~= n then return "0" end            -- NaN guard
		local sign = n < 0 and "-" or ""
		n = math.abs(n)
		if n < 1000 then
			return sign .. tostring(math.floor(n + 0.5))
		end
		local index = math.floor(math.log(n, 1000))
		index = math.clamp(index, 1, #SUFFIXES - 1)
		local scaled = n / (1000 ^ index)
		local text
		if scaled >= 100 then
			text = string.format("%.0f", scaled)
		elseif scaled >= 10 then
			text = string.format("%.1f", scaled)
		else
			text = string.format("%.2f", scaled)
		end
		-- Trim trailing zeros, but ONLY past a decimal point. Trimming
		-- unconditionally turns "320" into "32", i.e. 320K displays as 32K.
		if text:find("%.") then
			text = text:gsub("0+$", "")
			text = text:gsub("%.$", "")
		end
		return sign .. text .. SUFFIXES[index + 1]
	end

	--- 1234567 -> "1,234,567"
	function Util.comma(n: number): string
		local whole = string.format("%.0f", math.abs(n))
		local out = whole:reverse():gsub("(%d%d%d)", "%1,"):reverse()
		out = out:gsub("^,", "")
		return (n < 0 and "-" or "") .. out
	end

	function Util.weld(a: BasePart, b: BasePart, name: string?): WeldConstraint
		local weld = Instance.new("WeldConstraint")
		weld.Name = name or "TungWeld"
		weld.Part0 = a
		weld.Part1 = b
		weld.Parent = a
		return weld
	end

	--- Welds every descendant BasePart of `model` to `root` and anchors nothing.
	function Util.weldModel(model: Model, root: BasePart)
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") and part ~= root then
				part.Anchored = false
				Util.weld(root, part)
			end
		end
	end

	function Util.setCollision(model: Instance, group: string)
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") then
				part.CollisionGroup = group
			end
		end
		if model:IsA("BasePart") then
			model.CollisionGroup = group
		end
	end

	function Util.newPart(props: { [string]: any }): Part
		local part = Instance.new("Part")
		part.Anchored = true
		part.CanCollide = false
		part.CastShadow = false
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		for key, value in pairs(props) do
			if key ~= "Parent" then
				(part :: any)[key] = value
			end
		end
		if props.Parent then
			part.Parent = props.Parent
		end
		return part
	end

	function Util.roundedFrame(parent: Instance, radius: number): UICorner
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, radius)
		corner.Parent = parent
		return corner
	end

	--- invariant: device class from a bag of input flags. One of
	--- Config.Analytics.Fields.platform.values, always.
	---
	--- HERE RATHER THAN IN Analytics.lua. Roblox has no server-side device API, so
	--- the ladder has to RUN on the client — and Analytics.lua is deliberately
	--- server-only, because an analytics call from a client silently does nothing
	--- forever. Written twice it would drift invisibly: two plausible ladders
	--- disagreeing about tablets. Analytics re-exports it as
	--- `Analytics.platformFrom` so the specs pin the server's contract.
	---
	--- ORDER IS THE WHOLE FUNCTION. A VR headset and a console both report
	--- TouchEnabled in some configurations, so a `TouchEnabled` test placed first
	--- files every headset in the game under "mobile" — and the resulting chart
	--- looks completely normal. VR and console are therefore asked first, and the
	--- touch test additionally requires that there is no keyboard.
	---
	--- The tablet split is a viewport width because Roblox does not expose a device
	--- class: 900px is where a phone in landscape stops and a tablet starts. It is a
	--- judgement call and it is the only line here that is.
	function Util.platformFrom(flags): string
		flags = flags or {}
		if flags.vr then
			return "vr"
		elseif flags.tenFoot then
			return "console"
		elseif flags.touch and not flags.keyboard then
			return (tonumber(flags.viewportX) or 0) >= 900 and "tablet" or "mobile"
		elseif flags.keyboard and flags.mouse then
			return "desktop"
		end
		return "unknown"
	end

	function Util.shallowCopy(t)
		local out = {}
		for k, v in pairs(t) do
			out[k] = v
		end
		return out
	end

	function Util.count(t): number
		local n = 0
		for _ in pairs(t) do
			n += 1
		end
		return n
	end

	--- Deterministic-ish pseudo random from a string seed (used for plot flavour).
	function Util.hash(s: string): number
		local h = 5381
		for i = 1, #s do
			h = (h * 33 + s:byte(i)) % 2147483647
		end
		return h
	end

	function Util.lerpColor(a: Color3, b: Color3, t: number): Color3
		return a:Lerp(b, math.clamp(t, 0, 1))
	end

	--- Safely reads a character's humanoid + root, or nil.
	function Util.getRig(model: Instance?): (Humanoid?, BasePart?)
		if not model or not model:IsA("Model") then
			return nil, nil
		end
		local humanoid = model:FindFirstChildOfClass("Humanoid")
		local root = model:FindFirstChild("HumanoidRootPart")
		if humanoid and root and root:IsA("BasePart") then
			return humanoid, root
		end
		return nil, nil
	end

	return Util
end


__MODULES["CombatClient"] = function()
	--[[
		CombatClient.lua — local feel for combat: hitmarkers, camera shake and
		knockback. Damage itself is entirely server-side, and equipping is handled
		by Roblox's built-in Backpack.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")
	local HUD = Req("HUD")
	local SwingAnim = Req("SwingAnim")

	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")

	local player = Players.LocalPlayer

	local CombatClient = {}

	local shake = 0

	--- The crosshair flash on a landed hit.
	---
	--- It goes in HUD.root(), not in the ScreenGui itself. Parenting straight to the
	--- ScreenGui puts it outside the UIScale AND outside the safe-area padding — the
	--- exact failure the one-ScreenGui lint exists to prevent, reached through a
	--- different door, because nothing had to make a second ScreenGui to get there.
	--- A 44x44 marker at MinScale would have drawn 44 physical pixels on a phone
	--- while every other 44 in the game drew 27.
	local function buildHitmarker(root: Instance)
		local marker = Instance.new("Frame")
		marker.Name = "Hitmarker"
		marker.AnchorPoint = Vector2.new(0.5, 0.5)
		marker.Position = UDim2.fromScale(0.5, 0.5)
		marker.Size = UDim2.fromOffset(44, 44)
		marker.BackgroundTransparency = 1
		marker.Visible = false
		marker.Parent = root

		for i, rot in ipairs({ 45, -45 }) do
			for j, offset in ipairs({ -1, 1 }) do
				local tick = Instance.new("Frame")
				tick.Name = ("Tick%d_%d"):format(i, j)
				tick.AnchorPoint = Vector2.new(0.5, 0.5)
				tick.Size = UDim2.fromOffset(16, 4)
				tick.Position = UDim2.fromScale(0.5, 0.5)
				tick.BackgroundColor3 = Color3.fromRGB(255, 245, 200)
				tick.BorderSizePixel = 0
				tick.Rotation = rot
				tick.Parent = marker
				local dx = math.cos(math.rad(rot)) * 16 * offset
				local dy = math.sin(math.rad(rot)) * 16 * offset
				tick.Position = UDim2.new(0.5, dx, 0.5, dy)
			end
		end

		return marker
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- swings
	--
	-- The server is still the only thing that decides whether a swing HIT. All we
	-- do here is draw it, and draw our own immediately instead of waiting for the
	-- round trip — a wind-up that starts 100ms after the click feels broken even
	-- though the damage timing is identical.
	-- ─────────────────────────────────────────────────────────────────────────────

	local localSwing = { at = 0, combo = 0 }

	--- Mirrors the server's combo bookkeeping in CombatService.swing. A drifted
	--- prediction only ever picks the wrong swing ANIMATION, never the wrong
	--- damage, so it is allowed to be approximate.
	local function predictSwing(tool: Tool)
		local now = os.clock()
		local cooldown = tool:GetAttribute("Cooldown") or 0.55
		if now - localSwing.at < cooldown then
			return
		end
		if now - localSwing.at <= Config.Combat.ComboWindow then
			localSwing.combo = (localSwing.combo + 1) % (Config.Combat.ComboMaxStacks + 1)
		else
			localSwing.combo = 0
		end
		localSwing.at = now
		SwingAnim.play(player.Character, localSwing.combo + 1, cooldown)
	end

	local watched: { [Instance]: boolean } = setmetatable({}, { __mode = "k" }) :: any

	local function watchTool(tool: Instance)
		-- A tool moves Backpack -> Character on equip and back on unequip, so it
		-- turns up in ChildAdded on both containers. Connect once.
		if watched[tool] or not tool:IsA("Tool") or not tool:GetAttribute("BatId") then
			return
		end
		watched[tool] = true
		tool.Activated:Connect(function()
			predictSwing(tool)
		end)
	end

	--- Bats are handed out by the server into the Backpack, and moved into the
	--- character on equip, so watch both containers and everything already in them.
	local function watchBats()
		local function attach(container: Instance?)
			if not container then
				return
			end
			container.ChildAdded:Connect(watchTool)
			for _, child in ipairs(container:GetChildren()) do
				watchTool(child)
			end
		end

		attach(player:FindFirstChildOfClass("Backpack"))
		player.ChildAdded:Connect(function(child)
			if child:IsA("Backpack") then
				attach(child)
			end
		end)

		local function onCharacter(character: Model)
			SwingAnim.stop(character)
			localSwing.combo = 0
			attach(character)
		end
		if player.Character then
			onCharacter(player.Character)
		end
		player.CharacterAdded:Connect(onCharacter)
	end

	function CombatClient.start()
		local root = HUD.root()
		if not root then
			return
		end

		local marker = buildHitmarker(root)
		local hideAt = 0

		Net.event("HitFeedback").OnClientEvent:Connect(function(payload)
			marker.Visible = true
			hideAt = os.clock() + 0.16
			for _, tick in ipairs(marker:GetChildren()) do
				if tick:IsA("Frame") then
					tick.BackgroundColor3 = payload.killed and Color3.fromRGB(255, 120, 90)
						or payload.crit and Color3.fromRGB(255, 190, 90)
						or Color3.fromRGB(255, 245, 200)
				end
			end
			shake = math.min(shake + (payload.killed and 1.1 or payload.crit and 0.85 or 0.55), 2)
			-- Stopping the arc dead for two or three frames is most of what makes a
			-- hit feel like it connected with something solid.
			SwingAnim.hitStop(player.Character, Config.Combat.HitStop)
		end)

		-- Everyone else's swings. Motor6D.Transform is a local visual, so each
		-- client draws every character's swing itself; skip our own, which we
		-- already predicted on Tool.Activated.
		Net.event("SwingFx").OnClientEvent:Connect(function(payload)
			if typeof(payload) ~= "table" or not payload.character then
				return
			end
			-- Skip our own swing only if we really did predict it. The two cooldown
			-- gates run on different clocks, so a pair of clicks near the boundary
			-- can be refused locally and accepted by the server — and an
			-- unconditional skip would leave the attacker dealing damage with no
			-- swing drawn at all.
			if payload.character == player.Character and (os.clock() - localSwing.at) < 0.3 then
				return
			end
			SwingAnim.play(payload.character, payload.combo or 1, payload.duration or 0.5)
		end)

		-- knockback is applied here, not on the server: this client owns its own
		-- character's physics, so a server-side impulse would just be overwritten
		Net.event("Knockback").OnClientEvent:Connect(function(impulse)
			local character = player.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root and root:IsA("BasePart") and typeof(impulse) == "Vector3" then
				root:ApplyImpulse(impulse)
			end
		end)

		RunService.RenderStepped:Connect(function()
			if marker.Visible and os.clock() > hideAt then
				marker.Visible = false
			end
		end)

		-- The default camera module writes Camera.CFrame from a bound render step
		-- at Enum.RenderPriority.Camera. Shaking on RenderStepped runs BEFORE that
		-- and gets thrown away, so bind after the camera instead.
		RunService:BindToRenderStep("TungCameraShake", Enum.RenderPriority.Camera.Value + 1, function(dt)
			if shake <= 0.001 then
				return
			end
			shake = math.max(0, shake - dt * 5)
			local magnitude = shake * 0.6
			local activeCamera = workspace.CurrentCamera
			if activeCamera then
				activeCamera.CFrame = activeCamera.CFrame * CFrame.Angles(
					math.rad((math.random() - 0.5) * magnitude),
					math.rad((math.random() - 0.5) * magnitude),
					math.rad((math.random() - 0.5) * magnitude)
				)
			end
		end)

		-- No custom swing button and no auto-equip: the bat is a plain Tool, so
		-- Roblox's built-in hotbar equips it and its built-in activation (click,
		-- tap, or the mobile fire button) triggers Tool.Activated for us — on the
		-- client as well as on the server, which is what makes local prediction
		-- free rather than something we'd have to send a remote for.
		SwingAnim.start()
		watchBats()
	end

	return CombatClient
end


__MODULES["HUD"] = function()
	--[[
		HUD.lua — all of the on-screen furniture, and the one ScreenGui the whole
		game draws into.

		Built in code so there is no .rbxm to keep in sync with the source.

		IT OWNS THE TWO LAYERS EVERY OTHER PANEL BUILDS INTO. `Root` carries the
		UIScale and the safe-area padding and holds the persistent furniture;
		`Overlay` carries the same UIScale and no padding, and holds modals, because
		a dimming shade SHOULD run under the notch and a padded root would leave an
		undimmed strip down the side of it. Panels ask for HUD.root() or
		HUD.overlay(); nothing outside this file makes a ScreenGui, and tools/
		verify.py fails the build if anything tries.

		AND FOUR DOCKED REGIONS INSIDE Root, one per corner it uses:

		  Column    top-left, a UIListLayout — the status card, then whatever else
		            belongs in the stack under it. HUD.column() hands it out.
		  Rail      top-right, the utility icons. One item today, the invite.
		  Toasts    top-right under the rail, derived to clear it.
		  Actions   bottom-right, RAISED off the bottom edge by
		            Config.UI.TouchReserve.Bottom — see buildActions.

		Every one of them is a UiKit.dock call naming a corner. They were four
		hand-written AnchorPoint/UDim2 pairs, in this file and in SessionUI, and the
		left column's two panels were positioned by two files reading the same Config
		keys separately.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Net = Req("Net")
	local UiKit = Req("UiKit")

	local Players = game:GetService("Players")
	local TweenService = game:GetService("TweenService")
	local RunService = game:GetService("RunService")
	-- The invite prompt is a CLIENT call. There is no server-side equivalent, which
	-- is why the server half of this feature is only a cooldown.
	local SocialService = game:GetService("SocialService")

	local player = Players.LocalPlayer

	local HUD = {}

	local UI = Config.UI
	-- Spelled from `Config` rather than from `UI` so verify.py's config-path pass
	-- resolves it: it treats `local X = Config.a.b` as an alias and checks every
	-- `X.key` against Config, and a `local CARD = UI.StatusCard` would be a name it
	-- has no way to follow. Every number on the status card is read through here.
	local CARD = Config.UI.StatusCard
	local RAIL = Config.UI.Rail
	local TOAST = Config.UI.Toast
	local REBIRTH = Config.UI.Modal.Rebirth
	local PALETTE = UiKit.PALETTE

	local KIND_COLOR = {
		buy      = PALETTE.good,
		warn     = PALETTE.bad,
		wave     = PALETTE.wave,
		boss     = PALETTE.boss,
		rebirth  = PALETTE.accent,
		gear     = PALETTE.gold,
		ko       = Color3.fromRGB(255, 230, 140),
		claim    = PALETTE.good,
		welcome  = PALETTE.gold,
		info     = PALETTE.accent,
	}

	local state = {
		cash = 0,
		rebirths = 0,
		kills = 0,
		multiplier = 1,
		owned = {},
		rebirthCost = Config.Rebirth.BaseCost,
		friends = 0,
		friendCap = Config.Social.MaxFriends,
		friendBonus = Config.Social.BonusPerFriend,
		-- Until CanSendGameInviteAsync has answered, the button does not exist. It
		-- is never shown optimistically: account policy can refuse invites outright
		-- and a button that errors when a child presses it is worse than no button.
		canInvite = false,
	}

	local gui, root, overlay, rootScale, overlayScale, rootPadding
	local column, cashLabel, multLabel, termsLabel
	local inviteButton, inviteCaption
	local waveFrame, waveLabel, toastList, rebirthButton
	-- the next-purchase half of the status card: name, bar fill, "N to go". The bar's
	-- TRACK is not kept — it is drawn once and never written to again, and a module
	-- local nothing reads is a local that outlives the reason it was added.
	local nextLabel, nextFill, nextDetail
	local bossTrack, bossFill

	-- The panel vocabulary, aliased so every call site below reads exactly as it
	-- did when these were five local functions in this file. They are UiKit's now;
	-- see src/client/UiKit.lua for what the merge of the three copies cost.
	local corner, stroke, panel, text, button =
		UiKit.corner, UiKit.stroke, UiKit.panel, UiKit.text, UiKit.button

	-- ─────────────────────────────────────────────────────────────────────────────

	--- design:D-05 — ONE CARD, TWO THINGS TO READ: what you have, and what you are
	--- saving for. Why it is one card, why the balance is the largest thing on it,
	--- why the friend bonus is a term rather than a row, and why nothing on it is
	--- pressable.
	---
	--- mechanism: `multLabel` prints the product; `termsLabel` prints what went
	--- into it.
	---
	--- THE BAR IS A BAR AND A LINE OF TEXT ON PURPOSE. A bar alone cannot say what
	--- you are saving for or how much is left; the text alone makes you compare two
	--- abbreviated numbers to find out whether you are close. Both, driven off the
	--- same lerped balance, answer it at a glance and to the Tung.
	---
	--- invariant: EVERY NUMBER BELOW COMES FROM Config.UI.StatusCard. Not one Y is
	--- typed here — they are accumulated from the row heights in Config's
	--- derivation block, so a row that grows moves the rows under it, the card's
	--- ContentHeight, the session panel's Y and the column's bottom, and the
	--- verifier re-runs the fit against all four.
	local function buildStatusCard(parent: Instance)
		-- NO POSITION. The parent is HUD.column(), which is a UIListLayout; the only
		-- thing this card says about where it goes is that it is first.
		local frame = panel(parent,
			UDim2.fromOffset(CARD.Width, CARD.Height),
			UDim2.fromOffset(0, 0))
		frame.Name = "Status"
		frame.LayoutOrder = 1

		local icon = Instance.new("TextLabel")
		icon.Size = UDim2.fromOffset(CARD.IconSize, CARD.IconSize)
		icon.Position = UDim2.fromOffset(CARD.Pad, CARD.IconY)
		icon.BackgroundColor3 = PALETTE.gold
		icon.BackgroundTransparency = 0.15
		icon.Font = Style.Font.title
		icon.Text = "T"
		icon.TextColor3 = Color3.fromRGB(40, 28, 10)
		icon.TextScaled = true
		icon.Parent = frame
		corner(icon, math.floor(CARD.IconSize / 2))

		cashLabel = text(frame, {
			Size = UDim2.fromOffset(CARD.TextWidth, CARD.BalanceHeight),
			Position = UDim2.fromOffset(CARD.TextX, CARD.BalanceY),
			Font = Style.Font.title,
			Text = "0",
			TextSize = CARD.BalanceTextPx,
			TextColor3 = PALETTE.gold,
		})

		multLabel = text(frame, {
			Size = UDim2.fromOffset(CARD.TextWidth, CARD.MultHeight),
			Position = UDim2.fromOffset(CARD.TextX, CARD.MultY),
			Font = Style.Font.body,
			Text = "x1.00",
			TextSize = CARD.MultTextPx,
			TextColor3 = PALETTE.muted,
		})

		-- THE TERMS, FULL WIDTH, where the two lines above it are indented past the
		-- coin. Everything that went into the product on the line above: the
		-- rebirths, the KOs and the friends. See renderTerms for why one function
		-- writes all three.
		termsLabel = text(frame, {
			Size = UDim2.fromOffset(CARD.ContentWidth, CARD.TermsHeight),
			Position = UDim2.fromOffset(CARD.Pad, CARD.TermsY),
			Font = Style.Font.body,
			Text = "",
			TextSize = CARD.TermsTextPx,
			TextColor3 = PALETTE.muted,
			TextTruncate = Enum.TextTruncate.AtEnd,
		})

		-- A rule, not a second card. It says "two things to read" without spending a
		-- gutter, an outline and a shadow to say it.
		local divider = Instance.new("Frame")
		divider.Name = "Rule"
		divider.Size = UDim2.fromOffset(CARD.ContentWidth, CARD.DividerHeight)
		divider.Position = UDim2.fromOffset(CARD.Pad, CARD.DividerY)
		divider.BackgroundColor3 = PALETTE.accent
		divider.BackgroundTransparency = 0.75
		divider.BorderSizePixel = 0
		divider.Parent = frame

		text(frame, {
			Size = UDim2.fromOffset(CARD.ContentWidth, CARD.HeadingHeight),
			Position = UDim2.fromOffset(CARD.Pad, CARD.HeadingY),
			Font = Style.Font.body,
			Text = "NEXT UPGRADE",
			TextSize = CARD.HeadingTextPx,
			TextColor3 = PALETTE.muted,
		})

		nextLabel = text(frame, {
			Size = UDim2.fromOffset(CARD.ContentWidth, CARD.NameHeight),
			Position = UDim2.fromOffset(CARD.Pad, CARD.NameY),
			Font = Style.Font.title,
			Text = "Tung Dropper — 50",
			TextSize = CARD.NameTextPx,
			TextColor3 = PALETTE.text,
			TextTruncate = Enum.TextTruncate.AtEnd,
		})

		-- THE FILL RIDES THE LERPED BALANCE, not the packet — see renderNext. The
		-- track is drawn once and never written to again; only the fill's width and
		-- colour change, so there is nothing here for a frame to get half-way
		-- through.
		local barTrack = Instance.new("Frame")
		barTrack.Name = "Progress"
		barTrack.Size = UDim2.fromOffset(CARD.ContentWidth, CARD.BarHeight)
		barTrack.Position = UDim2.fromOffset(CARD.Pad, CARD.BarY)
		barTrack.BackgroundColor3 = PALETTE.panel2
		barTrack.BackgroundTransparency = 0.25
		barTrack.BorderSizePixel = 0
		barTrack.Parent = frame
		corner(barTrack, math.floor(CARD.BarHeight / 2))

		nextFill = Instance.new("Frame")
		nextFill.Name = "Fill"
		nextFill.Size = UDim2.fromScale(0, 1)
		nextFill.BackgroundColor3 = PALETTE.gold
		nextFill.BorderSizePixel = 0
		nextFill.Parent = barTrack
		corner(nextFill, math.floor(CARD.BarHeight / 2))

		-- The gap to the next purchase, and how far through the build you are. The
		-- bar says how close; this says what "close" is worth and which rung of which
		-- track you are on. A price on its own does not tell you whether to keep
		-- grinding or go and fight a wave for the bounty.
		nextDetail = text(frame, {
			Size = UDim2.fromOffset(CARD.ContentWidth, CARD.DetailHeight),
			Position = UDim2.fromOffset(CARD.Pad, CARD.DetailY),
			Font = Style.Font.body,
			Text = "",
			TextSize = CARD.DetailTextPx,
			TextColor3 = PALETTE.muted,
		})

		return frame
	end

	--- The raid banner is a SIGN IN THE WORLD, not a bar across your screen.
	---
	--- It hangs over the Tung statue in the middle of the arena, which is where
	--- the raid is and which is visible from every plot. One line, big, no box —
	--- readable at a glance and ignorable the rest of the time, which a panel
	--- pinned to the top of the screen never manages.
	---
	--- CLIENT-OWNED ON PURPOSE. The billboard is created here, on the client,
	--- parented to an anchor the server stood up. That is what lets the countdown
	--- keep ticking locally off a `seconds` the server sends once per phase,
	--- instead of costing a remote every second — which was one of the three
	--- properties of the old banner worth carrying over, and the cheapest to lose
	--- by accident if the server had drawn this.
	local function buildWaveBanner()
		local world = workspace:FindFirstChild("TungWorld")
		local arena = world and world:WaitForChild("Arena", 10)
		local anchor = arena and arena:WaitForChild("RaidAnchor", 10)
		if not anchor then
			-- No banner rather than a broken one. Every read of waveFrame is
			-- already nil-guarded because the HUD used to build it lazily.
			warn("[Tung] no RaidAnchor in the arena; the raid banner has nowhere to hang")
			return
		end

		waveFrame = Style.billboard(anchor, {
			name = "RaidSign",
			width = 60, height = Config.Style.RaidSignHeight,
			distance = "world",
		})
		waveFrame.Enabled = false

		-- THE SIGN IS SPLIT THE WAY THE ARENA TITLE ALREADY IS: a line, and a strip
		-- under it. The strip is the boss's health, and it is here rather than in a
		-- bar across the top of your screen for the reason written on
		-- Config.Style.RaidSignY — the raid is a place, and this is where it is.
		--
		-- The fractions are DERIVED from the two heights rather than typed, so the
		-- bar cannot drift out of the sign the arena title is asserted against.
		local signHeight = Config.Style.RaidSignHeight
		local barFraction = Config.Style.BossBarHeight / signHeight
		local inset = Config.Style.BossBarInset

		waveLabel = Style.text(waveFrame, {
			name = "Line",
			size = UDim2.fromScale(1, 1 - barFraction),
			text = "", color = PALETTE.wave,
		})

		bossTrack = Instance.new("Frame")
		bossTrack.Name = "BossBar"
		bossTrack.Size = UDim2.fromScale(1 - inset * 2, barFraction * 0.7)
		bossTrack.Position = UDim2.fromScale(inset, 1 - barFraction)
		bossTrack.BackgroundColor3 = PALETTE.panel
		bossTrack.BackgroundTransparency = 0.35
		bossTrack.BorderSizePixel = 0
		-- Only ever up during a boss fight. Every other wave, the sign is the one
		-- line it has always been.
		bossTrack.Visible = false
		bossTrack.Parent = waveFrame
		corner(bossTrack, 3)

		bossFill = Instance.new("Frame")
		bossFill.Name = "Fill"
		bossFill.Size = UDim2.fromScale(1, 1)
		bossFill.BackgroundColor3 = PALETTE.boss
		bossFill.BorderSizePixel = 0
		bossFill.Parent = bossTrack
		corner(bossFill, 3)
	end

	--- THE LEFT COLUMN, as one region rather than as two panels that agree.
	---
	--- The status card and the session panel are one width stacked from the top
	--- margin down, and they used to say so twice: this file positioned the first
	--- from Config.UI.StatusCard.Y and SessionUI positioned the second from
	--- Config.UI.SessionPanel.Y. Two files reading two derived numbers is the exact
	--- shape of the bug Config.UI's column comment says that table exists to catch —
	--- it was one edit away at all times. Neither file is told a Y now.
	---
	--- HEIGHT IS THE COLUMN'S BUDGET, NOT ITS CONTENT. The frame is sized to
	--- ColumnBottom so a panel laid out past it is visibly past it; the layout does
	--- not clip, and the verifier holds ColumnBottom to the reference height.
	local function buildColumn(parent: Instance)
		column = UiKit.dock(parent, {
			name = "Column",
			corner = "topLeft",
			width = UI.ColumnWidth,
			height = UI.ColumnBottom - UI.Margin,
			direction = "Vertical",
		})
	end

	--- THE TOP-RIGHT RAIL. One item today, and the reason it is a region rather than
	--- a button is that the toast column below it is derived from its height: a
	--- second item makes the rail wider, not taller, and nothing under it moves.
	local function buildUtilityRail(parent: Instance)
		local rail = UiKit.dock(parent, {
			name = "Rail",
			corner = "topRight",
			width = RAIL.ItemWidth,
			height = RAIL.ItemHeight,
			direction = "Horizontal",
		})

		local slot
		inviteButton, slot, inviteCaption = UiKit.railItem(rail, "Invite", PALETTE.good)
		UiKit.personPlus(slot, RAIL.GlyphSize, UiKit.INK, PALETTE.good)
		-- Not shown optimistically: until CanSendGameInviteAsync has answered, this
		-- control does not exist. See refreshInvite.
		inviteButton.Visible = false
		inviteButton.Activated:Connect(HUD.promptInvite)
	end

	local function buildToasts(parent: Instance)
		toastList = UiKit.dock(parent, {
			name = "Toasts",
			corner = "topRight",
			width = UI.Toast.Width,
			height = UI.Toast.ListHeight,
			-- Derived to clear the rail above it. The two shared a corner before the
			-- rail existed and the first toast of the session would have landed on
			-- top of the invite.
			insetY = UI.Toast.Y,
			direction = "Vertical",
		})
	end

	--- REBIRTH over LEAVE PLOT, on the right edge and RAISED OFF THE BOTTOM.
	---
	--- It was anchored (1,1) at (1,-Margin),(1,-Margin) — 200x112 in the corner the
	--- engine draws the touch jump button in, with the movement thumbstick in the
	--- corner opposite. Four out of five sessions are phones, so for four out of
	--- five players REBIRTH and JUMP were the same pixels. There is no API that
	--- returns either control's rectangle, so the clearance is a declared number:
	--- Config.UI.TouchReserve.Bottom, which is what insetY is measured from.
	local function buildActions(parent: Instance)
		local holder = UiKit.dock(parent, {
			name = "Actions",
			corner = "bottomRight",
			width = UI.Action.Width,
			height = UI.Action.Height,
			insetY = UI.Action.BottomGap,
			direction = "Vertical",
		})

		rebirthButton = button(holder, "REBIRTH", PALETTE.accent, {
			Size = UDim2.fromOffset(UI.Action.Width, UI.Button.primary),
			LayoutOrder = 1,
		})
		-- No TextSize: UiKit.button is TextScaled, which overrides one. There was a
		-- `TextSize = 16` here doing nothing, which is worse than no number at all —
		-- it reads as the size this label is drawn at and it never was.
		local leave = button(holder, "LEAVE PLOT", Color3.fromRGB(120, 110, 140), {
			Size = UDim2.fromOffset(UI.Action.Width, UI.Button.secondary),
			LayoutOrder = 2,
		})

		rebirthButton.Activated:Connect(function()
			HUD.showRebirthModal(state.rebirthCost)
		end)
		leave.Activated:Connect(function()
			Net.event("RequestReset"):FireServer()
		end)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- behaviour
	-- ─────────────────────────────────────────────────────────────────────────────

	local toastOrder = 0

	--- Destroy the oldest cards until the column holds no more than it is sized for.
	---
	--- WITHOUT THIS, UI.Toast.ListHeight IS DECORATION. A UIListLayout does not clip
	--- and does not stop: a burst of six toasts drew two of them out of the bottom of
	--- a frame that claimed to be five cards tall, and no assertion could be built on
	--- a height the runtime treated as advisory. The column has a real ceiling now,
	--- so the clearance against the action stack below it means something.
	---
	--- Oldest first, by LayoutOrder, because that is the order the layout draws them
	--- in and the one at the top is the one that has been readable the longest.
	local function trimToasts()
		local cards = toastList:GetChildren()
		local live = {}
		for _, child in ipairs(cards) do
			if child:IsA("Frame") then
				table.insert(live, child)
			end
		end
		if #live <= TOAST.MaxCards then
			return
		end
		table.sort(live, function(a, b)
			return a.LayoutOrder < b.LayoutOrder
		end)
		for index = 1, #live - TOAST.MaxCards do
			live[index]:Destroy()
		end
	end

	function HUD.toast(payload)
		if not toastList then
			return
		end
		toastOrder += 1

		local color = KIND_COLOR[payload.kind] or PALETTE.accent

		local card = Instance.new("Frame")
		card.Size = UDim2.fromOffset(TOAST.Width, TOAST.CardHeight)
		card.BackgroundColor3 = PALETTE.panel
		card.BackgroundTransparency = 0.08
		card.BorderSizePixel = 0
		card.LayoutOrder = toastOrder
		card.Parent = toastList
		corner(card, 12)
		stroke(card, color, 2)
		trimToasts()

		local bar = Instance.new("Frame")
		bar.Size = UDim2.fromOffset(TOAST.BarWidth, TOAST.BarHeight)
		bar.Position = UDim2.fromOffset(TOAST.BarInset, TOAST.Pad)
		bar.BackgroundColor3 = color
		bar.BorderSizePixel = 0
		bar.Parent = card
		corner(bar, math.floor(TOAST.BarWidth / 2))

		text(card, {
			Size = UDim2.fromOffset(TOAST.TextWidth, TOAST.TitleHeight),
			Position = UDim2.fromOffset(TOAST.TextX, TOAST.TitleY),
			Font = Style.Font.title,
			Text = payload.title or "",
			TextSize = TOAST.TitleTextPx,
			TextColor3 = color,
			TextTruncate = Enum.TextTruncate.AtEnd,
		})
		text(card, {
			Size = UDim2.fromOffset(TOAST.TextWidth, TOAST.BodyHeight),
			Position = UDim2.fromOffset(TOAST.TextX, TOAST.BodyY),
			Font = Style.Font.body,
			Text = payload.body or "",
			TextSize = TOAST.BodyTextPx,
			TextColor3 = PALETTE.muted,
			TextWrapped = true,
		})

		-- starts one card-width plus a hair off the right edge, and slides in
		card.Position = UDim2.fromOffset(TOAST.Width + UI.Gap, 0)
		TweenService:Create(card, TweenInfo.new(0.28, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
			Position = UDim2.fromOffset(0, 0),
		}):Play()

		task.delay(4.5, function()
			if not card.Parent then
				return
			end
			local out = TweenService:Create(card, TweenInfo.new(0.25), { BackgroundTransparency = 1 })
			out:Play()
			out.Completed:Once(function()
				card:Destroy()
			end)
		end)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the friend bonus
	-- ─────────────────────────────────────────────────────────────────────────────

	--- What the friend bonus is worth right now, as a percentage.
	local function friendPercent(friends: number): number
		return math.floor(math.min(friends, state.friendCap) * state.friendBonus * 100)
	end

	--- Visible only when there is room under the cap and the account is allowed to
	--- send invites at all. Nobody is asked to invite a fourth friend who would be
	--- worth nothing.
	---
	--- THE CAPTION IS THE OLD FRIEND ROW'S ZERO STATE, moved onto the control it was
	--- always about. With nobody here it reads what ONE friend would be worth, which
	--- is the offer; with somebody here it reads what you are already getting, in the
	--- good colour, which is the receipt. An icon with no number is a button a child
	--- presses to find out what it does.
	local function refreshInvite()
		if not inviteButton then
			return
		end
		inviteButton.Visible = state.canInvite and state.friends < state.friendCap
		if state.friends > 0 then
			inviteCaption.Text = ("+%d%%"):format(friendPercent(state.friends))
			inviteCaption.TextColor3 = UiKit.INK
		else
			-- One friend's worth, not zero: zero is what you have, and what you have
			-- is not what a button is offering you.
			inviteCaption.Text = ("+%d%%"):format(friendPercent(1))
			inviteCaption.TextColor3 = UiKit.INK
		end
	end

	--- THE TERMS LINE HAS ONE WRITER, and that is the whole reason it exists as a
	--- function. It prints three things that arrive on two different remotes — the
	--- rebirths and the KOs on Stats, the friends on SocialState — and the obvious
	--- implementation is for each handler to rewrite the label with what it knows.
	--- That is a line that is correct until the two packets disagree about which
	--- arrived last, at which point it silently drops whichever term the loser owned.
	--- Both handlers write `state` and call this.
	local function renderTerms()
		if not termsLabel then
			return
		end
		local parts = {
			("%d rebirth%s"):format(state.rebirths, state.rebirths == 1 and "" or "s"),
			("%d KO%s"):format(state.kills, state.kills == 1 and "" or "s"),
		}
		if state.friends > 0 then
			table.insert(parts, ("+%d%% friends"):format(friendPercent(state.friends)))
		end
		termsLabel.Text = table.concat(parts, "  •  ")
		termsLabel.TextColor3 = state.friends > 0 and PALETTE.good or PALETTE.muted
	end

	--- BOTH SocialService calls YIELD, so neither may run on the signal thread —
	--- an Activated handler that yields blocks the button until it returns.
	---
	--- `CanSendGameInviteAsync` can ERROR as well as return false: under some
	--- account policy restrictions it throws rather than answering. Both paths do
	--- the same thing, which is to HIDE the button. This game's audience is largely
	--- children and the failure they must never see is an error message where a
	--- button used to be.
	function HUD.promptInvite()
		task.spawn(function()
			local ok, can = pcall(function()
				return SocialService:CanSendGameInviteAsync(player)
			end)
			if not ok or not can then
				state.canInvite = false
				refreshInvite()
				return
			end
			pcall(function()
				SocialService:PromptGameInvite(player)
			end)
			-- Fire-and-forget. The server does not act on this; it rate-limits it,
			-- and it is where an invite analytics event will hang.
			Net.event("RequestInvite"):FireServer()
		end)
	end

	function HUD.applySocial(payload)
		state.friends = payload.friends or 0
		state.friendCap = payload.cap or state.friendCap
		state.friendBonus = payload.bonus or state.friendBonus

		renderTerms()
		refreshInvite()
	end

	function HUD.showRebirthModal(cost: number)
		if not overlay or overlay:FindFirstChild("RebirthModal") then
			return
		end

		-- On the OVERLAY layer, not the root one: the shade is supposed to dim the
		-- notch and the home indicator along with everything else, and the root
		-- layer is padded clear of both.
		local shade = Instance.new("Frame")
		shade.Name = "RebirthModal"
		shade.Size = UDim2.fromScale(1, 1)
		shade.BackgroundColor3 = Color3.new(0, 0, 0)
		shade.BackgroundTransparency = 0.45
		shade.BorderSizePixel = 0
		shade.ZIndex = 20
		shade.Parent = overlay

		local card = panel(shade,
			UDim2.fromOffset(REBIRTH.Width, REBIRTH.Height),
			UDim2.fromScale(0.5, 0.5), Vector2.new(0.5, 0.5))
		card.ZIndex = 21
		for _, child in ipairs(card:GetDescendants()) do
			if child:IsA("GuiObject") then
				child.ZIndex = 21
			end
		end

		text(card, {
			Size = UDim2.fromOffset(REBIRTH.ContentWidth, REBIRTH.TitleHeight),
			Position = UDim2.fromOffset(REBIRTH.Pad, REBIRTH.TitleY),
			Font = Style.Font.title,
			Text = "SAHUR REBIRTH",
			TextSize = REBIRTH.TitleTextPx,
			TextColor3 = PALETTE.accent,
			ZIndex = 22,
		})

		local affordable = state.cash >= cost
		text(card, {
			Size = UDim2.fromOffset(REBIRTH.ContentWidth, REBIRTH.BodyHeight),
			Position = UDim2.fromOffset(REBIRTH.Pad, REBIRTH.BodyY),
			Font = Style.Font.body,
			Text = ("Cost: <b>%s Tung</b>\n\nYour factory and cash are wiped, but every payout after this is permanently multiplied.\n\nNext multiplier: <b>x%.2f</b>")
				:format(Util.abbreviate(cost), Config.Rebirth.MultiplierPerRebirth ^ (state.rebirths + 1)),
			TextSize = REBIRTH.BodyTextPx,
			TextColor3 = affordable and PALETTE.text or PALETTE.muted,
			TextWrapped = true,
			ZIndex = 22,
		})

		local confirm = button(card, affordable and "DO IT" or "NOT ENOUGH TUNG",
			affordable and PALETTE.accent or PALETTE.dead, {
				Size = UDim2.fromOffset(REBIRTH.ButtonWidth, UI.Button.primary),
				Position = UDim2.fromOffset(REBIRTH.Pad, REBIRTH.ButtonY),
				ZIndex = 22,
				TextSize = REBIRTH.ButtonTextPx,
			})
		local cancel = button(card, "CANCEL", Color3.fromRGB(120, 110, 140), {
			Size = UDim2.fromOffset(REBIRTH.ButtonWidth, UI.Button.primary),
			Position = UDim2.fromOffset(REBIRTH.CancelX, REBIRTH.ButtonY),
			ZIndex = 22,
			TextSize = REBIRTH.ButtonTextPx,
		})

		confirm.Activated:Connect(function()
			if affordable then
				Net.event("RequestRebirth"):FireServer()
			end
			shade:Destroy()
		end)
		cancel.Activated:Connect(function()
			shade:Destroy()
		end)
	end

	-- The ranking Tycoon:pointAt uses. It HAS to be the same, or the card names one
	-- purchase — and now fills a bar towards its price — while the beacon out on the
	-- plot glows on a different one. A bar makes that disagreement worse, not better:
	-- it is a promise about which price you are counting towards. And keeping two
	-- hand-maintained copies of a ranking identical is not a plan, it is a hope. So
	-- there is one: Config.TrackRank, derived from TrackOrder. Factory first, then
	-- cheapest within the track, because a cabinet's first rung is cheap and
	-- cheapest-overall would point at a bat for most of the early game.
	local function cheapestAvailable()
		local best, bestRank
		for _, def in ipairs(Config.Buttons) do
			-- The gate has to be applied here too, and for the same reason the
			-- ranking does: a track that has not opened yet has no cabinet and no
			-- buttons anywhere on the plot, so naming one of its rungs as your next
			-- purchase points you at nothing.
			if not state.owned[def.id]
				and Config.trackUnlocked(def.track, state.owned)
			then
				local ok = true
				for _, req in ipairs(Config.requirementsOf(def)) do
					if not state.owned[req] then
						ok = false
						break
					end
				end
				local rank = Config.TrackRank[def.track] or 99
				if ok and (not best or rank < bestRank or (rank == bestRank and def.price < best.price)) then
					best, bestRank = def, rank
				end
			end
		end
		return best
	end

	local displayedCash = 0
	-- Lerped towards wave.bossHp by the same connection, for the same reason.
	local displayedBossHp = 0

	--- What the last Stats packet said the next purchase is: the def cheapestAvailable
	--- picked, plus the step count within its own track. `nil` once everything is
	--- built, and `nil` before the first packet arrives — which is why `hasStats`
	--- exists rather than being inferred from this being nil, because "nothing left to
	--- buy" and "nobody has told us anything yet" draw completely different cards.
	local nextUp: { name: string, price: number, label: string, step: number, of: number }? = nil
	local hasStats = false

	--- Redrawn every frame from the SAME RenderStepped connection as the balance, and
	--- off the SAME `displayedCash`.
	---
	--- That is the point of it being here rather than in applyStats. The balance
	--- counts up over about a fifth of a second after every drop; a bar and a "N to
	--- go" computed from `state.cash` would already be at the destination while the
	--- number above them was still climbing, so the card would contradict itself on
	--- every purchase — and the one moment it is being read most closely is the moment
	--- the money lands. One value drives the number, the fill and the remainder, so
	--- there is nothing for them to disagree about.
	local function renderNext()
		if not nextLabel or not hasStats then
			return
		end
		if not nextUp then
			nextLabel.Text = "Everything built. Rebirth?"
			nextLabel.TextColor3 = PALETTE.accent
			-- A full bar, in the rebirth colour: there is no next rung, and an empty
			-- track under "everything built" reads as no progress at all.
			nextFill.Size = UDim2.fromScale(1, 1)
			nextFill.BackgroundColor3 = PALETTE.accent
			nextDetail.Text = ("all %d steps built"):format(#Config.Buttons)
			nextDetail.TextColor3 = PALETTE.muted
			return
		end

		-- Guarded rather than trusted: a price of zero would make this inf, and
		-- UDim2.fromScale of a nan is a bar of undefined width rather than an error.
		local fraction = nextUp.price > 0
			and math.clamp(displayedCash / nextUp.price, 0, 1)
			or 1
		local affordable = fraction >= 1

		nextFill.Size = UDim2.fromScale(fraction, 1)
		nextFill.BackgroundColor3 = affordable and PALETTE.good or PALETTE.gold
		nextLabel.Text = ("%s — %s"):format(nextUp.name, Util.abbreviate(nextUp.price))
		nextLabel.TextColor3 = affordable and PALETTE.good or PALETTE.text
		nextDetail.Text = affordable
			and ("%s %d/%d  •  affordable now"):format(nextUp.label, nextUp.step, nextUp.of)
			or ("%s %d/%d  •  %s to go"):format(nextUp.label, nextUp.step, nextUp.of,
				Util.abbreviate(nextUp.price - displayedCash))
		nextDetail.TextColor3 = affordable and PALETTE.good or PALETTE.muted
	end

	function HUD.applyStats(payload)
		state.cash = payload.cash or 0
		state.rebirths = payload.rebirths or 0
		state.kills = payload.kills or 0
		state.multiplier = payload.multiplier or 1
		state.owned = payload.owned or {}
		state.rebirthCost = payload.rebirthCost or state.rebirthCost
		hasStats = true

		-- The product on one line, and what went into it on the next.
		multLabel.Text = ("x%.2f"):format(state.multiplier)
		renderTerms()

		local next_ = cheapestAvailable()
		if next_ then
			-- Count within the button's OWN track. "step 7 of 30" spanning the
			-- factory, the weapons cabinet and the armoury is three progress bars
			-- averaged into one meaningless number.
			local track = Config.Tracks[next_.track]
			local owned = 0
			-- Counted by CATEGORY (#125): the card says "PLOT 12 of 34", the
			-- same width the pad's own step line uses.
			for _, def in ipairs(Config.Buttons) do
				if def.category == next_.category and state.owned[def.id] then
					owned += 1
				end
			end
			nextUp = {
				name = next_.name,
				price = next_.price,
				label = Config.TrackLabel[next_.track] or "STEP",
				step = owned + 1,
				of = Config.CategoryCount[next_.category] or #track,
			}
		else
			nextUp = nil
		end
		-- Drawn once here as well as every frame, so a card that arrives on a paused
		-- or throttled RenderStepped is not blank while it waits for one.
		renderNext()

		rebirthButton.Text = ("REBIRTH  %s"):format(Util.abbreviate(state.rebirthCost))
		rebirthButton.BackgroundColor3 = state.cash >= state.rebirthCost and PALETTE.accent or PALETTE.dead
	end

	--- The last wave packet, plus the wall-clock deadline derived from its
	--- `seconds`. The server sends `seconds` ONCE per phase and the client counts
	--- it down locally, so a ticking banner costs no extra remote traffic.
	--- Typed `any` because it IS the packet: NPCService sends a different shape per
	--- phase (a boss fight carries three fields an idle one does not), and inferring
	--- a struct from the idle placeholder makes every optional field a type error.
	local wave: any = { phase = "idle", deadline = 0 }

	function HUD.applyWave(payload)
		if not waveFrame then
			return
		end
		-- The bar is lerped towards the packet (see the RenderStepped loop), which
		-- is what turns 2 Hz updates into something worth watching. The FIRST packet
		-- of a fight has to snap, though, or every boss opens with its bar sweeping
		-- up from empty and reading 0% while it does.
		if payload.bossMaxHp and not wave.bossMaxHp then
			displayedBossHp = payload.bossHp or payload.bossMaxHp
		end
		wave = payload
		wave.deadline = os.clock() + (payload.seconds or 0)
		HUD.renderWave()
	end

	--- Redrawn every frame from the RenderStepped connection that already exists
	--- for the cash counter — no second connection, and no `task.delay`.
	---
	--- The old `clear` branch hid the banner with an unguarded task.delay(4), so a
	--- wave that started inside that window had its fresh banner blanked by a
	--- stale timer. Visibility is now derived from state that any newer packet
	--- overwrites, which makes that failure unreachable rather than guarded.
	function HUD.renderWave()
		if not waveFrame then
			return
		end
		local phase = wave.phase
		local left = math.max(0, math.ceil(wave.deadline - os.clock()))
		local boss = wave.boss == true
		-- Off by default and turned on in exactly one branch, so a bar left up by a
		-- phase nobody thought about is unreachable rather than guarded against.
		bossTrack.Visible = false

		-- `Enabled` rather than `Visible`, and no background writes: the banner is a
		-- billboard hanging over the statue now, and the box is gone. Colour is the
		-- only thing left carrying tone, which is what "one line, big, nothing
		-- fancy" costs and buys.
		if phase == "idle" or phase == nil then
			waveFrame.Enabled = false
			return
		end

		if phase == "resting" then
			-- Broadcast rather than left blank: eighteen seconds of dead air with
			-- nothing on screen is most of why the old gap felt long.
			waveFrame.Enabled = left > 0
			waveLabel.Text = ("NEXT RAID IN %ds"):format(left)
			waveLabel.TextColor3 = PALETTE.muted
		elseif phase == "warning" then
			waveFrame.Enabled = true
			waveLabel.Text = boss
				and ("BOSS RAID %d IN %ds"):format(wave.wave, left)
				or ("SAHUR RAID %d IN %ds"):format(wave.wave, left)
			waveLabel.TextColor3 = boss and PALETTE.boss or PALETTE.wave
		elseif phase == "spawning" or phase == "active" then
			waveFrame.Enabled = true
			local maxHp = wave.bossMaxHp
			if maxHp and maxHp > 0 then
				-- THE SHARED OBJECTIVE TAKES THE SIGN. While the boss is up, the
				-- raider counter is the less interesting of the two numbers: what
				-- everyone in the arena is coordinating around is one health bar,
				-- and how many people it was built for.
				local fraction = math.clamp(displayedBossHp / maxHp, 0, 1)
				bossTrack.Visible = true
				bossFill.Size = UDim2.fromScale(fraction, 1)
				waveLabel.Text = ("WAVE %d BOSS  •  %d%%  •  scaled for %d"):format(
					wave.wave, math.floor(fraction * 100 + 0.5), wave.bossScale or 1)
				waveLabel.TextColor3 = PALETTE.boss
			else
				waveLabel.Text = ("WAVE %d  •  %d / %d RAIDERS"):format(
					wave.wave, wave.remaining or 0, wave.total or 0)
				waveLabel.TextColor3 = boss and PALETTE.boss or PALETTE.wave
			end
		elseif phase == "clear" then
			waveFrame.Enabled = left > 0
			waveLabel.Text = wave.forced
				and ("WAVE %d TIMED OUT"):format(wave.wave)
				or ("WAVE %d CLEARED"):format(wave.wave)
			waveLabel.TextColor3 = wave.forced and PALETTE.muted or PALETTE.good
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the two layers, and fitting them to the screen
	-- ─────────────────────────────────────────────────────────────────────────────

	--- A full-bleed transparent frame with its own UIScale.
	---
	--- The scale is not set here. It is set by applyViewport() below, which also
	--- sets the layer's SIZE to 1/scale — see there for why that pair is what makes
	--- a fromScale(1, 1) child still cover the whole screen.
	local function buildLayer(name: string): (Frame, UIScale)
		local frame = Instance.new("Frame")
		frame.Name = name
		frame.Size = UDim2.fromScale(1, 1)
		frame.BackgroundTransparency = 1
		frame.BorderSizePixel = 0
		frame.Parent = gui

		local scale = Instance.new("UIScale")
		scale.Parent = frame
		return frame, scale
	end

	--- Recomputed on every viewport change, which is one connection covering
	--- rotation, window resize and Studio's device emulator at once.
	---
	--- THE 1/SCALE SIZE IS THE POINT, and it is worth being precise about. A
	--- UIScale multiplies the whole subtree uniformly, offsets and scale-derived
	--- sizes alike — so a shade at fromScale(1, 1) inside a layer scaled to 0.62
	--- would dim 62% of the screen and leave a bright border, which is a bug you
	--- only ever see on the device you don't own. Sizing the layer itself at
	--- 1/scale cancels exactly that one factor: scale-based children come back out
	--- at full screen, while offset-based children (every panel in this file) stay
	--- multiplied by scale, which is the whole objective. It also makes the layer's
	--- own coordinate space the DESIGN space — at least ReferenceWidth x
	--- ReferenceHeight of it, by construction of UiKit.scaleFor.
	local function applyViewport()
		local camera = workspace.CurrentCamera
		if not camera or not root then
			return
		end
		local viewport = camera.ViewportSize
		local scale = UiKit.scaleFor(viewport)

		rootScale.Scale = scale
		overlayScale.Scale = scale
		root.Size = UDim2.fromScale(1 / scale, 1 / scale)
		overlay.Size = UDim2.fromScale(1 / scale, 1 / scale)

		-- The insets come back in PHYSICAL pixels and the padding is applied inside
		-- the scaled layer, so it has to be divided back out. If the engine turns
		-- out not to scale UIPadding the way it scales everything else, this errs
		-- generous (1/0.62 is a wider gutter, never a narrower one), which is the
		-- direction a guess about a notch should be wrong in.
		local insets = UiKit.safeInsets()
		rootPadding.PaddingLeft = UDim.new(0, math.round(insets.left / scale))
		rootPadding.PaddingRight = UDim.new(0, math.round(insets.right / scale))
		rootPadding.PaddingBottom = UDim.new(0, math.round(insets.bottom / scale))
		-- Top only gets the pad. IgnoreGuiInset = false already pushed this whole
		-- ScreenGui below the topbar; adding the top inset here would do it twice.
		rootPadding.PaddingTop = UDim.new(0, math.round(insets.top / scale))
	end

	function HUD.start()
		gui = Instance.new("ScreenGui")
		gui.Name = "TungHUD"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = false
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		-- Nothing set this before, so the portrait case never arising was an
		-- accident rather than a decision. This game is a landscape game: the HUD
		-- is a left column, a right column and an arena in the middle.
		pcall(function()
			gui.ScreenOrientation = Enum.ScreenOrientation.LandscapeSensor
		end)
		-- The explicit spelling of IgnoreGuiInset = false on clients new enough to
		-- have the enum. Guarded because it is newer surface than the property it
		-- restates, and restating it is worth nothing if it errors.
		pcall(function()
			(gui :: any).ScreenInsets = Enum.ScreenInsets.CoreUISafeInsets
		end)
		gui.Parent = player:WaitForChild("PlayerGui")

		root, rootScale = buildLayer("Root")
		rootPadding = Instance.new("UIPadding")
		rootPadding.Parent = root
		overlay, overlayScale = buildLayer("Overlay")

		-- One connection, rebound if the camera itself is replaced. Rotation,
		-- resize and device emulation all arrive through it.
		local viewportConnection
		local function watchCamera()
			if viewportConnection then
				viewportConnection:Disconnect()
				viewportConnection = nil
			end
			local camera = workspace.CurrentCamera
			if not camera then
				return
			end
			viewportConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(applyViewport)
			applyViewport()
		end
		workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(watchCamera)
		watchCamera()

		-- The four docked regions, then the one thing that is not on the screen at
		-- all. Column first: buildStatusCard parents into it.
		buildColumn(root)
		buildStatusCard(column)
		buildUtilityRail(root)
		buildToasts(root)
		buildActions(root)
		-- no layer: this one hangs in the world, not on the screen
		buildWaveBanner()

		Net.event("Notify").OnClientEvent:Connect(function(payload)
			if payload.kind == "rebirthPrompt" then
				HUD.showRebirthModal(payload.cost or state.rebirthCost)
			else
				HUD.toast(payload)
			end
		end)

		Net.event("Stats").OnClientEvent:Connect(HUD.applyStats)
		Net.event("WaveState").OnClientEvent:Connect(HUD.applyWave)
		Net.event("SocialState").OnClientEvent:Connect(HUD.applySocial)

		-- Ask ONCE, off the main thread, whether this account may send invites at
		-- all. The answer decides whether the button ever appears; it is not asked
		-- again on every press, because the press path re-checks it anyway and a
		-- yielding call per click is a double-fire waiting to happen.
		task.spawn(function()
			local ok, can = pcall(function()
				return SocialService:CanSendGameInviteAsync(player)
			end)
			state.canInvite = ok and can == true
			refreshInvite()
		end)

		-- smooth counting cash so big numbers feel good, and tick the raid
		-- countdown off the same connection
		RunService.RenderStepped:Connect(function(dt)
			if math.abs(displayedCash - state.cash) < 0.5 then
				displayedCash = state.cash
			else
				displayedCash += (state.cash - displayedCash) * math.min(dt * 9, 1)
			end
			cashLabel.Text = Util.abbreviate(displayedCash)
			-- ...and so does the progress bar, off the same value the label just
			-- printed. See renderNext for why they cannot be allowed to diverge.
			renderNext()

			-- The boss bar rides the SAME connection and the same easing. The server
			-- coalesces raid packets at 2 Hz, so a bar driven straight off them
			-- would step four times a second under twelve people's swings; lerped,
			-- the same four packets read as a bar going down.
			local targetHp = wave.bossHp or 0
			if math.abs(displayedBossHp - targetHp) < 0.5 then
				displayedBossHp = targetHp
			else
				displayedBossHp += (targetHp - displayedBossHp) * math.min(dt * 9, 1)
			end

			HUD.renderWave()
		end)

		return gui
	end

	-- THERE IS DELIBERATELY NO HUD.screenGui().
	--
	-- There was, and CombatClient used it to parent the hitmarker straight to the
	-- ScreenGui — outside the UIScale and outside the safe-area padding. The
	-- one-ScreenGui lint could not see it, because nothing had to make a second
	-- ScreenGui to escape the first one's layers: an accessor handed the way out.
	-- Panels get root() or overlay(); the gui itself is this file's business.

	--- The layer persistent furniture belongs on: scaled, and padded clear of the
	--- notch and the home indicator.
	function HUD.root(): Frame
		return root
	end

	--- The layer modals belong on: the same scale, no padding. A shade parented
	--- here dims the safe area too, which is what a shade is for.
	function HUD.overlay(): Frame
		return overlay
	end

	--- The top-left column, for a panel that belongs in the stack under the status
	--- card. Set a LayoutOrder; do not set a Position.
	---
	--- THIS IS NOT THE ESCAPE HATCH HUD.screenGui() WAS. That accessor handed out
	--- the raw ScreenGui, which is outside the UIScale AND outside the safe-area
	--- padding, and the one-ScreenGui lint could not see anything wrong because
	--- nothing had to make a second one. This is a child of Root: strictly inside
	--- both, and strictly narrower than root() — a panel that takes it gets the
	--- column's width and the column's stacking, which is the whole point.
	function HUD.column(): Frame
		return column
	end

	return HUD
end


__MODULES["SessionUI"] = function()
	--[[
		SessionUI.lua — the welcome-back panel, the daily / playtime claims and the
		boost button.

		Built into HUD's layers rather than a second ScreenGui so there is one place
		the game's UI lives, one ZIndex space, one UIScale and one thing to hide:
		the panel goes in HUD.column(), the welcome-back modal on HUD.overlay().

		IT NO LONGER KNOWS WHERE IT IS. The panel used to position itself at
		(Config.UI.Margin, Config.UI.SessionPanel.Y) while HUD.lua positioned the
		status card above it from Config.UI.StatusCard.Y — one column, two files, two
		reads. HUD.column() is a UIListLayout; this file sets a LayoutOrder and every
		remaining number in it is a row height from Config.UI.SessionPanel.

		The palette and the panel/text/button helpers used to be re-stated here, on
		the argument that a prototype which widens another module's public API is a
		prototype you cannot delete. Three copies later the drift risk outweighed
		the deletion cost, and they moved to src/client/UiKit.lua — which is not
		HUD's API, so the original argument is satisfied rather than overruled.

		Everything is presentation. The server sends the whole state on the
		SessionState remote and decides every claim; this file's only outbound
		messages are "I pressed the button". Note that the Vault Timer button sends
		`{ kind = "capUpgrade" }` and NOT a level or a price — the server owns which
		rung is next and what it costs.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Net = Req("Net")
	local HUD = Req("HUD")
	local UiKit = Req("UiKit")
	local Sound = Req("Sound")

	local RunService = game:GetService("RunService")
	local TweenService = game:GetService("TweenService")

	local SessionUI = {}

	local UI = Config.UI
	local PALETTE = UiKit.PALETTE
	-- Spelled from `Config`, like HUD.lua's CARD, because verify.py's config-path
	-- pass follows exactly one alias hop. Every number in this file comes from here
	-- now; there is no X and no Y among them, because HUD.column() places the panel.
	local PANEL = Config.UI.SessionPanel
	local OFFLINE = Config.UI.Modal.Offline

	local state = {
		payload = nil :: any,
		receivedAt = 0,
	}

	local column, overlay, panel, dailyRow, playtimeRow, boostButton, vaultRow, offlineRow, weekendBadge
	local playtimeFill, modalOpen = nil, false
	-- The optional rows, in the order layoutTail() stacks them, and the list
	-- Config.UI.SessionPanel.OptionalRows counts. Filled by buildPanel; see
	-- layoutTail for why the two have to agree.
	local TAIL_ROWS = nil :: any

	-- ─────────────────────────────────────────────────────────────────────────────
	-- builders
	-- ─────────────────────────────────────────────────────────────────────────────

	local corner, frame, text = UiKit.corner, UiKit.panel, UiKit.text

	--- THE ONE PLACE THIS PANEL DISAGREES WITH THE REST OF THE UI, and the reason
	--- the merge into UiKit was not a straight deletion. Every button in HUD and
	--- UpgradeUI is TextScaled; every button in here is sized text at 15, because
	--- these labels are long ("BOOST READY IN 12:04") in boxes that are not, and
	--- TextScaled would set each of them at a different size. Two properties
	--- pre-seeded into `props` before forwarding buys that back without touching
	--- the three call sites below — and it is deliberately NOT tidied away in the
	--- same change that moved the helpers, so that if sized text turns out to be
	--- the wrong call on a phone there is one function to look at.
	local function button(parent: Instance, label: string, color: Color3, props): TextButton
		props = props or {}
		if props.TextScaled == nil then
			props.TextScaled = false
		end
		if props.TextSize == nil then
			props.TextSize = 15
		end
		return UiKit.button(parent, label, color, props)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- formatting
	-- ─────────────────────────────────────────────────────────────────────────────

	--- "6h 12m" — the welcome-back panel has to say how long you were gone, and a
	--- raw second count is not an answer to that question.
	local function describe(seconds: number): string
		seconds = math.max(0, math.floor(seconds))
		local days = seconds // 86400
		local hours = (seconds % 86400) // 3600
		local minutes = (seconds % 3600) // 60
		if days > 0 then
			return ("%dd %dh"):format(days, hours)
		elseif hours > 0 then
			return ("%dh %dm"):format(hours, minutes)
		elseif minutes > 0 then
			return ("%dm"):format(minutes)
		end
		return ("%ds"):format(seconds)
	end

	--- mm:ss for anything under an hour, h:mm:ss above it
	local function clockText(seconds: number): string
		seconds = math.max(0, math.floor(seconds))
		if seconds >= 3600 then
			return ("%d:%02d:%02d"):format(seconds // 3600, (seconds % 3600) // 60, seconds % 60)
		end
		return ("%d:%02d"):format(seconds // 60, seconds % 60)
	end

	--- Seconds elapsed since the last server push, so every countdown ticks
	--- smoothly between pushes instead of stepping once every five seconds.
	local function elapsed(): number
		if state.receivedAt == 0 then
			return 0
		end
		return os.clock() - state.receivedAt
	end

	local function click()
		Sound.play("ui", { volume = 0.4 })
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- welcome-back modal
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The panel is half the value of offline earnings, and the claim IS the
	--- reward: nothing is ever credited silently, so the number counts up in front
	--- of you and you press the button.
	function SessionUI.showOfflineModal(offline)
		if not overlay or modalOpen or not offline then
			return
		end
		modalOpen = true

		-- HUD.overlay(), not HUD.root(): the shade has to dim the safe area it is
		-- covering, and the root layer is padded clear of exactly that strip.
		local shade = Instance.new("Frame")
		shade.Name = "OfflineModal"
		shade.Size = UDim2.fromScale(1, 1)
		shade.BackgroundColor3 = Color3.new(0, 0, 0)
		shade.BackgroundTransparency = 0.45
		shade.BorderSizePixel = 0
		shade.ZIndex = 30
		shade.Parent = overlay

		local card = frame(shade,
			UDim2.fromOffset(OFFLINE.Width, OFFLINE.Height),
			UDim2.fromScale(0.5, 0.5), Vector2.new(0.5, 0.5))
		card.ZIndex = 31
		for _, child in ipairs(card:GetDescendants()) do
			if child:IsA("GuiObject") then
				child.ZIndex = 31
			end
		end

		text(card, {
			Size = UDim2.fromOffset(OFFLINE.ContentWidth, OFFLINE.TitleHeight),
			Position = UDim2.fromOffset(OFFLINE.Pad, OFFLINE.TitleY),
			Font = Style.Font.title,
			Text = "WELCOME BACK",
			TextSize = OFFLINE.TitleTextPx,
			TextColor3 = PALETTE.accent,
			ZIndex = 32,
		})

		text(card, {
			Size = UDim2.fromOffset(OFFLINE.ContentWidth, OFFLINE.AwayHeight),
			Position = UDim2.fromOffset(OFFLINE.Pad, OFFLINE.AwayY),
			Font = Style.Font.body,
			Text = ("Away for <b>%s</b> — your factory kept running."):format(describe(offline.seconds)),
			TextSize = OFFLINE.AwayTextPx,
			TextColor3 = PALETTE.muted,
			ZIndex = 32,
		})

		local amount = text(card, {
			Size = UDim2.fromOffset(OFFLINE.ContentWidth, OFFLINE.AmountHeight),
			Position = UDim2.fromOffset(OFFLINE.Pad, OFFLINE.AmountY),
			Font = Style.Font.title,
			Text = "0",
			TextSize = OFFLINE.AmountTextPx,
			TextColor3 = PALETTE.gold,
			ZIndex = 32,
		})

		text(card, {
			Size = UDim2.fromOffset(OFFLINE.ContentWidth, OFFLINE.RateHeight),
			Position = UDim2.fromOffset(OFFLINE.Pad, OFFLINE.RateY),
			Font = Style.Font.body,
			Text = ("%d%% of %s/sec for %s"):format(
				math.floor((offline.rate or 0) * 100 + 0.5),
				Util.abbreviate(offline.perSecond or 0),
				describe(offline.creditedSeconds or offline.seconds)),
			TextSize = OFFLINE.RateTextPx,
			TextColor3 = PALETTE.muted,
			ZIndex = 32,
		})

		-- The cap line. If it clipped you, saying so and naming the fix is the
		-- whole difference between a cap that reads as a goal and one that reads
		-- as a confiscation.
		local capText, capColor
		if offline.clipped then
			local upgrade = offline.upgrade
			capText = ("<b>Capped at %dh.</b> %s of tung went uncollected."):format(
				offline.capHours, Util.abbreviate(offline.lost or 0))
			if upgrade then
				capText ..= ("\n<b>%s</b> banks %dh instead — %s, in the session panel."):format(
					upgrade.name, upgrade.hours, Util.abbreviate(upgrade.cost))
			else
				capText ..= "\nYou already own the longest vault timer."
			end
			capColor = PALETTE.bad
		else
			capText = ("Well inside your %dh offline cap."):format(offline.capHours)
			capColor = PALETTE.good
		end

		text(card, {
			Size = UDim2.fromOffset(OFFLINE.ContentWidth, OFFLINE.CapHeight),
			Position = UDim2.fromOffset(OFFLINE.Pad, OFFLINE.CapY),
			Font = Style.Font.body,
			Text = capText,
			TextSize = OFFLINE.CapTextPx,
			TextColor3 = capColor,
			TextWrapped = true,
			ZIndex = 32,
		})

		local collect = button(card, ("COLLECT %s"):format(Util.abbreviate(offline.earned)), PALETTE.good, {
			Size = UDim2.fromOffset(OFFLINE.ContentWidth, UI.Button.primary),
			Position = UDim2.fromOffset(OFFLINE.Pad, OFFLINE.ButtonY),
			TextSize = OFFLINE.ButtonTextPx,
			ZIndex = 32,
		})

		-- count-up: the number arriving instantly is a fact, the number climbing is
		-- a payout
		local shown = 0
		local connection
		connection = RunService.RenderStepped:Connect(function(dt)
			if not amount.Parent then
				connection:Disconnect()
				return
			end
			shown += (offline.earned - shown) * math.min(dt * 4, 1)
			if offline.earned - shown < 1 then
				shown = offline.earned
				connection:Disconnect()
			end
			amount.Text = Util.abbreviate(shown)
		end)

		collect.Activated:Connect(function()
			click()
			Sound.play("purchase", { volume = 0.6 })
			Net.event("RequestClaim"):FireServer({ kind = "offline" })
			modalOpen = false
			shade:Destroy()
		end)

		card.Position = UDim2.fromScale(0.5, 0.56)
		TweenService:Create(card, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
			Position = UDim2.fromScale(0.5, 0.5),
		}):Play()
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the session panel
	-- ─────────────────────────────────────────────────────────────────────────────

	local function buildRow(parent: Instance, y: number, height: number, title: string)
		local row = Instance.new("Frame")
		row.Size = UDim2.fromOffset(PANEL.RowWidth, height)
		row.Position = UDim2.fromOffset(PANEL.Pad, y)
		row.BackgroundColor3 = PALETTE.panel2
		row.BackgroundTransparency = 0.25
		row.BorderSizePixel = 0
		row.Parent = parent
		corner(row, 10)

		local titleLabel = text(row, {
			Size = UDim2.fromOffset(PANEL.ActionTextWidth, PANEL.RowTitleHeight),
			Position = UDim2.fromOffset(PANEL.RowPad, PANEL.RowPadY),
			Font = Style.Font.title,
			Text = title,
			TextSize = PANEL.RowTitleTextPx,
			TextColor3 = PALETTE.text,
		})
		local subLabel = text(row, {
			Size = UDim2.fromOffset(PANEL.ActionTextWidth, PANEL.RowSubHeight),
			Position = UDim2.fromOffset(PANEL.RowPad, PANEL.RowSubY),
			Font = Style.Font.body,
			Text = "",
			TextSize = PANEL.RowSubTextPx,
			TextColor3 = PALETTE.muted,
		})
		-- A 66x30 pill was a 41x19 physical target at MinScale, which is a coin
		-- flip with a thumb. Full touch height, vertically centred in whatever row
		-- it lands in — the rows are 46, 50 and 56 tall.
		local action = button(row, "CLAIM", PALETTE.good, {
			Size = UDim2.fromOffset(PANEL.ActionWidth, UI.Button.pill),
			Position = UDim2.fromOffset(PANEL.ActionX, math.round((height - UI.Button.pill) / 2)),
			TextSize = PANEL.ActionTextPx,
			Visible = false,
		})

		return { row = row, title = titleLabel, sub = subLabel, action = action }
	end

	--- NO POSITION, AND NO PANEL_X / PANEL_Y ANY MORE. The parent is HUD.column(),
	--- which stacks it under the status card; this file used to read
	--- Config.UI.SessionPanel.Y and HUD.lua used to read Config.UI.StatusCard.Y, and
	--- two files deriving where one column goes is the disagreement Config.UI's
	--- column comment says that table exists to prevent.
	local function buildPanel()
		panel = frame(column, UDim2.fromOffset(PANEL.Width, PANEL.Height), UDim2.fromOffset(0, 0))
		panel.Name = "Session"
		panel.LayoutOrder = 2
		panel.Visible = false

		text(panel, {
			Size = UDim2.fromOffset(PANEL.ActionTextWidth, PANEL.HeadHeight),
			Position = UDim2.fromOffset(PANEL.Pad, PANEL.HeadPad),
			Font = Style.Font.body,
			Text = "SESSION",
			TextSize = PANEL.HeadTextPx,
			TextColor3 = PALETTE.muted,
		})

		-- the weekend bonus is server-wide and invisible unless something says so
		weekendBadge = text(panel, {
			Size = UDim2.fromOffset(PANEL.BadgeWidth, PANEL.HeadHeight),
			Position = UDim2.fromOffset(PANEL.BadgeX, PANEL.HeadPad),
			Font = Style.Font.body,
			Text = "",
			TextSize = PANEL.HeadTextPx,
			TextXAlignment = Enum.TextXAlignment.Right,
			TextColor3 = PALETTE.gold,
		})

		dailyRow = buildRow(panel, PANEL.DailyY, PANEL.DailyHeight, "DAILY STREAK")
		playtimeRow = buildRow(panel, PANEL.PlaytimeY, PANEL.PlaytimeHeight, "PLAYTIME")

		-- a thin progress bar along the bottom of the playtime row: the ladder is
		-- the only part of this panel with a "how far to go" answer
		local track = Instance.new("Frame")
		track.Size = UDim2.fromOffset(PANEL.BarWidth, PANEL.BarHeight)
		track.Position = UDim2.fromOffset(PANEL.RowPad, PANEL.BarY)
		track.BackgroundColor3 = PALETTE.panel
		track.BorderSizePixel = 0
		track.Parent = playtimeRow.row
		corner(track, 2)

		playtimeFill = Instance.new("Frame")
		playtimeFill.Size = UDim2.fromScale(0, 1)
		playtimeFill.BackgroundColor3 = PALETTE.accent
		playtimeFill.BorderSizePixel = 0
		playtimeFill.Parent = track
		corner(playtimeFill, 2)

		boostButton = button(panel, "BOOST", PALETTE.gold, {
			Size = UDim2.fromOffset(PANEL.RowWidth, UI.Button.secondary),
			Position = UDim2.fromOffset(PANEL.Pad, PANEL.BoostY),
			TextSize = PANEL.BoostTextPx,
		})

		-- Both of these are positioned by layoutTail() rather than here: they come
		-- and go independently and a fixed y for each leaves a hole in the panel.
		vaultRow = buildRow(panel, PANEL.StackTop, PANEL.RowHeight, "VAULT TIMER")
		vaultRow.row.Visible = false
		vaultRow.action.BackgroundColor3 = PALETTE.gold

		offlineRow = buildRow(panel, PANEL.StackTop, PANEL.RowHeight, "OFFLINE TUNG")
		TAIL_ROWS = { vaultRow, offlineRow }
		offlineRow.row.Visible = false
		offlineRow.action.Text = "OPEN"
		offlineRow.action.BackgroundColor3 = PALETTE.gold

		dailyRow.action.Activated:Connect(function()
			click()
			Net.event("RequestClaim"):FireServer({ kind = "daily" })
		end)

		playtimeRow.action.Activated:Connect(function()
			click()
			local payload = state.payload
			local rungs = payload and payload.playtime and payload.playtime.rungs
			if not rungs then
				return
			end
			for _, rung in ipairs(rungs) do
				if rung.status == "ready" then
					Net.event("RequestClaim"):FireServer({ kind = "playtime", index = rung.index })
					return
				end
			end
		end)

		boostButton.Activated:Connect(function()
			click()
			Net.event("RequestBoost"):FireServer()
		end)

		vaultRow.action.Activated:Connect(function()
			click()
			-- INTENT ONLY. No level, no price: the server reads both from Config and
			-- spends through Economy, so a client that sends a different number gets
			-- charged the real one.
			Net.event("RequestClaim"):FireServer({ kind = "capUpgrade" })
		end)

		offlineRow.action.Activated:Connect(function()
			click()
			local payload = state.payload
			if payload and payload.offline then
				SessionUI.showOfflineModal(payload.offline)
			end
		end)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- rendering
	-- ─────────────────────────────────────────────────────────────────────────────

	local function renderDaily(daily)
		if not daily then
			dailyRow.row.Visible = false
			return
		end
		dailyRow.row.Visible = true

		if daily.available then
			dailyRow.title.Text = ("DAILY  •  DAY %d"):format(daily.nextStreak)
			dailyRow.sub.Text = daily.milestone
				and ("%s  +  %s milestone"):format(Util.abbreviate(daily.reward - daily.milestone), Util.abbreviate(daily.milestone))
				or ("%s waiting"):format(Util.abbreviate(daily.reward))
			dailyRow.sub.TextColor3 = PALETTE.good
			dailyRow.action.Visible = true
			dailyRow.action.Text = "CLAIM"
			dailyRow.action.BackgroundColor3 = PALETTE.good
		else
			dailyRow.title.Text = ("DAILY  •  %d DAY STREAK"):format(daily.streak)
			dailyRow.sub.Text = ("next in %s  •  %dh grace"):format(
				describe(math.max(0, (daily.resetIn or 0) - elapsed())), daily.graceHours)
			dailyRow.sub.TextColor3 = PALETTE.muted
			dailyRow.action.Visible = false
		end
	end

	local function renderPlaytime(playtime)
		if not playtime then
			playtimeRow.row.Visible = false
			return
		end
		playtimeRow.row.Visible = true

		-- the server only counts ACTIVE seconds, so this clock is allowed to run
		-- ahead of it locally but must never claim on its own
		local active = playtime.activeSeconds + elapsed()

		local ready, nextRung
		for _, rung in ipairs(playtime.rungs) do
			if rung.status == "ready" and not ready then
				ready = rung
			elseif rung.status == "locked" and not nextRung then
				nextRung = rung
			end
		end

		if ready then
			playtimeRow.title.Text = ("PLAYTIME  •  %d MIN"):format(ready.minutes)
			playtimeRow.sub.Text = ("%s ready to claim"):format(Util.abbreviate(ready.reward))
			playtimeRow.sub.TextColor3 = PALETTE.good
			playtimeRow.action.Visible = true
			playtimeFill.Size = UDim2.fromScale(1, 1)
		elseif nextRung then
			local target = nextRung.minutes * 60
			playtimeRow.title.Text = "PLAYTIME"
			playtimeRow.sub.Text = ("%s at %d min  •  %s to go"):format(
				Util.abbreviate(nextRung.reward), nextRung.minutes, clockText(target - active))
			playtimeRow.sub.TextColor3 = PALETTE.muted
			playtimeRow.action.Visible = false
			local previous = 0
			for _, rung in ipairs(playtime.rungs) do
				if rung.index < nextRung.index then
					previous = rung.minutes * 60
				end
			end
			local span = math.max(1, target - previous)
			playtimeFill.Size = UDim2.fromScale(math.clamp((active - previous) / span, 0, 1), 1)
		else
			playtimeRow.title.Text = "PLAYTIME"
			-- The ladder is claimed per UTC DAY now, not per session, so this line
			-- has to say when it comes back rather than implying a reconnect does it.
			playtimeRow.sub.Text = ("whole ladder claimed  •  resets in %s"):format(
				describe(math.max(0, (playtime.resetIn or 0) - elapsed())))
			playtimeRow.sub.TextColor3 = PALETTE.muted
			playtimeRow.action.Visible = false
			playtimeFill.Size = UDim2.fromScale(1, 1)
		end
	end

	--- The Vault Timer, as a row you can press. The panel used to name this upgrade
	--- in the welcome-back modal and offer no way to buy it.
	local function renderVault(payload)
		local upgrade = payload.capUpgrade
		if not upgrade then
			vaultRow.row.Visible = false     -- the longest timer is already owned
			return
		end
		vaultRow.row.Visible = true
		vaultRow.title.Text = upgrade.name:upper()
		vaultRow.sub.Text = ("banks %dh offline, up from %dh"):format(
			upgrade.hours, payload.capHours or upgrade.hours)
		vaultRow.sub.TextColor3 = PALETTE.muted
		vaultRow.action.Visible = true
		vaultRow.action.Text = Util.abbreviate(upgrade.cost)
	end

	local function renderBoost(boost)
		if not boost then
			boostButton.Visible = false
			return
		end
		boostButton.Visible = true

		local since = elapsed()
		if boost.active then
			boostButton.Text = ("x%g BOOST  •  %s"):format(boost.multiplier, clockText(boost.secondsLeft - since))
			boostButton.BackgroundColor3 = PALETTE.good
		elseif boost.cooldownLeft - since > 0 then
			boostButton.Text = ("BOOST READY IN %s"):format(clockText(boost.cooldownLeft - since))
			boostButton.BackgroundColor3 = PALETTE.dead
		else
			boostButton.Text = ("CLAIM x%g BOOST  •  %d MIN"):format(boost.multiplier, boost.duration // 60)
			boostButton.BackgroundColor3 = PALETTE.gold
		end

		weekendBadge.Text = boost.weekend and ("WEEKEND x%g"):format(boost.weekendMultiplier) or ""
	end

	--- invariant: stack whichever optional rows are showing, and size the panel to
	--- them. THE PANEL'S HEIGHT HAS EXACTLY ONE OWNER AND IT IS THIS FUNCTION.
	---
	--- A second write in render() is invisible — this one lands after it — and the
	--- last one to try it was wrong by a whole row, because both optional rows show
	--- at once for any returning player who has not maxed the vault.
	---
	--- THE ARITHMETIC BELOW IS THE ARITHMETIC Config DERIVES TallHeight FROM, so a
	--- full tail produces exactly TallHeight and the number the verifier holds the
	--- column to is a number this function can actually reach. TAIL_ROWS is what
	--- OptionalRows counts: adding a third row here without adding it there is a
	--- panel that grows past the budget again, and tools/testing/specs/hud_spec.lua
	--- is what says so.
	local function layoutTail()
		local y = PANEL.StackTop
		local shown = 0
		for _, row in ipairs(TAIL_ROWS) do
			if row.row.Visible then
				row.row.Position = UDim2.fromOffset(PANEL.Pad, y)
				y += PANEL.RowHeight + PANEL.RowGap
				shown += 1
			end
		end
		local height = shown == 0 and PANEL.Height or (y - PANEL.RowGap + PANEL.TailPad)
		panel.Size = UDim2.fromOffset(PANEL.Width, height)
	end

	local function render()
		local payload = state.payload
		if not payload or not panel then
			return
		end
		panel.Visible = true

		renderDaily(payload.daily)
		renderPlaytime(payload.playtime)
		renderBoost(payload.boost)
		renderVault(payload)

		if payload.offline then
			offlineRow.row.Visible = true
			offlineRow.sub.Text = ("%s from %s away"):format(
				Util.abbreviate(payload.offline.earned), describe(payload.offline.seconds))
			offlineRow.sub.TextColor3 = PALETTE.gold
			offlineRow.action.Visible = true
		else
			offlineRow.row.Visible = false
		end

		-- ...and layoutTail owns the height. There were two sizes written here and
		-- both were dead: this function set one and the next line overwrote it.
		layoutTail()
	end

	function SessionUI.start()
		-- HUD.column(), not HUD.root(): this panel belongs in the left column's
		-- stack, and taking the column rather than the layer is what stops it having
		-- an opinion about where that column starts.
		column = HUD.column()
		if not column then
			-- HUD.start() runs first in Main.client.lua, but a prototype that
			-- assumes boot order is a prototype that breaks when the boot order
			-- changes
			for _ = 1, 100 do
				task.wait(0.1)
				column = HUD.column()
				if column then
					break
				end
			end
			if not column then
				warn("[Tung] SessionUI: no HUD column to build into")
				return
			end
		end
		overlay = HUD.overlay()

		buildPanel()

		Net.event("SessionState").OnClientEvent:Connect(function(payload)
			if type(payload) ~= "table" then
				return
			end
			local hadOffline = state.payload and state.payload.offline
			state.payload = payload
			state.receivedAt = os.clock()
			render()

			-- first sight of a pending offline grant opens the panel by itself;
			-- after that it lives in the row so a mis-click cannot lose it
			if payload.offline and not hadOffline then
				SessionUI.showOfflineModal(payload.offline)
			end
		end)

		-- countdowns tick locally between pushes; the server still owns every
		-- number this reads from
		task.spawn(function()
			while true do
				task.wait(1)
				if state.payload then
					render()
				end
			end
		end)
	end

	return SessionUI
end


__MODULES["UiKit"] = function()
	--[[
		UiKit.lua — the vocabulary every on-screen panel is built out of, plus the
		two measurements that decide whether it survives a phone.

		CLIENT, NOT SHARED, DELIBERATELY. Req searches TungShared then TungClient, so
		`Req("UiKit")` resolves from the client root exactly as `Req("HUD")` already
		does in SessionUI. In src/shared it would be compiled into the SERVER paste
		build too — tools/pack.py builds that from [src/shared, src/server] — which
		hands the server a vocabulary for screen UI it must never draw.

		WHY IT EXISTS. corner / stroke / panel / text / button and the palette were
		written out three times: HUD.lua, SessionUI.lua and UpgradeUI.lua. Two of
		those files carried a header apologising for the copy and naming this module
		as the fix. Three copies of a palette is three chances for the game to be two
		different purples, and the one that drifts first is always the one nobody
		opens.

		IT ALSO OWNS WHERE A REGION GOES, not just what it looks like. `dock` names
		the four corners of the design canvas; before it, five call sites in three
		files each spelled out their own AnchorPoint and their own
		`UDim2.new(1, -UI.Margin, 1, -UI.Margin)`, and the left column's two panels
		were placed by two files reading the same Config keys separately. A panel
		asks for a corner now and gets the anchor, the inset and the list alignment
		that agree with it.

		ONE DIVERGENCE SURVIVED THE MERGE, and it is the only interesting thing in
		this file. HUD and UpgradeUI build TextScaled buttons with no TextSize;
		SessionUI's are sized text (TextScaled = false, TextSize = 15). `button` here
		is the TextScaled one, and SessionUI keeps a small shim that pre-seeds the
		other two properties before forwarding. Rewriting that panel's call sites to
		remove a shim is how a refactor turns into a redesign.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")

	local GuiService = game:GetService("GuiService")

	local UI = Config.UI
	-- Spelled from `Config` rather than from `UI`, exactly like HUD.lua's CARD, so
	-- verify.py's config-path pass can resolve it: it follows ONE alias hop, and a
	-- `local RAIL = UI.Rail` would be a name it has no way to check reads against.
	local RAIL = Config.UI.Rail

	local UiKit = {}

	--- THE PALETTE, once. This is the union of the three copies it replaces: `wave`
	--- and `boss` came from HUD (promoted out of a toast-only table, because the
	--- raid banner had inline literals of the same two colours and the raid read as
	--- two different oranges depending on which widget you looked at), and `dead`
	--- came from SessionUI and UpgradeUI, where it greys out a claimed or
	--- unaffordable control.
	UiKit.PALETTE = {
		panel   = Color3.fromRGB(22, 18, 32),
		panel2  = Color3.fromRGB(32, 26, 46),
		accent  = Color3.fromRGB(190, 130, 255),
		gold    = Color3.fromRGB(255, 205, 90),
		good    = Color3.fromRGB(120, 235, 160),
		bad     = Color3.fromRGB(255, 110, 110),
		text    = Color3.fromRGB(238, 232, 250),
		muted   = Color3.fromRGB(160, 150, 180),
		dead    = Color3.fromRGB(90, 84, 104),
		wave    = Color3.fromRGB(255, 150, 60),
		boss    = Color3.fromRGB(255, 90, 60),
	}

	--- The ink every button and pill prints its label in. Dark, because every
	--- button colour in the palette above is a bright one.
	UiKit.INK = Color3.fromRGB(20, 16, 28)

	local PALETTE = UiKit.PALETTE

	-- ─────────────────────────────────────────────────────────────────────────────
	-- builders
	-- ─────────────────────────────────────────────────────────────────────────────

	function UiKit.corner(parent: Instance, radius: number): UICorner
		local c = Instance.new("UICorner")
		c.CornerRadius = UDim.new(0, radius)
		c.Parent = parent
		return c
	end

	function UiKit.stroke(parent: Instance, color: Color3, thickness: number?): UIStroke
		local s = Instance.new("UIStroke")
		s.Color = color
		s.Thickness = thickness or 2
		s.Transparency = 0.35
		s.Parent = parent
		return s
	end

	--- A card: rounded, outlined, with the vertical gradient that makes a stack of
	--- them read as one surface rather than as eight rectangles.
	function UiKit.panel(parent: Instance, size: UDim2, position: UDim2, anchor: Vector2?): Frame
		local f = Instance.new("Frame")
		f.Size = size
		f.Position = position
		f.AnchorPoint = anchor or Vector2.zero
		f.BackgroundColor3 = PALETTE.panel
		f.BackgroundTransparency = 0.12
		f.BorderSizePixel = 0
		f.Parent = parent
		UiKit.corner(f, 14)
		UiKit.stroke(f, PALETTE.accent, 2)

		local gradient = Instance.new("UIGradient")
		gradient.Color = ColorSequence.new(PALETTE.panel2, PALETTE.panel)
		gradient.Rotation = 90
		gradient.Parent = f
		return f
	end

	function UiKit.text(parent: Instance, props): TextLabel
		local l = Instance.new("TextLabel")
		l.BackgroundTransparency = 1
		l.Font = Style.Font.body
		l.TextColor3 = PALETTE.text
		l.TextXAlignment = Enum.TextXAlignment.Left
		l.TextScaled = false
		l.RichText = true
		for k, v in pairs(props) do
			(l :: any)[k] = v
		end
		l.Parent = parent
		return l
	end

	--- TextScaled by default — see the header. A caller that wants sized text
	--- passes TextScaled = false and a TextSize in `props`, which land after these
	--- defaults do.
	function UiKit.button(parent: Instance, label: string, color: Color3, props): TextButton
		local b = Instance.new("TextButton")
		b.BackgroundColor3 = color
		b.BackgroundTransparency = 0.1
		b.BorderSizePixel = 0
		b.AutoButtonColor = true
		b.Font = Style.Font.title
		b.Text = label
		b.TextColor3 = UiKit.INK
		b.TextScaled = true
		for k, v in pairs(props or {}) do
			(b :: any)[k] = v
		end
		b.Parent = parent
		UiKit.corner(b, 10)
		return b
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- putting a region against an edge
	-- ─────────────────────────────────────────────────────────────────────────────

	--- THE FOUR CORNERS, and the AnchorPoint and list alignment each one implies.
	---
	--- A dock is (anchor, position, alignment) and the three have to agree: a frame
	--- anchored (1,0) and positioned from the LEFT edge is off the right side of the
	--- screen, and a right-hand column whose list layout aligns Left grows away from
	--- the edge it is docked to. Naming the corner once is what stops a call site
	--- getting two of the three right.
	local DOCKS = {
		topLeft     = { x = 0, y = 0, alignX = "Left",  alignY = "Top" },
		topRight    = { x = 1, y = 0, alignX = "Right", alignY = "Top" },
		bottomLeft  = { x = 0, y = 1, alignX = "Left",  alignY = "Bottom" },
		bottomRight = { x = 1, y = 1, alignX = "Right", alignY = "Bottom" },
	}

	--- invariant: a transparent region pinned to one corner of the design canvas,
	--- and THE ONLY WAY ANYTHING GETS PINNED TO AN EDGE. Five call sites spelling
	--- out their own AnchorPoint is five chances to disagree about what "against
	--- the edge" means, and they did.
	---
	--- `insetX` / `insetY` default to UI.Margin and are the distance from that edge,
	--- always measured INWARD whichever corner it is, so a caller never writes the
	--- sign. UI.Action passes an insetY of TouchReserve.Bottom to sit above the
	--- engine's own controls; everything else takes the margin.
	---
	--- `direction` is "Vertical" or "Horizontal", and attaches a UIListLayout that
	--- stacks children away from the docked corner with UI.Gap between them. Omit it
	--- for a region that positions its own children.
	function UiKit.dock(parent: Instance, opts): Frame
		local spot = DOCKS[opts.corner]
		if not spot then
			-- Loud, like Style.distance: a typo'd corner that fell back to top-left
			-- would be a panel silently drawn on top of the status card.
			error(("[Tung] unknown dock corner %q; expected topLeft/topRight/bottomLeft/bottomRight")
				:format(tostring(opts.corner)), 2)
		end

		local insetX = opts.insetX or UI.Margin
		local insetY = opts.insetY or UI.Margin

		local frame = Instance.new("Frame")
		frame.Name = opts.name
		frame.AnchorPoint = Vector2.new(spot.x, spot.y)
		-- The scale term picks the edge and the offset term steps inward from it, so
		-- the same expression serves all four corners.
		frame.Position = UDim2.new(
			spot.x, spot.x == 0 and insetX or -insetX,
			spot.y, spot.y == 0 and insetY or -insetY)
		frame.Size = UDim2.fromOffset(opts.width, opts.height)
		frame.BackgroundTransparency = 1
		frame.BorderSizePixel = 0
		frame.Parent = parent

		if opts.direction then
			local layout = Instance.new("UIListLayout")
			layout.FillDirection = (Enum.FillDirection :: any)[opts.direction]
			layout.Padding = UDim.new(0, UI.Gap)
			layout.HorizontalAlignment = (Enum.HorizontalAlignment :: any)[spot.alignX]
			layout.VerticalAlignment = (Enum.VerticalAlignment :: any)[spot.alignY]
			layout.SortOrder = Enum.SortOrder.LayoutOrder
			layout.Parent = frame
		end

		return frame
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the rail, and the one glyph on it
	-- ─────────────────────────────────────────────────────────────────────────────

	--- mechanism: a person with a plus, drawn out of rounded rectangles — a head, a
	--- domed torso clipped at the container's bottom edge, and a plus in a disc over
	--- its shoulder. design:D-05 for why it is drawn rather than uploaded.
	---
	--- `ink` is the glyph and `cut` is the colour showing THROUGH the plus — pass
	--- the button's own background for that, and the plus reads as a hole punched in
	--- the disc rather than as a third colour competing with the first two.
	---
	--- Every number is a fraction of `size`. They are here rather than in Config
	--- because they are the shape of a drawing, not the layout of a card: nothing
	--- else on screen is measured against them and the verifier has nothing to
	--- compare them to. The one number that IS layout, how big the glyph is drawn,
	--- is UI.Rail.GlyphSize and comes in as `size`.
	function UiKit.personPlus(parent: Instance, size: number, ink: Color3, cut: Color3): Frame
		local holder = Instance.new("Frame")
		holder.Name = "Glyph"
		holder.Size = UDim2.fromOffset(size, size)
		holder.BackgroundTransparency = 1
		holder.BorderSizePixel = 0
		-- The torso is a full rounded rectangle whose bottom half is meant to be off
		-- the picture; without this it is a pill floating under a head.
		holder.ClipsDescendants = true
		holder.Parent = parent

		local function block(name: string, w: number, h: number, x: number, y: number, colour: Color3, radius: number)
			local part = Instance.new("Frame")
			part.Name = name
			part.Size = UDim2.fromOffset(w, h)
			part.Position = UDim2.fromOffset(x, y)
			part.BackgroundColor3 = colour
			part.BorderSizePixel = 0
			part.Parent = holder
			if radius > 0 then
				UiKit.corner(part, radius)
			end
			return part
		end

		-- The person is pushed left of centre to leave the lower right for the disc.
		local head = math.floor(size * 0.34)
		local torsoW, torsoH = math.floor(size * 0.60), math.floor(size * 0.46)
		local centre = math.floor(size * 0.39)
		block("Head", head, head, centre - math.floor(head / 2), math.floor(size * 0.08),
			ink, math.floor(head / 2))
		block("Torso", torsoW, torsoH, centre - math.floor(torsoW / 2), math.floor(size * 0.48),
			ink, math.floor(torsoW / 2))

		local disc = math.floor(size * 0.46)
		local discX, discY = size - disc, size - disc
		block("Plus", disc, disc, discX, discY, ink, math.floor(disc / 2))

		-- The two bars are children of the holder, not of the disc, so they are
		-- positioned in one coordinate space; the disc is behind them by creation
		-- order under ZIndexBehavior.Sibling.
		local barLong, barShort = math.floor(disc * 0.52), math.max(2, math.floor(disc * 0.16))
		local barX = discX + math.floor((disc - barLong) / 2)
		local barY = discY + math.floor((disc - barShort) / 2)
		block("PlusH", barLong, barShort, barX, barY, cut, 0)
		block("PlusV", barShort, barLong, discX + math.floor((disc - barShort) / 2),
			discY + math.floor((disc - barLong) / 2), cut, 0)

		return holder
	end

	--- A rail item: a glyph over a caption, the whole thing one hit target.
	---
	--- The caption is not decoration. This is the only control in the game that asks
	--- a player to do something outside the server, and the number under the glyph
	--- is what the ask is worth — an icon on its own is a button a child has to
	--- press to find out what it does.
	---
	--- Returns the button and its caption label; the caller draws into the glyph
	--- slot and writes the caption.
	function UiKit.railItem(parent: Instance, name: string, colour: Color3): (TextButton, Frame, TextLabel)
		local b = Instance.new("TextButton")
		b.Name = name
		b.Size = UDim2.fromOffset(RAIL.ItemWidth, RAIL.ItemHeight)
		b.BackgroundColor3 = colour
		b.BackgroundTransparency = 0.1
		b.BorderSizePixel = 0
		b.AutoButtonColor = true
		b.Font = Style.Font.title
		b.Text = ""
		b.Parent = parent
		UiKit.corner(b, 12)

		local slot = Instance.new("Frame")
		slot.Name = "GlyphSlot"
		slot.Size = UDim2.fromOffset(RAIL.GlyphSize, RAIL.GlyphSize)
		slot.Position = UDim2.fromOffset(RAIL.GlyphX, RAIL.GlyphY)
		slot.BackgroundTransparency = 1
		slot.BorderSizePixel = 0
		slot.Parent = b

		local caption = UiKit.text(b, {
			Name = "Caption",
			Size = UDim2.fromOffset(RAIL.BadgeWidth, RAIL.BadgeHeight),
			Position = UDim2.fromOffset(RAIL.Pad, RAIL.BadgeY),
			Font = Style.Font.title,
			Text = "",
			TextSize = RAIL.BadgeTextPx,
			TextColor3 = UiKit.INK,
			TextXAlignment = Enum.TextXAlignment.Center,
		})

		return b, slot, caption
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- fitting the screen
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The one number the whole HUD is scaled by.
	---
	--- MIN OF THE TWO RATIOS, not max and not the width alone. The min is what
	--- guarantees the layer this is mounted on is at least ReferenceWidth x
	--- ReferenceHeight DESIGN pixels at every aspect ratio, which is the property
	--- that makes every UDim2.fromOffset literal in src/client correct by
	--- construction. Max would guarantee neither axis; width alone would guarantee
	--- the wrong one, since it is height that a landscape phone runs out of.
	---
	--- MinScale is the deliberate hole in that guarantee: below it the UI would
	--- shrink past the point of being readable, so it stops shrinking and a very
	--- short screen gets a canvas shorter than the reference instead. That is the
	--- band the shop-versus-column overlap lived in, and it is why the verifier
	--- asserts that layout at the reference height rather than trusting it.
	function UiKit.scaleFor(viewport: Vector2): number
		return math.clamp(
			math.min(viewport.X / UI.ReferenceWidth, viewport.Y / UI.ReferenceHeight),
			UI.MinScale, UI.MaxScale)
	end

	--- invariant: the gutter, in PHYSICAL pixels, the persistent HUD keeps clear on
	--- each edge — notch, home indicator, rounded corners.
	---
	--- Takes no viewport. It took one, to measure a right-hand inset off
	--- GuiService.TopbarInset's far edge; that whole reading is gone — see the note
	--- at the bottom of this function for what it actually measured.
	---
	--- WHAT IS CONFIDENT AND WHAT IS NOT. GuiService:GetGuiInset() returns two
	--- Vector2s and has been stable for years, so it is read directly. Everything
	--- else here is newer surface that a given client may not have, so it is
	--- pcall'd and simply does not contribute when it is missing — the fallback is
	--- the behaviour that shipped, plus SafeAreaPad.
	---
	--- THE TOP IS DELIBERATELY NOT READ. The ScreenGui is built with
	--- IgnoreGuiInset = false, so the engine has ALREADY pushed the whole layer
	--- below the topbar. Adding GetGuiInset().Y on top of that is the classic
	--- double-inset bug and costs 36 design pixels of screen for nothing.
	function UiKit.safeInsets()
		local pad = UI.SafeAreaPad
		local insets = { left = pad, right = pad, top = pad, bottom = pad }

		-- GetGuiInset's two corners answer two different questions.
		--
		-- topLeft.Y is the topbar, which the ScreenGui has ALREADY been pushed below
		-- (see the note above) and which must not be counted twice. topLeft.X is
		-- something else entirely: it is how far in from the left the usable area
		-- starts, which is zero on every desktop and is the DISPLAY CUTOUT on a
		-- notched phone held in landscape. bottomRight is the home indicator, and on
		-- a phone that has one it is the news that matters.
		--
		-- The X terms err outward on purpose. If a client turns out to apply the
		-- side inset to the ScreenGui itself, this double-counts it and the cost is a
		-- gutter one notch too wide — the direction Config.UI.SafeAreaPad's comment
		-- says a guess about a cutout should be wrong in.
		local ok, topLeft, bottomRight = pcall(function()
			return GuiService:GetGuiInset()
		end)
		if ok and typeof(topLeft) == "Vector2" then
			insets.left += math.max(0, topLeft.X)
		end
		if ok and typeof(bottomRight) == "Vector2" then
			insets.right += math.max(0, bottomRight.X)
			insets.bottom += math.max(0, bottomRight.Y)
		end

		-- invariant: GuiService.TopbarInset IS NOT READ, AND THAT IS THE POINT OF
		-- THIS COMMENT.
		--
		-- It was, on the argument that "in landscape on a notched phone its left edge
		-- is pushed in past the notch, which is the only reading of the SIDE safe
		-- area available to a LocalScript":
		--
		--     insets.left = math.max(insets.left, bar.Min.X + pad)
		--
		-- That is not what the Rect measures. TopbarInset is the strip left over for
		-- CUSTOM topbar buttons, so its left edge sits past Roblox's OWN menu and
		-- chat buttons — 165 physical pixels in on the desktop this was found on, and
		-- nothing to do with a notch. Applied as a full-height gutter it pushed the
		-- entire left column 191 px inside the screen, on every device, to clear an
		-- obstruction that lives in a strip `IgnoreGuiInset = false` has already put
		-- the whole layer below. It cost about a sixth of the screen's width and it
		-- looked deliberate.
		--
		-- The notch case it was reaching for is real and is covered twice over: the
		-- ScreenGui asks for Enum.ScreenInsets.CoreUISafeInsets, which is the device
		-- safe area, and topLeft.X above is the same number read a second way. A
		-- top-strip measurement is not a side gutter, and there is no third reading
		-- to go looking for.

		return insets
	end

	return UiKit
end


__MODULES["UpgradeUI"] = function()
	--[[
		UpgradeUI.lua — PROTOTYPE. The shop panel for Config.PlayerUpgrades and the
		utility slot for Config.ShopMath.

		It draws into HUD's own layers (HUD.root()) rather than making a second
		ScreenGui, so the two share a z-order, a UIScale and one ResetOnSpawn.

		The palette and the corner/stroke/panel/text/button helpers this file used
		to keep a local copy of are now src/client/UiKit.lua, which is the fix this
		header asked for when it was written. HUD still doesn't export them —
		nobody's panel builders belong to another panel — they just have an owner
		that is neither of us now.

		The client is a renderer here. It never decides what you own, what a level
		costs or whether a utility is off cooldown; it draws the last UpgradeState
		the server sent and asks for things.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Net = Req("Net")
	local UiKit = Req("UiKit")
	local ShopMath = Req("ShopMath")

	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")

	local UpgradeUI = {}

	local SHOP_ON = Config.Prototypes.PlayerUpgrades
	local UTILITY_ON = Config.Prototypes.Utilities
	local ENABLED = SHOP_ON or UTILITY_ON

	-- Should move to Config alongside the utility rows if this ships. Q is chosen
	-- because 1..9 belong to Roblox's hotbar and E is the ProximityPrompt default.
	local USE_KEY = Enum.KeyCode.Q
	local SEND_THROTTLE = 0.2

	local UI = Config.UI
	local PALETTE = UiKit.PALETTE

	local state = {
		cash = 0,
		-- Nothing is drawn as a real price until the server has spoken once: an
		-- empty costs table and a maxed-out upgrade look identical, and guessing
		-- wrong paints every row "MAX" for the first second of the session.
		received = false,
		levels = {} :: { [string]: number },
		costs = {} :: { [string]: number },
		locked = {} :: { [string]: string },
		equipped = "",
		cooldownTotal = 0,
		-- os.clock() on THIS machine. The server sends seconds-remaining, never a
		-- timestamp, because the two clocks have no relationship to each other.
		readyAt = 0,
	}

	local rows: { [string]: any } = {}
	local panelFrame, toggleButton, chipButton, chipLabel
	local lastSend = 0
	local flashUntil = 0

	-- ─────────────────────────────────────────────────────────────────────────────
	-- builders (UiKit's — see the header)
	-- ─────────────────────────────────────────────────────────────────────────────

	local corner, stroke, panel, text, button =
		UiKit.corner, UiKit.stroke, UiKit.panel, UiKit.text, UiKit.button

	-- ─────────────────────────────────────────────────────────────────────────────
	-- rows
	-- ─────────────────────────────────────────────────────────────────────────────

	local function sectionLabel(parent: Instance, label: string, order: number)
		local holder = Instance.new("Frame")
		holder.BackgroundTransparency = 1
		holder.Size = UDim2.new(1, 0, 0, 22)
		holder.LayoutOrder = order
		holder.Parent = parent

		text(holder, {
			Size = UDim2.fromScale(1, 1),
			Font = Style.Font.body,
			Text = label,
			TextSize = 12,
			TextColor3 = PALETTE.muted,
		})
	end

	--- One row is a single TextButton with labels laid on top, so the whole strip
	--- is the hit target. Tapping a 90px pill on a phone is a coin flip.
	local function buildRow(parent: Instance, id: string, name: string, order: number)
		local row = Instance.new("TextButton")
		row.Name = id
		row.Text = ""
		row.AutoButtonColor = false
		row.BackgroundColor3 = PALETTE.panel2
		row.BackgroundTransparency = 0.25
		row.BorderSizePixel = 0
		row.Size = UDim2.new(1, -6, 0, UI.ShopPanel.RowHeight)   -- -6 leaves the scrollbar its lane
		row.LayoutOrder = order
		row.Parent = parent
		corner(row, 10)
		local edge = stroke(row, PALETTE.accent, 1.5)
		edge.Transparency = 0.7

		local title = text(row, {
			Size = UDim2.new(1, -118, 0, 20),
			Position = UDim2.fromOffset(12, 8),
			Font = Style.Font.title,
			Text = name,
			TextSize = 16,
			TextTruncate = Enum.TextTruncate.AtEnd,
		})

		local blurb = text(row, {
			Size = UDim2.new(1, -118, 0, 28),
			Position = UDim2.fromOffset(12, 28),
			Font = Style.Font.body,
			Text = "",
			TextSize = 12,
			TextColor3 = PALETTE.muted,
			TextWrapped = true,
			TextYAlignment = Enum.TextYAlignment.Top,
		})

		local pill = Instance.new("Frame")
		pill.AnchorPoint = Vector2.new(1, 0.5)
		pill.Position = UDim2.new(1, -10, 0.5, 0)
		pill.Size = UDim2.fromOffset(92, 32)
		pill.BackgroundColor3 = PALETTE.good
		pill.BackgroundTransparency = 0.12
		pill.BorderSizePixel = 0
		pill.Parent = row
		corner(pill, 8)

		local pillLabel = text(pill, {
			Size = UDim2.fromScale(1, 1),
			Font = Style.Font.title,
			Text = "",
			TextSize = 15,
			TextScaled = false,
			TextXAlignment = Enum.TextXAlignment.Center,
			TextColor3 = Color3.fromRGB(20, 16, 28),
		})

		row.Activated:Connect(function()
			Net.event("RequestUpgrade"):FireServer(id)
		end)

		rows[id] = { row = row, title = title, blurb = blurb, pill = pill, pillLabel = pillLabel, edge = edge }
		return rows[id]
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- redraw
	-- ─────────────────────────────────────────────────────────────────────────────

	local function paint(entry, opts)
		entry.blurb.Text = opts.blurb
		entry.title.Text = opts.title
		entry.title.TextColor3 = opts.dim and PALETTE.muted or PALETTE.text
		entry.pill.BackgroundColor3 = opts.pillColor
		entry.pillLabel.Text = opts.pillText
		entry.pillLabel.TextColor3 = opts.pillTextColor or Color3.fromRGB(20, 16, 28)
		entry.row.BackgroundTransparency = opts.dim and 0.55 or 0.25
		entry.edge.Transparency = opts.dim and 0.9 or 0.7
	end

	local function paintPending(entry, name: string)
		paint(entry, {
			title = name,
			blurb = "…",
			pillText = "…",
			pillColor = PALETTE.dead,
			pillTextColor = PALETTE.muted,
			dim = true,
		})
	end

	local function refreshUpgrades()
		for _, def in ipairs(Config.PlayerUpgrades) do
			local entry = rows[def.id]
			if entry and not state.received then
				paintPending(entry, def.name)
			elseif entry then
				local level = state.levels[def.id] or 0
				local cost = state.costs[def.id]
				local maxed = cost == nil
				local affordable = not maxed and state.cash >= (cost or 0)

				paint(entry, {
					title = ("%s  <font color=\"#8f86a8\">Lv %d/%d</font>"):format(def.name, level, def.levels),
					-- the CURRENT effect, then what the next level moves it to: a
					-- price with no delta doesn't tell you whether to buy
					blurb = maxed and ShopMath.describe(def, level)
						or ("%s  →  %s"):format(
							ShopMath.describe(def, level),
							ShopMath.formatValue(ShopMath.valueAt(def, level + 1))),
					pillText = maxed and "MAX" or Util.abbreviate(cost or 0),
					pillColor = maxed and PALETTE.accent or (affordable and PALETTE.good or PALETTE.dead),
					pillTextColor = (not maxed and not affordable) and PALETTE.muted or nil,
					dim = not maxed and not affordable,
				})
			end
		end
	end

	local function refreshUtilities()
		for _, def in ipairs(Config.Utilities) do
			local entry = rows[def.id]
			if entry and not state.received then
				paintPending(entry, def.name)
			elseif entry then
				local owned = (state.levels[def.id] or 0) >= 1
				local lockedBy = state.locked[def.id]
				local equipped = state.equipped == def.id
				local affordable = state.cash >= def.price

				local pillText, pillColor, dim
				if equipped then
					pillText, pillColor, dim = "EQUIPPED", PALETTE.accent, false
				elseif owned then
					pillText, pillColor, dim = "EQUIP", PALETTE.gold, false
				elseif lockedBy then
					pillText, pillColor, dim = "LOCKED", PALETTE.dead, true
				else
					pillText = Util.abbreviate(def.price)
					pillColor = affordable and PALETTE.good or PALETTE.dead
					dim = not affordable
				end

				paint(entry, {
					title = ("%s  <font color=\"#8f86a8\">%ds cd</font>"):format(def.name, def.cooldown),
					blurb = lockedBy and ("Needs %s."):format(lockedBy) or ShopMath.verbBlurb(def),
					pillText = pillText,
					pillColor = pillColor,
					pillTextColor = dim and PALETTE.muted or nil,
					dim = dim,
				})
			end
		end
	end

	local function refresh()
		if SHOP_ON then
			refreshUpgrades()
		end
		if UTILITY_ON then
			refreshUtilities()
		end
	end

	--- The chip is both the readout and the touch button for the utility, so a
	--- phone player never needs a keyboard. Desktop gets the same thing plus Q.
	local function refreshChip()
		if not chipButton then
			return
		end
		if state.equipped == "" then
			chipButton.Visible = false
			return
		end
		chipButton.Visible = true

		local def = ShopMath.UtilityById[state.equipped]
		local remaining = math.max(0, state.readyAt - os.clock())
		if os.clock() < flashUntil then
			-- a mistimed press reads as "not yet" rather than as a dropped input
			chipButton.BackgroundColor3 = PALETTE.bad
			chipLabel.Text = ("%.0fs"):format(math.ceil(remaining))
			chipLabel.TextColor3 = Color3.fromRGB(30, 12, 12)
		elseif remaining > 0 then
			chipButton.BackgroundColor3 = PALETTE.dead
			chipLabel.Text = ("%s  •  %.0fs"):format(def and def.name or "?", math.ceil(remaining))
			chipLabel.TextColor3 = PALETTE.muted
		else
			chipButton.BackgroundColor3 = PALETTE.accent
			chipLabel.Text = ("Q   %s"):format(def and def.name or "?")
			chipLabel.TextColor3 = Color3.fromRGB(20, 16, 28)
		end
	end

	local function fireUtility()
		if not UTILITY_ON or state.equipped == "" then
			return
		end
		local now = os.clock()
		-- Local gates only stop us spamming the wire; the server owns the real
		-- cooldown and will refuse anything early regardless.
		if now < state.readyAt or now - lastSend < SEND_THROTTLE then
			flashUntil = now + 0.25
			refreshChip()
			return
		end
		lastSend = now
		Net.event("UseUtility"):FireServer()
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- construction
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The shop's own column, one gap clear of HUD's left column.
	---
	--- IT USED TO SHARE THAT COLUMN, and that was a real bug rather than a tight
	--- fit. The panel is bottom-anchored and proportionally tall, so on a short
	--- screen it grows UPWARDS into whatever is above it: below 638 design pixels
	--- it covered the NEXT UPGRADE panel, and with the utility chip on it did so at
	--- the 720 reference height. Neither file could see the collision, because HUD
	--- held the bottom edge of the column and this one held the top edge of the
	--- shop. Both numbers are Config.UI now, X is derived from the column's width,
	--- and tools/verify_config.lua asserts the two clear each other on one axis or
	--- the other — which holds at every viewport height rather than at the one it
	--- was eyeballed on.
	local function buildPanel(parent: Instance)
		local anchorY = UTILITY_ON and UI.ShopPanel.BottomGap or UI.ShopPanel.BottomGapNoUtility

		panelFrame = panel(parent,
			UDim2.new(0, UI.ShopPanel.Width, UI.ShopPanel.HeightScale, 0),
			UDim2.new(0, UI.ShopPanel.X, 1, -anchorY), Vector2.new(0, 1))
		panelFrame.Name = "UpgradeShop"
		panelFrame.Visible = false

		local sizeLimit = Instance.new("UISizeConstraint")
		sizeLimit.MaxSize = Vector2.new(UI.ShopPanel.Width, UI.ShopPanel.MaxHeight)
		sizeLimit.MinSize = Vector2.new(UI.ShopPanel.Width, UI.ShopPanel.MinHeight)
		sizeLimit.Parent = panelFrame

		text(panelFrame, {
			Size = UDim2.new(1, -28, 0, 26),
			Position = UDim2.fromOffset(14, 10),
			Font = Style.Font.title,
			Text = "TUNG UPGRADES",
			TextSize = 20,
			TextColor3 = PALETTE.accent,
		})

		local scroll = Instance.new("ScrollingFrame")
		scroll.Name = "List"
		scroll.BackgroundTransparency = 1
		scroll.BorderSizePixel = 0
		scroll.Position = UDim2.fromOffset(14, 42)
		scroll.Size = UDim2.new(1, -28, 1, -56)
		scroll.CanvasSize = UDim2.new()
		scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
		-- XY is the default and lets a row that is one pixel too wide start
		-- scrolling sideways, which looks like a bug rather than like a list
		scroll.ScrollingDirection = Enum.ScrollingDirection.Y
		scroll.ScrollBarThickness = 4
		scroll.ScrollBarImageColor3 = PALETTE.accent
		scroll.Parent = panelFrame

		local layout = Instance.new("UIListLayout")
		layout.Padding = UDim.new(0, 8)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = scroll

		local order = 0
		if SHOP_ON then
			order += 1
			sectionLabel(scroll, "PLAYER UPGRADES", order)
			for _, def in ipairs(Config.PlayerUpgrades) do
				order += 1
				buildRow(scroll, def.id, def.name, order)
			end
		end
		if UTILITY_ON then
			order += 1
			sectionLabel(scroll, "UTILITY SLOT  •  ONE EQUIPPED", order)
			for _, def in ipairs(Config.Utilities) do
				order += 1
				buildRow(scroll, def.id, def.name, order)
			end
		end
	end

	local function buildToggle(parent: Instance)
		toggleButton = button(parent, "UPGRADES", PALETTE.accent, {
			Name = "UpgradeToggle",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, UI.ShopPanel.X, 1, -UI.Margin),
			Size = UDim2.fromOffset(UI.Action.Width, UI.Button.pill),
			TextSize = 18,
		})
		toggleButton.Activated:Connect(function()
			panelFrame.Visible = not panelFrame.Visible
			if panelFrame.Visible then
				refresh()
			end
		end)
	end

	local function buildChip(parent: Instance)
		chipButton = button(parent, "", PALETTE.accent, {
			Name = "UtilityChip",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, UI.ShopPanel.X, 1, -UI.ShopPanel.BottomGapNoUtility),
			Size = UDim2.fromOffset(UI.Action.Width, UI.Button.pill),
			Visible = false,
		})
		chipLabel = text(chipButton, {
			Size = UDim2.fromScale(1, 1),
			Font = Style.Font.title,
			Text = "",
			TextSize = 16,
			TextXAlignment = Enum.TextXAlignment.Center,
			TextColor3 = Color3.fromRGB(20, 16, 28),
		})
		chipButton.Activated:Connect(fireUtility)
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	function UpgradeUI.start()
		if not ENABLED then
			return
		end

		local HUD = Req("HUD")
		local root = HUD.root()
		if not root then
			-- Main.client calls HUD.start() first, so this only fires if that order
			-- changes; better a warning than a silent half-built shop.
			warn("[Tung] UpgradeUI: HUD.root() is nil, shop not built")
			return
		end

		buildPanel(root)
		if UTILITY_ON then
			buildChip(root)
		end
		buildToggle(root)

		Net.event("UpgradeState").OnClientEvent:Connect(function(payload)
			if typeof(payload) ~= "table" then
				return
			end
			state.received = true
			state.levels = payload.levels or {}
			state.costs = payload.costs or {}
			state.locked = payload.locked or {}
			state.equipped = payload.equipped or ""
			state.cooldownTotal = payload.cooldownTotal or 0
			state.readyAt = os.clock() + (payload.cooldown or 0)
			refresh()
			refreshChip()
		end)

		-- Cash comes from the same broadcast HUD reads; a second listener on one
		-- RemoteEvent is free and beats coupling the two panels together.
		Net.event("Stats").OnClientEvent:Connect(function(payload)
			if typeof(payload) ~= "table" then
				return
			end
			local cash = payload.cash or 0
			if cash ~= state.cash then
				state.cash = cash
				if panelFrame and panelFrame.Visible then
					refresh()
				end
			end
		end)

		-- The server pushes state as soon as the profile loads, which can land
		-- before this LocalScript has connected its handler — a RemoteEvent fired
		-- at a client with no listener is simply gone, there is no replay. So ask
		-- for it. An id the server doesn't recognise buys nothing and still gets a
		-- push back, which makes RequestUpgrade("") a resync with no new remote.
		task.spawn(function()
			for _ = 1, 6 do
				if state.received then
					return
				end
				Net.event("RequestUpgrade"):FireServer("")
				task.wait(1.5)
			end
		end)

		if UTILITY_ON then
			UserInputService.InputBegan:Connect(function(input, processed)
				-- processed = the player is typing in the chat box
				if not processed and input.KeyCode == USE_KEY then
					fireUtility()
				end
			end)

			-- Only the cooldown readout needs a clock, and only ~10x a second.
			local accumulator = 0
			RunService.Heartbeat:Connect(function(dt)
				accumulator += dt
				if accumulator < 0.1 then
					return
				end
				accumulator = 0
				if chipButton and chipButton.Visible then
					refreshChip()
				end
			end)
		end

		refresh()
	end

	return UpgradeUI
end


-- ── entry point ───────────────────────────────────────────────


--[[ Main.client.lua — client entry point. ]]

local Req = __Req
local Net = Req("Net")
local Util = Req("Util")

local HUD = Req("HUD")
local CombatClient = Req("CombatClient")
local UpgradeUI = Req("UpgradeUI")
local SessionUI = Req("SessionUI")

-- The default Backpack CoreGui stays ON: the bat is an ordinary Tool, so
-- Roblox's own hotbar and inventory handle equipping it.
HUD.start()
CombatClient.start()

-- Prototype panels. Both return immediately unless their Config.Prototypes
-- flag is on.
UpgradeUI.start()
SessionUI.start()

-- THE ONE THING THE SERVER CANNOT WORK OUT FOR ITSELF.
--
-- Roblox has no server-side device API, so the analytics layer's platform label
-- has to come from here. Fired ONCE, immediately: the server holds the session's
-- three join events open waiting for it and gives up after ten seconds, because
-- a logged event cannot be edited afterwards.
--
-- The ladder is Util.platformFrom and the ORDER inside it is the whole point —
-- a VR headset and a console can both report TouchEnabled, so asking touch first
-- files every headset in the game under "mobile" and the chart looks fine. The
-- server re-validates whatever this sends against the declared set, because a
-- client can say anything; nothing in the game is gated on the answer.
task.spawn(function()
	local UIS = game:GetService("UserInputService")
	local GuiService = game:GetService("GuiService")

	local tenFoot = false
	pcall(function()
		tenFoot = GuiService:IsTenFootInterface()
	end)

	local viewportX = 0
	local camera = workspace.CurrentCamera
	if camera then
		viewportX = camera.ViewportSize.X
	end

	Net.event("ClientHello"):FireServer({
		platform = Util.platformFrom({
			vr = UIS.VREnabled,
			tenFoot = tenFoot,
			touch = UIS.TouchEnabled,
			keyboard = UIS.KeyboardEnabled,
			mouse = UIS.MouseEnabled,
			viewportX = viewportX,
		}),
	})
end)

print("[Tung] client ready")
